INSERT INTO `tours` VALUES
(1,1,2,'Đà Nẵng - Bán Đảo Sơn Trà - Phố Cổ Hội An - Bà Nà Hills 4N3Đ','Khám phá miền di sản tuyệt đẹp: ngắm toàn cảnh Đà Nẵng từ Sơn Trà, check-in Cầu Vàng nổi tiếng thế giới tại Sun World Ba Na Hills, và thả đèn hoa đăng lung linh trên sông Hoài Phố cổ Hội An.',4890000.00,4,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?w=800',350,'2026-10-21','2026-10-25','ACTIVE',4.9,5890000.00,'Máy bay khứ hồi Vietnam Airlines & Xe Universe 45 chỗ đời mới',4,'BÁN CHẠY NHẤT','[\"Check-in Cầu Vàng lừng danh thế giới trên đỉnh Bà Nà Hills\", \"Du ngoạn phố cổ Hội An về đêm ngắm đèn lồng và thả hoa đăng sông Hoài\", \"Tắm biển Mỹ Khê - một trong những bãi biển quyến rũ nhất hành tinh\", \"Thưởng thức đặc sản mì Quảng, bánh tráng cuốn thịt heo hai đầu da\"]','[{\"day\": 1, \"title\": \"TP.HCM / Hà Nội - Đà Nẵng - Bán Đảo Sơn Trà\", \"content\": \"Đáp chuyến bay đến Đà Nẵng. Xe đón đoàn viếng Chùa Linh Ứng Bãi Bụt, chiêm ngưỡng tượng Phật Bà Quan Âm 67m cao nhất Việt Nam. Chiều tự do tắm biển Mỹ Khê.\"}, {\"day\": 2, \"title\": \"KDL Sun World Ba Na Hills - Check-in Cầu Vàng\", \"content\": \"Trải nghiệm cáp treo đạt 4 kỷ lục thế giới. Check-in Cầu Vàng bàn tay khổng lồ, Làng Pháp cổ kính, Hầm rượu Debay, Vườn hoa Le Jardin D\'Amour và Fantasy Park.\"}, {\"day\": 3, \"title\": \"Ngũ Hành Sơn - Làng Đá Non Nước - Đô Thị Cổ Hội An\", \"content\": \"Khám phá quần thể hang động Ngũ Hành Sơn. Chiều di chuyển về Phố Cổ Hội An: Chùa Cầu Nhật Bản, Nhà cổ Phùng Hưng, Hội quán Phúc Kiến. Ăn tối ẩm thực phố cổ.\"}, {\"day\": 4, \"title\": \"Chợ Hàn Mua Sắm Đặc Sản - Tiễn Sân Bay\", \"content\": \"Ghé Chợ Hàn mua sắm chả bò Đà Nẵng, mực một nắng, bánh khô mè. Xe đưa đoàn ra sân bay Đà Nẵng đáp chuyến bay về lại điểm đón ban đầu.\"}]','[\"Vé máy bay khứ hồi bao gồm 20kg hành lý ký gửi + 7kg xách tay\", \"Khách sạn 4 sao tiêu chuẩn quốc tế gần biển Mỹ Khê (2 khách/phòng)\", \"Xe du lịch đời mới Universe máy lạnh đón tiễn theo lịch trình\", \"Vé cáp treo và buffet trưa thượng hạng tại Bà Nà Hills\", \"Bảo hiểm du lịch nội địa mức bồi thường 100.000.000 VNĐ/khách\"]','[\"Chi phí cá nhân ngoài chương trình (giặt ủi, đồ uống minibar)\", \"Vé tham quan Bảo tàng Tượng sáp Bà Nà Hills\", \"Thuế VAT 8% (nếu xuất hóa đơn đỏ)\", \"Tiền bồi dưỡng cho Hướng dẫn viên và Tài xế\"]','2026-10-21 07:52:31'),
(2,1,3,'Phú Quốc - Thành Phố Không Ngủ Grand World - Safari - Sunset Town 3N2Đ','Trải nghiệm kỳ nghỉ đảo ngọc thượng lưu: dạo thuyền Gondola sông Venice tại Grand World, khám phá thế giới động vật bán hoang dã Vinpearl Safari, check-in Cầu Hôn Kiss Bridge trứ danh.',5650000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800',420,'2026-10-21','2026-10-24','ACTIVE',5.0,6890000.00,'Máy bay khứ hồi Bamboo Airways & Xe du lịch cao cấp',5,'5 SAO CAO CẤP','[\"Khám phá Vinpearl Safari - công viên chăm sóc động vật bán hoang dã lớn nhất VN\", \"Thưởng lãm show diễn triệu đô \'Sắc Màu Venice\' và \'Tinh Hoa Việt Nam\'\", \"Check-in Thị trấn Hoàng Hôn Sunset Town và Cầu Hôn Kiss Bridge biểu tượng\", \"Thưởng thức hải sản tươi sống tại Làng chài Hàm Ninh và Chợ đêm Phú Quốc\"]','[{\"day\": 1, \"title\": \"TP.HCM - Phú Quốc - Grand World - Show Sắc Màu Venice\", \"content\": \"Bay đến Phú Quốc. Nhận phòng resort 5 sao biển Bãi Dài. Khám phá thành phố không ngủ Grand World, du ngoạn kênh đào Venice, xem show nhạc nước ánh sáng đỉnh cao.\"}, {\"day\": 2, \"title\": \"Vinpearl Safari - Sunset Town - Cầu Hôn Kiss Bridge\", \"content\": \"Sáng tham quan Vinpearl Safari bằng xe chuyên dụng. Chiều di chuyển về Nam đảo check-in Thị trấn Hoàng Hôn Sunset Town, ngắm hoàng hôn rực rỡ tại Cầu Hôn.\"}, {\"day\": 3, \"title\": \"Cơ Sở Ngọc Trai - Nước Mắm Truyền Thống - Tiễn Sân Bay\", \"content\": \"Tham quan cơ sở nuôi cấy ngọc trai Phú Quốc và nhà thùng nước mắm truyền thống Khải Hoàn. Xe đưa đoàn ra sân bay Phú Quốc về lại TP.HCM.\"}]','[\"Vé máy bay khứ hồi Phú Quốc có 20kg hành lý\", \"Resort 5 sao Vinpearl / Mövenpick bao gồm buffet sáng chuẩn quốc tế\", \"Vé vào cổng Vinpearl Safari và Grand World Phú Quốc\", \"Bữa tối hải sản ghẹ Hàm Ninh tươi ngon\", \"Hướng dẫn viên nhiệt tình suốt hành trình\"]','[\"Vé cáp treo Hòn Thơm Sun World\", \"Show diễn Tinh Hoa Việt Nam (ban đêm)\", \"Chi phí cá nhân ngoài chương trình\", \"Phụ thu phòng đơn nếu đi 1 mình\"]','2026-10-21 07:52:31'),
(3,1,4,'Nha Trang - VinWonders - Du Ngoạn 3 Đảo Vịnh San Hô - Tắm Khoáng 4N3Đ','Chiêm ngưỡng vịnh biển đẹp bậc nhất thế giới Nha Trang: vui chơi thỏa thích tại công viên giải trí VinWonders Hòn Tre, lặn ngắm san hô Vịnh San Hô, tắm bùn khoáng nóng I-Resort phục hồi sức khỏe.',3990000.00,4,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800',380,'2026-10-21','2026-10-25','ACTIVE',4.8,4890000.00,'Xe giường nằm VIP Limousine hoặc Máy bay',4,'ƯU ĐÃI ĐOÀN B2B','[\"Vui chơi trọn ngày tại VinWonders Nha Trang với Tata Show hoành tráng\", \"Cano cao tốc lướt sóng tham quan 3 đảo: Hòn Mun, Bãi Tranh, Làng Chài\", \"Thư giãn tắm bùn khoáng nóng thiên nhiên I-Resort trị liệu sức khỏe\", \"Thưởng thức buffet hải sản tôm hùm, cá nướng và nem nướng Ninh Hòa\"]','[{\"day\": 1, \"title\": \"Khởi Hành Đi Nha Trang - Nhận Phòng Khách Sạn 4 Sao\", \"content\": \"Xe đón đoàn di chuyển theo cao tốc Dầu Giây - Cam Lâm về phố biển Nha Trang. Tối tự do dạo phố biển Trần Phú và chợ đêm.\"}, {\"day\": 2, \"title\": \"Thiên Đường Giải Trí VinWonders Nha Trang\", \"content\": \"Qua đảo Hòn Tre trải nghiệm vòng quay bánh xe bầu trời, thủy cung Sea World, vịnh phao nổi lớn nhất thế giới và thưởng thức Tata Show triệu đô.\"}, {\"day\": 3, \"title\": \"Cano Du Ngoạn 3 Đảo - Bãi Tranh - Vịnh San Hô\", \"content\": \"Cano đưa quý khách lặn ngắm rạn san hô Bãi Tranh, dùng bữa trưa trên bè nổi hải sản Làng Chài. Chiều tắm bùn khoáng I-Resort.\"}, {\"day\": 4, \"title\": \"Tháp Bà Ponagar - Chùa Long Sơn - Khởi Hành Về\", \"content\": \"Viếng Chùa Long Sơn tượng Phật Trắng, tham quan quần thể kiến trúc Chăm Pa Tháp Bà Ponagar. Khởi hành về điểm đón ban đầu.\"}]','[\"Xe vận chuyển Universe / Limousine chất lượng cao suốt tuyến\", \"Khách sạn 4 sao sát biển mặt đường Trần Phú\", \"Vé cáp treo và trọn gói trò chơi VinWonders Hòn Tre\", \"Vé cano cao tốc và lặn ống thở ngắm san hô\", \"Bảo hiểm du lịch trọn tour\"]','[\"Dịch vụ lặn biển bằng bình dưỡng khí / dù bay cano\", \"Chi phí cá nhân minibar khách sạn\", \"Tiền tip tài xế và hướng dẫn viên\"]','2026-10-21 07:52:31'),
(4,1,2,'Quy Nhơn - Kỳ Co - Eo Gió - Hòn Khô - Tháp Đôi Huyền Bí 3N2Đ','Chiêm ngưỡng vẻ đẹp hoang sơ kỳ vĩ của \'Maldives phiên bản Việt\': lặn biển ngắm san hô Kỳ Co, ngắm hoàng hôn Eo Gió tuyệt sắc và khám phá ẩm thực đất võ Bình Định trứ danh.',4250000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?w=800',300,'2026-10-21','2026-10-24','ACTIVE',4.8,5100000.00,'Máy bay khứ hồi & Xe du lịch đời mới',4,'GIÁ TỐT TRAVELOKA','[\"Chinh phục con đường ven biển đẹp ngỡ ngàng tại Eo Gió\", \"Tắm biển và lặn ngắm san hô tự nhiên tại bãi Kỳ Co nước xanh màu ngọc bích\", \"Check-in cây cầu gỗ bắt ngang biển siêu ảo tại Hòn Khô\", \"Thưởng thức bánh hỏi lòng heo, nem Chợ Huyện và hải sản tươi sống\"]','[{\"day\": 1, \"title\": \"Sân Bay Phù Cát - Tháp Đôi - Ghềnh Ráng Tiên Sa\", \"content\": \"Đón sân bay Phù Cát. Tham quan Ghềnh Ráng Tiên Sa, viếng mộ thi sĩ Hàn Mặc Tử, Bãi Trứng (Bãi tắm Hoàng Hậu). Check-in Tháp Đôi Chăm Pa.\"}, {\"day\": 2, \"title\": \"Cano Đi Bãi Tắm Kỳ Co - Lặn San Hô - Eo Gió\", \"content\": \"Vượt Cầu Thị Nại sang bán đảo Phương Mai. Đi cano lướt sóng sang Kỳ Co tắm biển. Lặn ngắm san hô Hòn Sẹo. Chiều dạo bước ngắm hoàng hôn tuyệt đẹp tại Eo Gió.\"}, {\"day\": 3, \"title\": \"Đảo Hòn Khô - Mua Sắm Đặc Sản - Tiễn Bay\", \"content\": \"Đi thuyền sang Đảo Hòn Khô chụp ảnh cầu gỗ ven biển. Trưa thưởng thức bánh xèo tôm nhảy rau mầm. Tiễn sân bay Phù Cát.\"}]','[\"Vé máy bay khứ hồi có 20kg ký gửi\", \"Khách sạn 4 sao trung tâm TP Quy Nhơn view biển\", \"Cano cao tốc đưa đón Kỳ Co bao gồm áo phao, kính lặn\", \"Vé vào cổng Eo Gió và Ghềnh Ráng Tiên Sa\"]','[\"Chi phí cá nhân\", \"Đồ uống phát sinh ngoài thực đơn\", \"VAT\"]','2026-10-21 07:52:31'),
(5,1,3,'Côn Đảo Huyền Thoại - Viếng Mộ Cô Sáu - Nghỉ Dưỡng Biển Xanh 3N2Đ','Hành trình linh thiêng và thanh bình: dâng hương viếng Nghĩa trang Hàng Dương mộ nữ anh hùng Võ Thị Sáu vào ban đêm, khám phá hệ thống Nhà tù Côn Đảo và bãi biển Đầm Trầu hoang sơ.',7200000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',250,'2026-10-21','2026-10-24','ACTIVE',5.0,8500000.00,'Máy bay khứ hồi ATR72 / Embraer VASCO',4,'LINH THIÊNG','[\"Lễ viếng mộ nữ anh hùng liệt sĩ Võ Thị Sáu linh thiêng tại Nghĩa trang Hàng Dương\", \"Tìm hiểu lịch sử hào hùng qua di tích Chuồng Cọp Pháp - Mỹ\", \"Tắm biển bãi Đầm Trầu ngắm máy bay hạ cánh sát bãi cát\", \"Hít thở không khí nguyên sinh trong lành của Vườn Quốc Gia Côn Đảo\"]','[{\"day\": 1, \"title\": \"Bay Đến Côn Đảo - Bãi Nhát - Đỉnh Tình Yêu\", \"content\": \"Đáp máy bay xuống sân bay Cỏ Ống. Xe đưa đoàn về thị trấn, dừng chân ngắm cảnh Đỉnh Tình Yêu, Mũi Cá Mập. 23h00 tham gia lễ viếng mộ Cô Sáu tại Nghĩa Trang Hàng Dương.\"}, {\"day\": 2, \"title\": \"Di Tích Lịch Sử Nhà Tù - Bãi Đầm Trầu\", \"content\": \"Tham quan Trại giam Phú Hải, Trại Phú Tường (Chuồng Cọp Pháp), Chuồng Cọp Mỹ. Chiều đến Bãi Đầm Trầu tắm biển và ngắm máy bay cất hạ cánh cự ly gần.\"}, {\"day\": 3, \"title\": \"Chợ Côn Đảo Mua Hạt Bàng - Tiễn Sân Bay\", \"content\": \"Mua đặc sản mứt hạt bàng rang muối, cá thu một nắng. Xe tiễn đoàn ra sân bay Cỏ Ống đáp chuyến bay về TP.HCM.\"}]','[\"Vé máy bay khứ hồi Sài Gòn - Côn Đảo\", \"Khách sạn 4 sao The Secret Con Dao hoặc Marina Hotel\", \"Xe đưa đón viếng mộ Cô Sáu ban đêm\", \"Lễ vật dâng hương nghĩa trang chuẩn bị chu đáo\"]','[\"Chi phí cá nhân\", \"Bia nước ngọt trong các bữa ăn\", \"Tiền tip tổ phục vụ\"]','2026-10-21 07:52:31'),
(6,2,2,'Sa Pa - Chinh Phục Đỉnh Fansipan Nóc Nhà Đông Dương - Bản Cát Cát 3N2Đ','Chiêm ngưỡng vẻ đẹp huyền ảo của thị trấn trong sương: cáp treo vượt biển mây chinh phục đỉnh Fansipan 3.143m, dạo bước bản Cát Cát của người H\'Mông và thưởng thức lẩu cá hồi Tây Bắc.',3650000.00,3,'Hà Nội','https://images.unsplash.com/photo-1528127269322-539801943592?w=800',350,'2026-10-21','2026-10-24','ACTIVE',4.9,4500000.00,'Xe Limousine giường nằm cao cấp khứ hồi Hà Nội - Sa Pa',4,'BÁN CHẠY NHẤT','[\"Chinh phục đỉnh Fansipan 3.143m ngắm toàn cảnh dãy Hoàng Liên Sơn hùng vĩ\", \"Check-in Đại tượng Phật A Di Đà bằng đồng lớn nhất Đông Nam Á\", \"Dạo bước bản Cát Cát xem guồng nước, suối Hoa và cầu Si mộng mơ\", \"Thưởng thức mẹt lợn bản cắp nách, thắng cố và lẩu cá tầm Sa Pa\"]','[{\"day\": 1, \"title\": \"Hà Nội - Cao Tốc Nội Bài Lào Cai - Sa Pa - Bản Cát Cát\", \"content\": \"Xe Limousine đón tại phố cổ Hà Nội chạy cao tốc lên Sa Pa. Nhận phòng khách sạn 4 sao. Chiều bách bộ khám phá Bản Cát Cát của người H\'Mông.\"}, {\"day\": 2, \"title\": \"Chinh Phục Đỉnh Fansipan - Moana Sống Ảo\", \"content\": \"Trải nghiệm cáp treo Fansipan 3 dây vượt thung lũng Mường Hoa. Chạm tay vào cột mốc Fansipan 3.143m. Chiều check-in khu sinh thái Moana view núi non.\"}, {\"day\": 3, \"title\": \"Nhà Thờ Đá Sa Pa - Chợ Sa Pa - Trở Về Hà Nội\", \"content\": \"Bách bộ chụp ảnh Nhà thờ Đá cổ thời Pháp, mua sắm thảo dược, thịt trâu gác bếp tại chợ Sa Pa. Chiều xe đưa đoàn về lại trung tâm Hà Nội.\"}]','[\"Xe Limousine VIP khứ hồi Hà Nội - Sa Pa - Hà Nội\", \"Khách sạn 4 sao trung tâm có bể bơi nước ấm view núi Fansipan\", \"Vé cáp treo Sun World Fansipan Legend\", \"Vé tham quan Bản Cát Cát và Moana Sa Pa\"]','[\"Vé tàu hỏa leo núi Mường Hoa / đỉnh Fansipan\", \"Chi phí trang phục chụp ảnh dân tộc\", \"Chi phí cá nhân ngoài thực đơn\"]','2026-10-21 07:52:31'),
(7,2,3,'Hà Giang - Cao Nguyên Đá Đồng Văn - Đèo Mã Pí Lèng - Hẻm Tu Sản 4N3Đ','Hành trình nghẹt thở qua cung đường đèo đẹp nhất Việt Nam: chinh phục Mã Pí Lèng, ngồi thuyền xuôi dòng sông Nho Quế ngắm hẻm vực Tu Sản sâu nhất Đông Nam Á, ghé Dinh Vua Mèo cổ kính.',4450000.00,4,'Hà Nội','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',280,'2026-10-21','2026-10-25','ACTIVE',5.0,5400000.00,'Xe du lịch Universe 29-45 chỗ tài xế chuyên nghiệp cung đường đèo',3,'HOT TUẦN NÀY','[\"Đi thuyền trên dòng sông Nho Quế màu xanh ngọc bích qua Hẻm Tu Sản\", \"Chinh phục Đèo Mã Pí Lèng - một trong \'Tứ đại đỉnh đèo\' hùng vĩ của VN\", \"Check-in Cột cờ Lũng Cú - điểm cực Bắc địa đầu Tổ quốc thiêng liêng\", \"Thăm Dinh thự Vua Mèo Vương Chính Đức và Phố cổ Đồng Văn\"]','[{\"day\": 1, \"title\": \"Hà Nội - TP. Hà Giang - Cổng Trời Quản Bạ - Núi Đôi Cô Tiên\", \"content\": \"Xe đón khởi hành từ Hà Nội. Dừng chân check-in Cột mốc Km0 Hà Giang. Vượt Dốc Bắc Sum lên Cổng Trời Quản Bạ ngắm Núi Đôi Cô Tiên. Nghỉ đêm tại Yên Minh.\"}, {\"day\": 2, \"title\": \"Dốc Thẩm Mã - Làng Lũng Cẩm - Dinh Vua Mèo - Cột Cờ Lũng Cú\", \"content\": \"Vượt Dốc Thẩm Mã uốn lượn. Ghé thăm Làng Lũng Cẩm (bối cảnh phim Chuyện Của Pao). Thăm Dinh Thự Họ Vương. Chinh phục Cột cờ Quốc gia Lũng Cú.\"}, {\"day\": 3, \"title\": \"Đèo Mã Pí Lèng - Du Thuyền Sông Nho Quế Hẻm Tu Sản - Mèo Vạc\", \"content\": \"Bách bộ trên Con đường Hạnh Phúc vượt Đèo Mã Pí Lèng. Xuống bến thuyền sông Nho Quế du ngoạn Hẻm Tu Sản kỳ vĩ. Nghỉ đêm tại Đồng Văn.\"}, {\"day\": 4, \"title\": \"Chợ Phiên Đồng Văn - TP. Hà Giang - Trở Về Hà Nội\", \"content\": \"Trải nghiệm sắc màu chợ phiên vùng cao Đồng Văn buổi sáng. Ăn trưa tại TP Hà Giang. Khởi hành về đến Hà Nội lúc 20h00.\"}]','[\"Xe vận chuyển chuyên cung đường đèo suốt hành trình\", \"Khách sạn / Homestay tiêu chuẩn sạch đẹp có điều hòa nóng lạnh\", \"Vé tham quan Cột cờ Lũng Cú, Dinh Vua Mèo, Làng Pao\", \"Thuyền tham quan sông Nho Quế và Hẻm Tu Sản\"]','[\"Chi phí cá nhân\", \"Đồ uống rượu ngô trong các bữa ăn\", \"Tip cho tổ phục vụ\"]','2026-10-21 07:52:31'),
(8,2,4,'Mù Cang Chải - Mùa Lúa Chín Vàng Mâm Xôi - Đèo Khau Phạ 3N2Đ','Chiêm ngưỡng kiệt tác ruộng bậc thang kỳ vĩ được công nhận Di tích quốc gia đặc biệt: đồi Mâm Xôi, đồi Móng Ngựa, ngắm dù lượn bay lượn trên đèo Khau Phạ bạt ngàn.',2950000.00,3,'Hà Nội','https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=800',250,'2026-10-21','2026-10-24','ACTIVE',4.8,3700000.00,'Xe du lịch đời mới máy lạnh êm ái',3,'MÙA ĐẸP NHẤT','[\"Check-in Đồi Mâm Xôi và Đồi Móng Ngựa vàng óng mùa lúa chín\", \"Chinh phục Đèo Khau Phạ - nơi diễn ra lễ hội dù lượn Bay Trên Mùa Vàng\", \"Tắm suối khoáng nóng tự nhiên Trạm Tấu phục hồi thể lực\", \"Thưởng thức xôi nếp Tú Lệ dẻo thơm nức tiếng\"]','[{\"day\": 1, \"title\": \"Hà Nội - Nghĩa Lộ - Suối Khoáng Nóng Trạm Tấu\", \"content\": \"Khởi hành từ Hà Nội qua vùng chè Thanh Sơn Phú Thọ. Đến Nghĩa Lộ nhận phòng, tắm khoáng nóng thư giãn tại Trạm Tấu thiên đường.\"}, {\"day\": 2, \"title\": \"Đèo Khau Phạ - Đồi Mâm Xôi - Thị Trấn Mù Cang Chải\", \"content\": \"Vượt Đèo Khau Phạ ngắm thung lũng Cao Phạ. Lên đồi Mâm Xôi La Pán Tẩn chụp ảnh ruộng bậc thang rực rỡ sắc vàng. Chiều săn hoàng hôn đồi Móng Ngựa.\"}, {\"day\": 3, \"title\": \"Tú Lệ Mua Cốm Nếp - Hà Nội\", \"content\": \"Ghé thung lũng Tú Lệ mua cốm xanh nếp tan, gạo Séng Cù dẻo thơm. Khởi hành về lại Hà Nội kết thúc chuyến đi trọn vẹn.\"}]','[\"Xe du lịch đưa đón suốt tuyến\", \"Vé vào cổng các điểm tham quan\", \"Các bữa ăn đặc sản Tây Bắc theo chương trình\", \"Bảo hiểm du lịch\"]','[\"Xe ôm lên Đồi Mâm Xôi và Móng Ngựa\", \"Vé tắm khoáng nóng Trạm Tấu\", \"Chi tiêu cá nhân\"]','2026-10-21 07:52:31'),
(9,2,2,'Mộc Châu - Đồi Chè Trái Tim - Thác Dải Yếm - Cầu Kính Bạch Long 2N1Đ','Trốn phố về với thảo nguyên xanh mát: hái mận thung lũng Nà Ka, chụp ảnh đồi chè Trái Tim xanh mướt, thử thách lòng dũng cảm trên Cầu kính Bạch Long dài nhất thế giới.',1850000.00,2,'Hà Nội','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',320,'2026-10-21','2026-10-23','ACTIVE',4.7,2400000.00,'Xe du lịch đời mới',4,'TOUR CUỐI TUẦN','[\"Trải nghiệm Cầu kính Bạch Long đạt kỷ lục Guiness dài nhất thế giới\", \"Check-in Đồi chè Trái Tim biểu tượng tình yêu thảo nguyên Mộc Châu\", \"Chiêm ngưỡng Thác Dải Yếm hùng vĩ và Rừng thông Bản Áng lãng mạn\", \"Thưởng thức bê chao Mộc Châu, cá suối nướng và sữa bò tươi nguyên chất\"]','[{\"day\": 1, \"title\": \"Hà Nội - Đèo Thung Khe - Thác Dải Yếm - Cầu Kính Bạch Long\", \"content\": \"Xe đón tại Hà Nội. Dừng chân check-in Đèo Thung Khe đá trắng ngỡ trời Âu. Đến Mộc Châu tham quan Thác Dải Yếm và Cầu Kính Bạch Long kỷ lục thế giới.\"}, {\"day\": 2, \"title\": \"Đồi Chè Trái Tim - Rừng Thông Bản Áng - Về Hà Nội\", \"content\": \"Chụp ảnh tại Đồi chè Trái Tim, dạo hồ nước thông reo Bản Áng. Mua sữa chua nếp cẩm, mận sấy dẻo Mộc Châu. Khởi hành về lại Hà Nội.\"}]','[\"Xe du lịch đưa đón đời mới\", \"Khách sạn 4 sao resort Mộc Châu Island hoặc Mường Thanh\", \"Bữa ăn đặc sản bê chao, lợn mán\", \"Bảo hiểm du lịch\"]','[\"Vé vào cổng Cầu kính Bạch Long\", \"Chi phí hái dâu tây, hái mận tại vườn\", \"Chi tiêu cá nhân\"]','2026-10-21 07:52:31'),
(10,2,3,'Ninh Bình - Quần Thể Danh Thắng Tràng An - Chùa Bái Đính - Hang Múa 2N1Đ','Khám phá di sản thế giới kép UNESCO: ngồi thuyền nan lướt nhẹ qua các hang động Tràng An kỳ ảo, chiêm bái đại tự Bái Đính giữ nhiều kỷ lục châu Á, leo đỉnh Ngọa Long ngắm Tam Cốc từ Hang Múa.',2200000.00,2,'Hà Nội','https://images.unsplash.com/photo-1528181304800-259b08848526?w=800',380,'2026-10-21','2026-10-23','ACTIVE',4.9,2800000.00,'Xe du lịch Universe Limousine máy lạnh',4,'DI SẢN UNESCO','[\"Ngồi thuyền chèo tay len lỏi qua 9 hang động ngập nước tại Tràng An\", \"Leo 500 bậc đá đỉnh Hang Múa săn góc nhìn triệu like toàn cảnh Tam Cốc\", \"Chiêm bái Chùa Bái Đính - ngôi chùa quy mô lớn nhất Đông Nam Á\", \"Thưởng thức đặc sản cơm cháy Ninh Bình, thịt dê núi nướng tảng\"]','[{\"day\": 1, \"title\": \"Hà Nội - Chùa Bái Đính - Tuyệt Tình Cốc - Đầm Vân Long\", \"content\": \"Khởi hành từ Hà Nội. Tham quan Bái Đính Cổ Tự và Bái Đính Mới với hành lang 500 vị La Hán. Chiều check-in Động Am Tiên (Tuyệt Tình Cốc) non xanh nước biếc.\"}, {\"day\": 2, \"title\": \"Khu Du Lịch Sinh Thái Tràng An - Đỉnh Núi Hang Múa - Về Hà Nội\", \"content\": \"Đi thuyền nan 3 tiếng khám phá Hang Sáng, Hang Tối, Hang Nấu Rượu Tràng An. Leo đỉnh núi Ngọa Long tại Hang Múa. Chiều khởi hành về lại Hà Nội.\"}]','[\"Xe vận chuyển du lịch đời mới\", \"Resort 4 sao Ninh Bình Hidden Charm / Emeralda\", \"Vé thuyền Tràng An và vé tham quan Hang Múa\", \"Xe điện khứ hồi Chùa Bái Đính\"]','[\"Chi phí cá nhân\", \"Đồ uống trong bữa ăn\", \"Thuế VAT\"]','2026-10-21 07:52:31'),
(11,3,2,'Huế - Đại Nội Cố Đô Triều Nguyễn - Lăng Tự Đức - Động Phong Nha 4N3Đ','Trở về miền hoài niệm dấu ấn vàng son phong kiến: thăm Đại Nội nguy nga, du thuyền rồng nghe ca Huế trên sông Hương thơ mộng, khám phá \'Đệ nhất kỳ quan\' Động Phong Nha Quảng Bình.',4100000.00,4,'Đà Nẵng','https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?w=800',320,'2026-10-21','2026-10-25','ACTIVE',4.8,5000000.00,'Xe Universe 45 chỗ máy lạnh êm ái',4,'DI SẢN VĂN HÓA','[\"Tham quan Đại Nội Huế - Hoàng Thành và Tử Cấm Thành của 13 vị vua triều Nguyễn\", \"Ngồi thuyền rồng nghe Ca Huế trên sông Hương và thả hoa đăng cầu may\", \"Khám phá kiến trúc lăng tẩm lãng mạn bậc nhất: Lăng Khải Định & Lăng Tự Đức\", \"Đi thuyền vào lòng Động Phong Nha chiêm ngưỡng hệ thống thạch nhũ lung linh\"]','[{\"day\": 1, \"title\": \"Đà Nẵng - Hầm Hải Vân - Cố Đô Huế - Thuyền Rồng Sông Hương\", \"content\": \"Xe đón tại Đà Nẵng vượt Hầm Hải Vân đến Huế. Chiều viếng Chùa Thiên Mụ cổ kính 400 năm tuổi. Tối ngồi thuyền rồng nghe ca Huế trên sông Hương.\"}, {\"day\": 2, \"title\": \"Đại Nội Huế - Lăng Khải Định - Lăng Tự Đức\", \"content\": \"Sáng tham quan Cung Diên Thọ, Điện Thái Hòa, Thế Miếu trong Đại Nội. Chiều chiêm ngưỡng nghệ thuật ghép sành sứ độc nhất vô nhị tại Lăng Khải Định.\"}, {\"day\": 3, \"title\": \"Huế - Thánh Địa La Vang - Vườn Quốc Gia Phong Nha Kẻ Bàng\", \"content\": \"Khởi hành đi Quảng Bình, ghé Thánh Địa La Vang. Đến Phong Nha, đi thuyền trên sông Son vào thám hiểm Động Phong Nha kỳ vĩ. Nghỉ đêm tại Đồng Hới.\"}, {\"day\": 4, \"title\": \"Bãi Biển Nhật Lệ - Chợ Đông Ba Huế - Trở Về\", \"content\": \"Dạo bãi biển Nhật Lệ. Ghé Chợ Đông Ba mua mè xửng, nón bài thơ, tôm chua Huế. Xe đưa đoàn về lại điểm đón ban đầu.\"}]','[\"Xe vận chuyển chất lượng cao suốt tuyến\", \"Khách sạn 4 sao cao cấp tại Huế và Đồng Hới\", \"Vé tham quan trọn gói Đại Nội, Lăng Tẩm, Động Phong Nha\", \"Thuyền rồng sông Hương và thuyền sông Son Phong Nha\"]','[\"Chi phí cá nhân\", \"Đồ uống minibar\", \"Tiền tip hướng dẫn viên\"]','2026-10-21 07:52:31'),
(12,3,3,'Đà Nẵng - Sun World Ba Na Hills - Du Thuyền Sông Hàn - Cầu Rồng Phun Lửa 3N2Đ','Tận hưởng không khí hiện đại và sôi động của thành phố đáng sống nhất Việt Nam: cáp treo Bà Nà Hills, du thuyền ngắm Cầu Rồng phun lửa, tắm biển Mỹ Khê cát trắng mịn màng.',4390000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800',360,'2026-10-21','2026-10-24','ACTIVE',4.9,5200000.00,'Máy bay khứ hồi Vietnam Airlines & Xe du lịch đời mới',4,'HOT TUẦN NÀY','[\"Check-in Cầu Vàng Bà Nà Hills - Top 10 cây cầu đẹp nhất hành tinh\", \"Thưởng ngoạn du thuyền trên sông Hàn ngắm Cầu Rồng phun lửa và phun nước\", \"Vui chơi thỏa thích tại Fantasy Park công viên trò chơi trong nhà lớn nhất VN\", \"Thưởng thức tiệc buffet ẩm thực quốc tế hơn 100 món tại đỉnh Bà Nà\"]','[{\"day\": 1, \"title\": \"TP.HCM - Đà Nẵng - Tắm Biển Mỹ Khê - Du Thuyền Sông Hàn\", \"content\": \"Bay đến Đà Nẵng. Nhận phòng khách sạn 4 sao mặt biển Võ Nguyên Giáp. Tối lên du thuyền sông Hàn ngắm cầu Trần Thị Lý, Cầu Quay và Cầu Rồng phun lửa.\"}, {\"day\": 2, \"title\": \"Thiên Đường Cổ Tích Sun World Ba Na Hills\", \"content\": \"Cáp treo lên đỉnh núi Chúa. Dạo bước Cầu Vàng, khám phá Lâu đài Mặt Trăng, Quảng trường Nhật Thực. Thưởng thức buffet trưa cao cấp.\"}, {\"day\": 3, \"title\": \"Bán Đảo Sơn Trà - Chợ Cồn - Tiễn Sân Bay\", \"content\": \"Viếng Chùa Linh Ứng Bãi Bụt. Ăn trưa bánh tráng thịt heo Đại Lộc. Mua sắm đặc sản chả bò tại Chợ Cồn. Xe tiễn sân bay Đà Nẵng.\"}]','[\"Vé máy bay khứ hồi có 20kg hành lý ký gửi\", \"Khách sạn 4 sao biển Mỹ Khê\", \"Vé cáp treo Bà Nà Hills & buffet trưa quốc tế\", \"Vé du thuyền sông Hàn\"]','[\"Bảo tàng sáp Bà Nà\", \"Chi tiêu cá nhân\"]','2026-10-21 07:52:31'),
(13,3,4,'Quảng Bình - Động Thiên Đường - Suối Nước Moọc - Sông Chày Hang Tối 3N2Đ','Thám hiểm vương quốc hang động thế giới: chiêm ngưỡng hoàng cung trong lòng đất Động Thiên Đường dài 31km, chèo kayak tắm suối Moọc ngọc bích, zipline đu dây vào Hang Tối.',3850000.00,3,'Hà Nội','https://images.unsplash.com/photo-1551632811-561732d1e306?w=800',280,'2026-10-21','2026-10-24','ACTIVE',4.9,4600000.00,'Tàu hỏa giường nằm cao cấp hoặc Máy bay khứ hồi',4,'MẠO HIỂM','[\"Thám hiểm Động Thiên Đường - hang động khô dài nhất châu Á\", \"Đu Zipline trên không và tắm bùn tự nhiên phục hồi da tại Hang Tối\", \"Chèo thuyền Kayak trên dòng nước ngọc bích xanh mát của Suối Moọc\", \"Thưởng thức mẹt gà đồi nướng chấm muối cheo Quảng Bình cay nồng\"]','[{\"day\": 1, \"title\": \"Đến Đồng Hới - Đồi Cát Quang Phú - Biển Nhật Lệ\", \"content\": \"Đến Đồng Hới nhận phòng khách sạn. Chiều trượt cát trên đồi cát trắng Quang Phú. Tắm biển Nhật Lệ và thưởng thức hải sản đẻn biển.\"}, {\"day\": 2, \"title\": \"Hoàng Cung Trong Lòng Đất Động Thiên Đường - Suối Moọc\", \"content\": \"Xe điện đưa vào chân núi, bách bộ khám phá thạch nhũ kỳ ảo Động Thiên Đường. Chiều đắm mình trong làn nước trong vắt tại Suối Nước Moọc.\"}, {\"day\": 3, \"title\": \"Zipline Sông Chày - Hang Tối - Tiễn Ga / Sân Bay\", \"content\": \"Trải nghiệm Zipline 400m vượt Sông Chày vào Hang Tối tắm bùn khoáng thiên nhiên. Chiều xe tiễn ga Đồng Hới về lại Hà Nội.\"}]','[\"Xe vận chuyển máy lạnh đời mới\", \"Khách sạn 4 sao trung tâm TP Đồng Hới\", \"Vé vào cổng Động Thiên Đường, xe điện khứ hồi\", \"Vé trọn gói Zipline, kayak Sông Chày Hang Tối\"]','[\"Chi phí cá nhân\", \"Thuế VAT\", \"Tiền bồi dưỡng tài xế\"]','2026-10-21 07:52:31'),
(14,3,2,'Phú Yên - Xứ Sở Hoa Vàng Trên Cỏ Xanh - Gành Đá Đĩa - Mũi Điện 3N2Đ','Về xứ Nẫu hoang sơ say đắm lòng người: ngắm kiệt tác bazan núi lửa Gành Đá Đĩa độc nhất vô nhị, đón bình minh sớm nhất đất liền tại Mũi Điện, check-in Bãi Xép ngắm biển xanh ngắt.',3750000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800',300,'2026-10-21','2026-10-24','ACTIVE',4.8,4500000.00,'Máy bay khứ hồi Vietjet Air & Xe du lịch đời mới',4,'GIÁ TỐT TRAVELOKA','[\"Chiêm ngưỡng Gành Đá Đĩa - tuyệt tác địa chất núi lửa bazan kỳ vĩ\", \"Chạm tay vào ngọn hải đăng Mũi Điện - điểm đón ánh bình minh đầu tiên\", \"Chụp ảnh tại Bãi Xép bối cảnh phim \'Tôi thấy hoa vàng trên cỏ xanh\'\", \"Thưởng thức mắt cá ngừ đại dương hầm thuốc bắc bổ dưỡng\"]','[{\"day\": 1, \"title\": \"Tuy Hòa - Tháp Nhạn - Chùa Thanh Lương Bằng San Hô\", \"content\": \"Đáp máy bay sân bay Tuy Hòa. Tham quan Tháp Nhạn Chăm Pa cổ, viếng Chùa Thanh Lương làm từ san hô và gáo dừa độc đáo. Thưởng thức mắt cá ngừ đại dương.\"}, {\"day\": 2, \"title\": \"Gành Đá Đĩa - Nhà Thờ Mằng Lăng - Bãi Xép Gành Ông\", \"content\": \"Khám phá Nhà thờ Mằng Lăng lưu giữ cuốn sách in chữ quốc ngữ đầu tiên. Check-in kỳ quan Gành Đá Đĩa. Chiều dạo thảo nguyên cỏ xanh Bãi Xép.\"}, {\"day\": 3, \"title\": \"Hải Đăng Mũi Điện - Vịnh Vũng Rô Tàu Không Số - Tiễn Bay\", \"content\": \"Đón bình minh tại Hải đăng Mũi Đại Lãnh. Thăm di tích bến Tàu Không Số Vịnh Vũng Rô. Ăn trưa bè nổi hải sản. Tiễn sân bay Tuy Hòa.\"}]','[\"Vé máy bay khứ hồi TP.HCM - Tuy Hòa có hành lý\", \"Khách sạn 4 sao Sala Tuy Hoa Beach hoặc tương đương\", \"Vé tham quan tất cả danh lam thắng cảnh\", \"Thực đơn hải sản tươi sống chất lượng cao\"]','[\"Chi phí cá nhân\", \"Thuế VAT\"]','2026-10-21 07:52:31'),
(15,3,3,'Quảng Nam - Thánh Địa Mỹ Sơn - Làng Rau Trà Quế - Rừng Dừa Bảy Mẫu 2N1Đ','Khám phá chiều sâu văn hóa Chăm Pa và sông nước xứ Quảng: thăm khu đền tháp Mỹ Sơn huyền bí, trải nghiệm múa thúng chai xoay tròn náo nhiệt tại Rừng Dừa Bảy Mẫu Cẩm Thanh.',2100000.00,2,'Đà Nẵng','https://images.unsplash.com/photo-1528181304800-259b08848526?w=800',320,'2026-10-21','2026-10-23','ACTIVE',4.7,2600000.00,'Xe du lịch đời mới',4,'VĂN HÓA DÂN GIAN','[\"Khám phá Thánh Địa Mỹ Sơn - Di sản văn hóa thế giới đền tháp Chăm Pa\", \"Thưởng thức điệu múa Apsara uyển chuyển của các thiếu nữ Chăm\", \"Trải nghiệm chèo thuyền thúng xoay vòng náo nhiệt ở Rừng dừa Bảy Mẫu\", \"Tập làm nông dân tưới nước gánh rau tại Làng rau Trà Quế 300 năm tuổi\"]','[{\"day\": 1, \"title\": \"Đà Nẵng - Thánh Địa Mỹ Sơn - Thưởng Thức Múa Chăm\", \"content\": \"Xe đón tại Đà Nẵng khởi hành đi thung lũng Mỹ Sơn. Bách bộ khám phá các cụm tháp Chăm nghìn năm tuổi, xem show diễn văn nghệ dân gian Chăm Pa.\"}, {\"day\": 2, \"title\": \"Rừng Dừa Bảy Mẫu - Làng Rau Trà Quế - Trở Về\", \"content\": \"Đi thuyền thúng len lỏi trong rừng dừa nước Cẩm Thanh, xem ngư dân quăng chài và múa thúng biểu diễn. Chiều về làng rau Trà Quế ngâm chân thảo dược rồi trở về Đà Nẵng.\"}]','[\"Xe vận chuyển chất lượng cao\", \"Khách sạn 4 sao Hội An\", \"Vé thuyền thúng Rừng dừa Bảy Mẫu\", \"Vé vào cổng Thánh địa Mỹ Sơn\"]','[\"Chi phí cá nhân ngoài chương trình\", \"Tiền tip tài xế\"]','2026-10-21 07:52:31'),
(16,4,4,'Đà Lạt - Samten Hills Đại Bảo Tháp Kinh Luân - Thác Datanla - Langbiang 3N3Đ','Hành trình tĩnh tâm và lãng mạn nơi thành phố ngàn hoa: chiêm bái Đại Bảo Tháp Kinh Luân lớn nhất thế giới dát vàng 24K tại Samten Hills, trượt máng Thác Datanla, chinh phục đỉnh Langbiang.',2890000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',400,'2026-10-21','2026-10-24','ACTIVE',4.9,3600000.00,'Xe Limousine giường nằm VIP cung điện bay',4,'BÁN CHẠY NHẤT','[\"Chiêm bái Đại bảo tháp Kinh Luân dát vàng 24K lớn nhất thế giới tại Samten Hills\", \"Trải nghiệm máng trượt uốn lượn xuyên rừng thông dài nhất châu Á tại Thác Datanla\", \"Check-in đỉnh núi Langbiang huyền thoại ngắm toàn cảnh suối Vàng suối Bạc\", \"Thưởng thức tiệc buffet rau không giới hạn Leguda trên đồi Robin\"]','[{\"day\": 1, \"title\": \"TP.HCM - Đèo Prenn Mới - Không Gian Văn Hóa Tâm Linh Samten Hills\", \"content\": \"Đêm xe Limousine khởi hành từ TP.HCM lên Đà Lạt qua Đèo Prenn tuyệt đẹp. Sáng tham quan Samten Hills Dalat, xoay kinh luân cầu an may mắn. Chiều nhận phòng khách sạn 4 sao.\"}, {\"day\": 2, \"title\": \"Thác Datanla - Đỉnh Núi Langbiang - Giao Lưu Cồng Chiêng\", \"content\": \"Trượt máng xuống Thác Datanla hùng vĩ. Chiều đi xe Jeep lên đỉnh Langbiang huyền thoại. Tối tham gia đêm hội rượu cần cồng chiêng Tây Nguyên rực lửa.\"}, {\"day\": 3, \"title\": \"Quảng Trường Lâm Viên - Chợ Đà Lạt - Về Lại TP.HCM\", \"content\": \"Check-in Bông hoa dã quỳ và nụ hoa Atiso tại Quảng trường Lâm Viên. Mua dâu tây tươi, mứt hoa quả tại chợ Đà Lạt. Chiều xe đưa đoàn về lại TP.HCM.\"}]','[\"Xe Limousine giường nằm cao cấp êm ái khứ hồi\", \"Khách sạn 4 sao gần Hồ Xuân Hương\", \"Vé vào cổng Samten Hills và Thác Datanla\", \"Vé đêm hội giao lưu cồng chiêng ăn thịt nướng uống rượu cần\"]','[\"Vé xe Jeep lên đỉnh Langbiang\", \"Vé máng trượt Datanla\", \"Chi phí cá nhân\"]','2026-10-21 07:52:31'),
(17,4,2,'Đà Lạt - Săn Mây Cầu Đất Đón Bình Minh - Vườn Cẩm Tú Cầu - Dinh Bảo Đại 3N2Đ','Bắt trọn khoảnh khắc huyền ảo nhất xứ sở ngàn hoa: săn mây trên thảm gỗ đồi chè Cầu Đất lúc bình minh, lạc bước giữa vườn hoa cẩm tú cầu rực rỡ và dinh thự vua Bảo Đại uy nghiêm.',2750000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?w=800',350,'2026-10-21','2026-10-24','ACTIVE',4.8,3400000.00,'Xe Universe 45 chỗ đời mới',3,'SỐNG ẢO TRIỆU VIEW','[\"Săn biển mây cuồn cuộn trên cầu gỗ đồi chè Cầu Đất ngắm cối xay gió\", \"Check-in cánh đồng hoa Cẩm Tú Cầu bạt ngàn góc chụp ảnh thần thánh\", \"Tham quan Dinh 1 Bảo Đại mang phong cách kiến trúc Pháp cổ kính sang trọng\", \"Thưởng thức lẩu gà lá é Tao Ngộ và bánh tráng nướng Đà Lạt nóng hổi\"]','[{\"day\": 1, \"title\": \"TP.HCM - Đà Lạt - Quảng Trường Lâm Viên - Dạo Hồ Xuân Hương\", \"content\": \"Khởi hành từ TP.HCM đi Đà Lạt. Dừng chân ăn trưa tại Bảo Lộc. Chiều đến Đà Lạt check-in Quảng trường Lâm Viên, dạo quanh Hồ Xuân Hương ngắm hoàng hôn buông.\"}, {\"day\": 2, \"title\": \"Săn Mây Cầu Đất - Vườn Cẩm Tú Cầu - Dinh 1 Bảo Đại\", \"content\": \"04h30 sáng xe đưa đoàn lên Đồi chè Cầu Đất săn biển mây đón ánh bình minh tuyệt diệu. Ghé Cánh đồng hoa Cẩm Tú Cầu. Chiều tham quan Dinh 1 vua Bảo Đại.\"}, {\"day\": 3, \"title\": \"Thiền Viện Trúc Lâm - Hồ Tuyền Lâm - TP.HCM\", \"content\": \"Viếng Thiền Viện Trúc Lâm thanh tịnh soi bóng bên Hồ Tuyền Lâm. Mua đặc sản atiso, bơ 034. Khởi hành về lại TP.HCM lúc 20h00.\"}]','[\"Xe du lịch đưa đón khứ hồi\", \"Khách sạn tiêu chuẩn 3 sao trung tâm\", \"Vé săn mây Cầu Đất và vườn hoa Cẩm Tú Cầu\", \"Ăn uống đầy đủ theo lịch trình\"]','[\"Chi phí cá nhân\", \"Cáp treo đồi Robin\", \"Nước uống tự gọi trong bữa ăn\"]','2026-10-21 07:52:31'),
(18,4,3,'Buôn Ma Thuột - Thác Dray Nur Hùng Vĩ - Buôn Đôn - Bảo Tàng Cà Phê 3N2Đ','Khám phá thủ phủ cà phê nức tiếng: chiêm ngưỡng thác nước Dray Nur hùng vĩ tuôn trào trắng xóa, trải nghiệm cầu treo Buôn Đôn bắc qua sông Serepôk và thưởng thức cà phê chồn thượng hạng.',3400000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800',260,'2026-10-21','2026-10-24','ACTIVE',4.8,4200000.00,'Máy bay khứ hồi hoặc Xe du lịch chất lượng cao',4,'ĐẠI NGÀN HUYỀN BÍ','[\"Chiêm ngưỡng Thác Dray Nur - thác nước kỳ vĩ và thơ mộng nhất Tây Nguyên\", \"Đi cầu treo bằng tre bắc ngang dòng sông Sêrêpôk chảy ngược tại Buôn Đôn\", \"Check-in Bảo tàng Thế giới Cà phê với kiến trúc nhà dài cách điệu ấn tượng\", \"Thưởng thức cơm lam gà nướng chấm muối é và gỏi cà đắng cá khô\"]','[{\"day\": 1, \"title\": \"Đến Buôn Ma Thuột - Bảo Tàng Cà Phê - Làng Cà Phê Trung Nguyên\", \"content\": \"Xe đón tại Buôn Ma Thuột. Thăm Bảo tàng Thế giới Cà phê, thưởng thức ly espresso đậm đà. Thăm Làng Cà phê Trung Nguyên rợp bóng cây cổ thụ.\"}, {\"day\": 2, \"title\": \"Thác Dray Nur Hùng Vĩ - Buôn Đôn Cầu Treo Serepok\", \"content\": \"Khám phá Thác Dray Nur dòng nước trắng xóa mát lạnh. Chiều về Buôn Đôn nghe chuyện săn bắt thuần dưỡng voi rừng, đi cầu treo dài 500m bắc qua sông Sêrêpôk.\"}, {\"day\": 3, \"title\": \"Chùa Sắc Tứ Khải Đoan - Mua Sắm Cà Phê Hạt - Trở Về\", \"content\": \"Viếng Chùa Sắc Tứ Khải Đoan - ngôi chùa gỗ lớn nhất Tây Nguyên do Nam Phương Hoàng Hậu chủ trì xây dựng. Mua cà phê Robusta đặc sản. Tiễn sân bay.\"}]','[\"Xe vận chuyển máy lạnh đời mới\", \"Khách sạn 4 sao Mường Thanh / Elephants Hotel\", \"Vé vào cổng tất cả các điểm tham quan\", \"Thực đơn đặc sản Tây Nguyên phong phú\"]','[\"Chi phí cưỡi voi (nếu có)\", \"Chi tiêu cá nhân\"]','2026-10-21 07:52:31'),
(19,4,4,'Pleiku - Biển Hồ Tơ Nưng Mắt Ngọc Gia Lai - Núi Lửa Chư Đăng Ya 3N2Đ','Chạm vào vẻ đẹp nguyên sơ của cao nguyên Gia Lai: ngắm \'đôi mắt Pleiku\' Biển Hồ Tơ Nưng biếc xanh, chiêm ngưỡng miệng núi lửa Chư Đăng Ya rực rỡ hoa dã quỳ và Thác Phú Cường kỳ ảo.',3600000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1528127269322-539801943592?w=800',240,'2026-10-21','2026-10-24','ACTIVE',4.7,4300000.00,'Máy bay khứ hồi Bamboo Airways & Xe du lịch',4,'THIÊN NHIÊN HOANG SƠ','[\"Ngắm Biển Hồ Tơ Nưng - hồ nước ngọt tự nhiên trên miệng núi lửa cổ triệu năm\", \"Check-in Núi lửa Chư Đăng Ya chìm trong sắc vàng hoa dã quỳ mùa đông\", \"Chiêm ngưỡng hàng thông trăm tuổi và Biển Hồ Chè xanh ngút ngàn\", \"Thưởng thức phở hai tô (phở khô Gia Lai) và bò một nắng muối kiến vàng\"]','[{\"day\": 1, \"title\": \"TP.HCM - Sân Bay Pleiku - Biển Hồ Tơ Nưng - Hàng Thông Trăm Tuổi\", \"content\": \"Bay đến Pleiku. Thăm Biển Hồ Tơ Nưng nước xanh phẳng lặng như gương. Dạo bước dưới Hàng thông trăm tuổi và đồi chè Biển Hồ thơ mộng.\"}, {\"day\": 2, \"title\": \"Núi Lửa Chư Đăng Ya - Chùa Minh Thành Đẹp Tựa Xứ Phù Tang\", \"content\": \"Chinh phục đỉnh núi lửa Chư Đăng Ya ngắm đất đỏ bazan màu mỡ. Chiều viếng Chùa Minh Thành với kiến trúc tháp chuông tuyệt mỹ như Nhật Bản thu nhỏ.\"}, {\"day\": 3, \"title\": \"Thác Phú Cường - Thưởng Thức Bò Một Nắng - Tiễn Bay\", \"content\": \"Khám phá Thác Phú Cường hùng vĩ tuôn trào trên nền nham thạch núi lửa cổ. Thưởng thức bò một nắng muối kiến vàng. Tiễn sân bay Pleiku.\"}]','[\"Vé máy bay khứ hồi có 20kg hành lý\", \"Khách sạn 4 sao Pleiku trung tâm\", \"Xe vận chuyển chất lượng cao\", \"Vé tham quan các thắng cảnh\"]','[\"Chi phí cá nhân ngoài chương trình\", \"Đồ uống trong bữa ăn\"]','2026-10-21 07:52:31'),
(20,4,2,'Măng Đen - Nàng Thơ Kon Tum Khí Hậu Ôn Đới - Thác Pa Sỹ - Cầu Treo Kon Klor 3N2Đ','Lạc bước giữa \'Đà Lạt thứ hai\' thanh bình và nguyên sơ: hít thở không khí rừng thông Măng Đen mát lạnh 20 độ C quanh năm, ngắm Thác Pa Sỹ bọt tung trắng xóa, thăm Nhà thờ Gỗ Kon Tum trăm tuổi.',3950000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800',260,'2026-10-21','2026-10-24','ACTIVE',4.9,4800000.00,'Máy bay khứ hồi & Xe du lịch đời mới',4,'KHUYẾN NGHỊ','[\"Nghỉ dưỡng tại Măng Đen - \'Đà Lạt thứ hai\' thanh bình không khói bụi\", \"Chiêm ngưỡng Thác Pa Sỹ trong vắt bắt nguồn từ đại ngàn rừng già\", \"Viếng tượng Đức Mẹ Măng Đen linh thiêng giữa rừng thông cổ thụ\", \"Khám phá Nhà thờ Gỗ Kon Tum hơn 100 năm tuổi làm hoàn toàn bằng gỗ cà chít\"]','[{\"day\": 1, \"title\": \"Pleiku - Kon Tum - Cầu Treo Kon Klor - Cao Nguyên Măng Đen\", \"content\": \"Xe đón tại sân bay Pleiku về Kon Tum. Thăm Nhà thờ Gỗ Kon Tum, Nhà rông Kon Klor và cầu treo Kon Klor bắc qua sông Đắk Bla. Chiều lên Măng Đen nhận resort.\"}, {\"day\": 2, \"title\": \"Thác Pa Sỹ - Hồ Đắk Ke - Viếng Tượng Đức Mẹ Măng Đen\", \"content\": \"Khám phá Thác Pa Sỹ tung bọt trắng xóa. Chèo thuyền ngắm hoa nở bên Hồ Đắk Ke. Viếng Tượng Đức Mẹ Măng Đen. Tối đốt lửa trại nướng gà đồi cơm lam.\"}, {\"day\": 3, \"title\": \"Vườn Nông Nghiệp Công Nghệ Cao - Tiễn Sân Bay\", \"content\": \"Hái dâu tây hữu cơ, mua sâm dây Ngọc Linh và mật ong rừng nguyên chất. Xe đưa đoàn về sân bay Pleiku đáp chuyến bay về TP.HCM.\"}]','[\"Vé máy bay khứ hồi Sài Gòn - Pleiku\", \"Resort sinh thái nghỉ dưỡng tại Măng Đen\", \"Xe ô tô đời mới đưa đón suốt hành trình\", \"Các bữa ăn đặc sản địa phương gà nướng cơm lam\"]','[\"Chi phí cá nhân\", \"Đồ uống rượu sâm\", \"Thuế VAT\"]','2026-10-21 07:52:31'),
(21,5,3,'Cần Thơ - Chợ Nổi Cái Răng - Cồn Sơn Xem Cá Bú Bình - Miệt Vườn 2N1Đ','Trải nghiệm văn hóa sông nước miền Tây độc đáo: đi thuyền ngắm bình minh trên Chợ Nổi Cái Răng tấp nập, sang Cồn Sơn xem màn trình diễn độc lạ \'cá lóc bay\' và \'cá bú bình sữa\'.',1950000.00,2,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1528181304800-259b08848526?w=800',450,'2026-10-21','2026-10-23','ACTIVE',4.9,2500000.00,'Xe du lịch Universe 45 chỗ máy lạnh êm ái',4,'BÁN CHẠY NHẤT','[\"Trải nghiệm văn hóa Chợ Nổi Cái Răng - Di sản văn hóa phi vật thể quốc gia\", \"Thưởng thức tô hủ tiếu nóng hổi và ly cà phê sữa đá đậm đà trên thuyền nổi\", \"Sang Cồn Sơn xem màn biểu diễn \'cá lóc bay\' săn mồi và cá Koi bú bình sữa lạ mắt\", \"Thưởng thức bánh xèo miền Tây khổng lồ và trái cây miệt vườn hái tại cây\"]','[{\"day\": 1, \"title\": \"TP.HCM - Mỹ Tho - Bến Tre - Cần Thơ - Du Thuyền Bến Ninh Kiều\", \"content\": \"Xe đón tại TP.HCM đi Tiền Giang, Bến Tre thưởng thức kẹo dừa, nghe đờn ca tài tử. Chiều về Cần Thơ nhận phòng khách sạn 4 sao. Tối lên du thuyền bến Ninh Kiều ăn tối.\"}, {\"day\": 2, \"title\": \"Khám Phá Chợ Nổi Cái Răng - Làng Cá Bè Cồn Sơn - TP.HCM\", \"content\": \"05h30 sáng đi tàu ra Chợ Nổi Cái Răng ngắm thuyền ghe tấp nập chào hàng bằng cây \'bẹo\'. Sang Cồn Sơn xem cá lóc bay, học làm bánh dân gian. Khởi hành về TP.HCM.\"}]','[\"Xe vận chuyển Universe máy lạnh chất lượng cao suốt tuyến\", \"Khách sạn 4 sao TTC Cần Thơ / Mường Thanh Luxury\", \"Tàu tham quan Chợ Nổi Cái Răng và vé đò sang Cồn Sơn\", \"Bữa tối du thuyền Ninh Kiều sang trọng\"]','[\"Chi phí cá nhân\", \"Đồ uống minibar\", \"Tiền tip tài xế\"]','2026-10-21 07:52:31'),
(22,5,4,'An Giang - Rừng Tràm Trà Sư Mùa Nước Nổi - Miếu Bà Chúa Xứ Núi Sam 2N1Đ','Hành trình tâm linh và sinh thái miền biên thùy: chèo xuồng ba lá lướt trên thảm bèo xanh mướt Rừng tràm Trà Sư, chiêm bái Miếu Bà Chúa Xứ Núi Sam linh ứng bậc nhất Nam Bộ.',1850000.00,2,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800',380,'2026-10-21','2026-10-23','ACTIVE',4.8,2400000.00,'Xe du lịch Universe đời mới',4,'TÂM LINH SINH THÁI','[\"Chèo xuồng ba lá len lỏi giữa thảm bèo tấm xanh ngắt tại Rừng tràm Trà Sư\", \"Check-in cây cầu tre vạn bước xuyên rừng tràm dài nhất Việt Nam\", \"Viếng Miếu Bà Chúa Xứ Núi Sam Châu Đốc linh thiêng cầu bình an tài lộc\", \"Thưởng thức lẩu mắm Châu Đốc nức tiếng cùng hơn 20 loại rau đồng cỏ dại\"]','[{\"day\": 1, \"title\": \"TP.HCM - Sa Đéc Làng Hoa - Châu Đốc - Viếng Miếu Bà Chúa Xứ\", \"content\": \"Khởi hành từ TP.HCM qua cầu Vàm Cống sang An Giang. Viếng Miếu Bà Chúa Xứ Núi Sam, Lăng Thoại Ngọc Hầu, Tây An Cổ Tự. Tối tự do khám phá chợ đêm Châu Đốc.\"}, {\"day\": 2, \"title\": \"Khám Phá Rừng Tràm Trà Sư - Về Lại TP.HCM\", \"content\": \"Đi tắc ráng lướt sóng vào vùng lõi Rừng Tràm Trà Sư, ngồi xuồng chèo ngắm hàng ngàn cánh cò bay lượn trên thảm bèo xanh. Ăn trưa cá lóc nướng trui. Về lại TP.HCM.\"}]','[\"Xe vận chuyển chất lượng cao khứ hồi\", \"Khách sạn 4 sao Châu Đốc Victoria hoặc tương đương\", \"Vé tắc ráng và xuồng chèo tay Rừng Tràm Trà Sư\", \"Bữa ăn đặc sản lẩu mắm, cá linh bông điên điển\"]','[\"Chi phí cá nhân\", \"Cáp treo Núi Sam\", \"Thuế VAT\"]','2026-10-21 07:52:31'),
(23,5,2,'Mỹ Tho - Bến Tre - Cù Lao Thới Sơn - Nghe Đờn Ca Tài Tử 1 Ngày','Chuyến du lịch thư giãn trong ngày cuối tuần: đi thuyền rồng ngắm 4 cù lao Long Lân Quy Phụng, chèo xuồng ba lá dưới rặng dừa nước rợp bóng mát, uống trà mật ong phấn hoa thơm lừng.',850000.00,1,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1528181304800-259b08848526?w=800',500,'2026-10-21','2026-10-22','ACTIVE',4.7,1100000.00,'Xe du lịch đời mới',3,'TOUR TRONG NGÀY','[\"Du thuyền trên sông Tiền ngắm Cầu Rạch Miễu và 4 cồn Long - Lân - Quy - Phụng\", \"Trải nghiệm chèo xuồng ba lá len lỏi trong rạch dừa nước rợp bóng mát\", \"Thưởng thức trà mật ong hoa nhãn, kẹo dừa béo ngậy vừa ra lò tại chỗ\", \"Ăn trưa cá tai tượng chiên xù cuốn bánh tráng rau rừng\"]','[{\"day\": 1, \"title\": \"TP.HCM - Bến Tàu 30/4 Mỹ Tho - Cù Lao Thới Sơn - Cồn Phụng\", \"content\": \"07h30 sáng xuất phát từ TP.HCM. Thuyền đưa đoàn sang Cù lao Thới Sơn nghe đờn ca tài tử ăn trái cây bốn mùa. Xuồng chèo len lỏi qua rạch dừa. Tham quan Đạo Dừa tại Cồn Phụng. Chiều 17h30 về lại TP.HCM.\"}]','[\"Xe đưa đón đời mới\", \"Thuyền rồng sông Tiền và xuồng ba lá\", \"Bữa trưa cá tai tượng chiên xù bánh tráng\", \"Vé tham quan trọn gói, bảo hiểm du lịch\"]','[\"Chi phí cá nhân\", \"Đồ uống trong bữa ăn\"]','2026-10-21 07:52:31'),
(24,5,3,'Đồng Tháp - Làng Hoa Sa Đéc - Khu Sinh Thái Tràm Chim Tam Nông 2N1Đ','Về miền sen hồng thanh khiết: check-in làng hoa Sa Đéc trăm tuổi rực rỡ sắc màu, ngắm sếu đầu đỏ tại Vườn quốc gia Tràm Chim, thăm nhà cổ Huỳnh Thủy Lê mối tình lãng mạn xuyên biên giới.',1790000.00,2,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800',320,'2026-10-21','2026-10-23','ACTIVE',4.8,2300000.00,'Xe Universe 45 chỗ máy lạnh',3,'THIÊN NHIÊN HOANG DÃ','[\"Khám phá Vườn Quốc Gia Tràm Chim Tam Nông - khu Ramsar thứ 2.000 của thế giới\", \"Thăm Làng hoa Sa Đéc với hàng ngàn giàn hoa khoe sắc trên mặt nước\", \"Chiêm ngưỡng kiến trúc Đông Tây hòa quyện tại Nhà cổ Huỳnh Thủy Lê\", \"Thưởng thức cơm huyết rồng gói lá sen và canh chua cá lóc bông súng\"]','[{\"day\": 1, \"title\": \"TP.HCM - Sa Đéc Làng Hoa - Nhà Cổ Huỳnh Thủy Lê - Cao Lãnh\", \"content\": \"Khởi hành từ TP.HCM đi Đồng Tháp. Ghé thăm Làng hoa Sa Đéc, chụp ảnh cầu hoa, nhà cổ Huỳnh Thủy Lê. Chiều viếng Khu di tích Cụ Phó Bảng Nguyễn Sinh Sắc.\"}, {\"day\": 2, \"title\": \"Khám Phá Tràm Chim Tam Nông - Về Lại TP.HCM\", \"content\": \"Lên thuyền tắc ráng lướt sóng qua cánh đồng sen bát ngát Tràm Chim, ngắm chim nước và cánh đồng cỏ năn. Chiều khởi hành về lại TP.HCM.\"}]','[\"Xe vận chuyển du lịch đời mới\", \"Khách sạn tiêu chuẩn tại TP Cao Lãnh\", \"Tắc ráng tham quan Tràm Chim\", \"Các bữa ăn đặc sản đồng quê sen Đồng Tháp\"]','[\"Chi phí cá nhân\", \"Thuế VAT\"]','2026-10-21 07:52:31'),
(25,5,4,'Cà Mau - Chinh Phục Cột Mốc Mũi Cà Mau - Rừng Ngập Mặn U Minh Hạ 3N2Đ','Hành trình về điểm cực Nam thiêng liêng của dải đất hình chữ S: chạm tay vào Cột Mốc Tọa Độ Quốc Gia GPS 0001, ngắm biểu tượng Con Tàu Mũi Cà Mau vươn mình ra biển lớn.',3500000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800',300,'2026-10-21','2026-10-24','ACTIVE',4.9,4300000.00,'Xe du lịch giường nằm cao cấp',4,'ĐIỂM CỰC TỔ QUỐC','[\"Chạm tay vào Cột Mốc Tọa Độ Quốc Gia GPS 0001 tại Đất Mũi Cà Mau\", \"Check-in biểu tượng Con Tàu No Gió hướng ra biển Đông rộng lớn\", \"Đi cano cao tốc xuyên rừng đước ngập mặn lớn thứ 2 thế giới\", \"Thưởng thức cua Cà Mau chính gốc gạch son chắc nịt và lẩu cá ngát\"]','[{\"day\": 1, \"title\": \"TP.HCM - Bạc Liêu Nhà Công Tử - TP. Cà Mau\", \"content\": \"Khởi hành từ TP.HCM. Ghé Sóc Trăng viếng Chùa Dơi, Chùa Chén Kiểu. Đến Bạc Liêu thăm Nhà Công Tử Bạc Liêu và Cánh đồng điện gió. Nghỉ đêm tại TP Cà Mau.\"}, {\"day\": 2, \"title\": \"Chinh Phục Cột Mốc Đất Mũi Cà Mau - Xuyên Rừng Đước\", \"content\": \"Đi xe và cano đến Vườn Quốc Gia Mũi Cà Mau. Chụp ảnh lưu niệm tại Cột mốc tọa độ GPS 0001, Cột cờ Hà Nội tại Đất Mũi. Thưởng thức cua Cà Mau nướng mọi.\"}, {\"day\": 3, \"title\": \"Rừng U Minh Hạ Ăn Ong Rừng - Trở Về TP.HCM\", \"content\": \"Trải nghiệm đi gác kèo ong, thưởng thức mật ong rừng U Minh Hạ và gỏi ong non. Khởi hành về đến TP.HCM lúc 20h00.\"}]','[\"Xe giường nằm Universe đời mới suốt tuyến\", \"Khách sạn 4 sao Mường Thanh Luxury Cà Mau\", \"Cano cao tốc xuyên rừng ngập mặn Đất Mũi\", \"Thực đơn tiệc cua Cà Mau thượng hạng\"]','[\"Chi phí cá nhân\", \"Thuế VAT\"]','2026-10-21 07:52:31'),
(26,6,2,'Hạ Long - Du Thuyền 5 Sao Ambassador Cruise Siêu Sang - Hang Sửng Sốt 2N1Đ','Trải nghiệm kỳ nghỉ thượng lưu trên du thuyền 5 sao lớn nhất Vịnh Hạ Long: ngắm hoàng hôn trên sundeck 360 độ, thưởng thức tiệc buffet tôm hùm không giới hạn, khám phá Hang Sửng Sốt kỳ vĩ.',3990000.00,2,'Hà Nội','https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800',350,'2026-10-21','2026-10-23','ACTIVE',5.0,5200000.00,'Xe Limousine Dcar đưa đón Hà Nội - Cảng Tuần Châu & Du Thuyền 5 Sao',5,'5 SAO CAO CẤP','[\"Nghỉ đêm trên du thuyền Ambassador Cruise 5 sao với cabin ban công riêng view vịnh\", \"Thưởng thức đại tiệc buffet tôm hùm thượng hạng và hải sản Hạ Long\", \"Thư giãn tại bể sục Jacuzzi ngoài trời trên boong tàu ngắm hoàng hôn\", \"Chèo thuyền Kayak khám phá Hang Luồn và bách bộ leo Đảo Titov ngắm toàn cảnh vịnh\"]','[{\"day\": 1, \"title\": \"Hà Nội - Cảng Quốc Tế Tuần Châu - Check-in Du Thuyền Ambassador\", \"content\": \"Xe Limousine đón tại Hà Nội qua cao tốc đến Tuần Châu. 12h00 lên du thuyền, thưởng thức đồ uống chào mừng. Dùng buffet trưa sang trọng. Chiều khám phá Hang Sửng Sốt, chèo kayak tại Hang Luồn. Tiệc Sunset Party và đại tiệc tôm hùm ban đêm.\"}, {\"day\": 2, \"title\": \"Tập Thái Cực Quyền Bình Minh - Đảo Ti Tốp - Về Hà Nội\", \"content\": \"06h30 tập Tai-chi đón bình minh trên sundeck. Chinh phục đỉnh núi Đảo Titov tắm biển cát trắng. Dùng bữa trưa buffet sớm trong khi du thuyền lướt qua Hòn Trống Mái. 12h00 cập bến, xe đưa về Hà Nội.\"}]','[\"Cabin 5 sao view biển có ban công riêng và bồn tắm sang trọng\", \"Trọn gói 4 bữa ăn cao cấp trên du thuyền (buffet tôm hùm, bữa trưa hải sản)\", \"Xe Limousine Dcar đưa đón khứ hồi Hà Nội - Hạ Long\", \"Vé tham quan trọn gói Vịnh Hạ Long, bảo hiểm du lịch đường thủy\"]','[\"Dịch vụ spa làm đẹp trên du thuyền\", \"Đồ uống rượu vang tự chọn\", \"Tiền tip cho thuyền viên\"]','2026-10-21 07:52:31'),
(27,6,3,'Vịnh Lan Hạ - Cát Bà - Du Thuyền Scarlet Pearl Luxury 5 Sao 2N1Đ','Hành trình riêng tư và đẳng cấp tại \'thiên đường bị lãng quên\': du ngoạn Vịnh Lan Hạ nguyên sơ, chèo thuyền Kayak vào Hang Sáng Tối ngắm vượn mắt thụt quý hiếm, tắm biển Ba Trái Đào.',4350000.00,2,'Hà Nội','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800',280,'2026-10-21','2026-10-23','ACTIVE',5.0,5500000.00,'Xe Limousine VIP & Du Thuyền Buồm Scarlet Pearl 5 Sao',5,'SANG TRỌNG RIÊNG TƯ','[\"Khám phá Vịnh Lan Hạ - một trong những vịnh biển đẹp nhất hành tinh\", \"Nghỉ dưỡng trên du thuyền Scarlet Pearl kiến trúc du thuyền buồm hiện đại bậc nhất\", \"Chèo thuyền Kayak khám phá Hang Sáng Tối huyền ảo\", \"Tắm biển và thưởng thức tiệc cocktail hoàng hôn tại Bãi biển Ba Trái Đào\"]','[{\"day\": 1, \"title\": \"Hà Nội - Cảng Tuần Châu - Du Thuyền Lan Hạ - Hang Sáng Tối\", \"content\": \"12h15 lên tàu Scarlet Pearl, nghe giới thiệu an toàn. Dùng bữa trưa hải sản chuẩn fine-dining. Chiều ngồi thuyền nan / kayak qua Hang Sáng Tối. Tối thưởng thức tiệc nướng BBQ hải sản trên sundeck.\"}, {\"day\": 2, \"title\": \"Tập Yoga Đón Bình Minh - Làng Chài Việt Hải Cát Bà - Trở Về\", \"content\": \"Tập Yoga sáng sớm trên boong tàu. Đạp xe xuyên rừng khám phá Làng cổ Việt Hải Cát Bà. Thưởng thức bữa trưa nhẹ buffet trước khi tàu cập cảng về lại Hà Nội.\"}]','[\"Phòng ngủ 5 sao có ban công hướng vịnh\", \"Các bữa ăn tiêu chuẩn 5 sao trên tàu (bữa trưa set menu, bữa tối fine dining)\", \"Xe đạp tham quan làng Việt Hải\", \"Vé tham quan thắng cảnh Vịnh Lan Hạ\"]','[\"Dịch vụ massage spa\", \"Thuyền buồm Catamaran cao cấp\", \"Chi tiêu cá nhân\"]','2026-10-21 07:52:31'),
(28,6,4,'Hạ Long - Du Thuyền Paradise Elegance Siêu Sang Khám Phá Toàn Cảnh Vịnh 3N2Đ','Kỳ nghỉ dài 3 ngày 2 đêm thư thái trọn vẹn: du ngoạn sâu vào vùng lõi di sản thế giới Vịnh Hạ Long, khám phá Hang Tiên Ông, Làng ngọc trai Tùng Sâu và trải nghiệm câu mực đêm thú vị.',7890000.00,3,'Hà Nội','https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800',250,'2026-10-21','2026-10-24','ACTIVE',5.0,9800000.00,'Xe Limousine đưa đón tận nơi & Du thuyền Paradise Elegance',5,'VIP ĐẲNG CẤP','[\"Hành trình 3N2Đ khám phá sâu các điểm đẹp nhất mà tour ngắn ngày không tới được\", \"Thưởng thức ẩm thực của đầu bếp đạt chuẩn Michelin trên nhà hàng Le Marin\", \"Tham gia lớp học nấu ăn nghệ thuật tỉa củ quả truyền thống Việt Nam\", \"Trải nghiệm câu mực đêm cùng các thủy thủ đoàn mến khách\"]','[{\"day\": 1, \"title\": \"Hà Nội - Hạ Long - Check-in Paradise Elegance - Hang Luồn\", \"content\": \"Đón tại Hà Nội đi Tuần Châu. Lên du thuyền Paradise Elegance. Bắt đầu hành trình qua Động Mê Cung, Hòn Trống Mái. Chèo thuyền Kayak tại Hang Luồn. Tiệc Live Music trên sundeck.\"}, {\"day\": 2, \"title\": \"Làng Chài Cửa Vạn - Hang Tiên Ông - Đảo Hồ Động Tiên\", \"content\": \"Chuyển sang tàu ngày chuyên dụng khám phá Làng Chài Cửa Vạn cổ xưa, thăm Hang Tiên Ông với dấu tích người tiền sử. Chiều tắm biển bãi cát tự nhiên vắng người.\"}, {\"day\": 3, \"title\": \"Hang Sửng Sốt - Trở Về Đất Liền - Hà Nội\", \"content\": \"Bách bộ khám phá Hang Sửng Sốt với vòm hang kỳ vĩ hàng triệu năm. Dùng bữa trưa buffet sớm. Xe Limousine đưa đoàn về lại trung tâm Hà Nội.\"}]','[\"Cabin Suite ban công riêng view panorama vịnh\", \"Toàn bộ các bữa ăn gourmet cao cấp suốt hành trình\", \"Kayak không giới hạn\", \"Vé thắng cảnh trọn gói 3N2Đ\"]','[\"Đồ uống rượu ngoại\", \"Spa & Sauna\", \"Chi tiêu cá nhân\"]','2026-10-21 07:52:31'),
(29,6,2,'Sông Sài Gòn - Tiệc Tối 5 Sao Du Thuyền Saigon Princess Lung Linh 1 Đêm','Chiêm ngưỡng vẻ đẹp hoa lệ của \'Hòn ngọc Viễn Đông\' về đêm: thưởng thức set menu ẩm thực thượng hạng, ngắm tòa nhà Landmark 81 rực rỡ và các cây cầu biểu tượng từ giữa lòng sông Sài Gòn.',1250000.00,1,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=800',400,'2026-10-21','2026-10-22','ACTIVE',4.9,1600000.00,'Du Thuyền 5 Sao Saigon Princess đạt chuẩn Hoàng Gia',5,'TRẢI NGHIỆM ĐỘC ĐÁO','[\"Thưởng thức bữa tối Set Menu 5 món fine-dining do bếp trưởng 5 sao chế biến\", \"Hành trình lướt êm 2 tiếng ngắm toàn cảnh skyline Sài Gòn và Landmark 81 rực sáng\", \"Không gian kiến trúc cổ điển châu Âu hoàng gia sang trọng và lãng mạn\", \"Thưởng thức ban nhạc sống trình diễn các bản tình ca acoustic du dương\"]','[{\"day\": 1, \"title\": \"18h00 Đón Khách Tại Cảng Sài Gòn - 19h30 Du Ngoạn - 21h30 Kết Thúc\", \"content\": \"18h00 quý khách có mặt tại Cảng Sài Gòn (Số 5 Nguyễn Tất Thành, Q.4). Nhận bàn ăn hoa tươi nến lung linh. 19h30 tàu rời bến xuôi dòng ngắm Cầu Ba Son, bến Bạch Đằng, Tòa nhà Bitexco và Landmark 81. 21h30 tàu cập bến trả khách.\"}]','[\"Hành trình 2 tiếng du ngoạn trên sông Sài Gòn\", \"Bữa tối ẩm thực cao cấp 5 món theo thực đơn Fusion Âu - Á\", \"Chương trình ban nhạc sống biểu diễn trực tiếp\", \"Bảo hiểm đường thủy nội địa\"]','[\"Đồ uống tự gọi (rượu vang, cocktail)\", \"Chi phí gửi xe tại bến cảng\", \"Tiền tip ban nhạc\"]','2026-10-21 07:52:31'),
(30,6,3,'Vịnh Bái Tử Long - Du Thuyền Gỗ Cổ Điển Dragon Legend 3N2Đ','Hành trình ngược về thiên nhiên hoang sơ không tì vết: thám hiểm Vịnh Bái Tử Long tĩnh lặng, ghé thăm công viên Hòn Xếp, chèo thuyền kayak qua những vịnh cát trắng mịn không bóng người.',6900000.00,3,'Hà Nội','https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800',240,'2026-10-21','2026-10-24','ACTIVE',4.9,8500000.00,'Xe Limousine đưa đón khứ hồi Hà Nội & Du thuyền Dragon Legend',5,'SINH THÁI NGUYÊN SƠ','[\"Khám phá Vịnh Bái Tử Long hoang sơ tuyệt đối ít tàu bè du lịch\", \"Du thuyền gỗ phong cách rồng thời Lý chạm khắc thủ công tinh xảo\", \"Bữa tối tiệc nướng BBQ trên bãi biển hoang đảo lãng mạn dưới ngàn sao\", \"Chèo thuyền Kayak khám phá Hang Thiên Cảnh Sơn\"]','[{\"day\": 1, \"title\": \"Hà Nội - Cảng Quốc Tế Hạ Long - Du Thuyền Bái Tử Long\", \"content\": \"Limousine đưa đoàn đến cảng. Lên du thuyền thưởng thức bữa trưa ngắm núi đá vôi Bái Tử Long kỳ thú. Chiều chèo kayak tại Đầm Đơn. Thư giãn bồn sục khoáng trên tàu.\"}, {\"day\": 2, \"title\": \"Hang Cỏ - Bãi Biển Vung Hà - Tiệc Nướng Bãi Biển\", \"content\": \"Khám phá thạch nhũ nguyên sinh Hang Cỏ. Chiều tắm biển chèo thuyền tại Vung Đặng. Tối thưởng thức tiệc BBQ bãi biển ấm cúng với lửa trại và hải sản nướng.\"}, {\"day\": 3, \"title\": \"Làng Chài Vung Viêng - Thăm Lò Gốm - Hà Nội\", \"content\": \"Ngồi thuyền nan mộc mạc thăm Làng Chài Vung Viêng. Thưởng thức bữa trưa chia tay. Xe đưa đoàn về lại Hà Nội, dừng chân xem biểu diễn múa rối nước tại Hải Dương.\"}]','[\"Phòng Suite gỗ sang trọng view biển\", \"Toàn bộ các bữa ăn hải sản cao cấp trên tàu\", \"Tiệc BBQ trên bãi biển riêng tư\", \"Hướng dẫn viên tiếng Anh/Việt nhiệt tình\"]','[\"Đồ uống minibar\", \"Chi tiêu cá nhân\", \"Thuế VAT\"]','2026-10-21 07:52:31'),
(31,7,4,'Trekking Thám Hiểm Hang Én - Hang Động Tự Nhiên Lớn Thứ 3 Thế Giới 2N1Đ','Chinh phục kỳ quan thiên nhiên ngoạn mục bậc nhất hành tinh: băng rừng nguyên sinh Phong Nha, lội suối Rào Thương, cắm trại trên bãi cát mịn trong lòng hang vòm đá khổng lồ kỳ ảo.',7600000.00,2,'Quảng Bình','https://images.unsplash.com/photo-1551632811-561732d1e306?w=800',220,'2026-10-21','2026-10-23','ACTIVE',5.0,8900000.00,'Xe chuyên dụng địa hình 4x4 đón tiễn Phong Nha',4,'CHINH PHỤC ĐỈNH CAO','[\"Thám hiểm Hang Én - hang động tự nhiên lớn thứ 3 thế giới được đài BBC vinh danh\", \"Trải nghiệm cắm trại ngủ lều trên bãi cát trắng mịn màng bên bờ hồ xanh trong lòng hang\", \"Ghé thăm Bản Đoòng của đồng bào Bru-Vân Kiều nằm cô lập giữa đại ngàn\", \"Đội ngũ chuyên gia an toàn và porter chuẩn quốc tế đồng hành chăm sóc chu đáo\"]','[{\"day\": 1, \"title\": \"Phong Nha - Bản Đoòng - Băng Rừng Lội Suối - Cửa Sau Hang Én\", \"content\": \"Họp phổ biến an toàn tại văn phòng. Xe đưa đoàn đến Km35 Đường Hồ Chí Minh Tây. Bắt đầu trekking xuyên rừng già xuống thung lũng Bản Đoòng. Lội suối Rào Thương tiến vào cửa sau Hang Én. Cắm trại bên hồ nước ngọc bích trong lòng hang.\"}, {\"day\": 2, \"title\": \"Khám Phá Cửa Trước Hang Én - Leo Dốc Ba Giàn - Phong Nha\", \"content\": \"Chiêm ngưỡng giếng trời khổng lồ cửa trước Hang Én nơi hàng vạn cánh én chao lượn. Băng qua các bãi thạch nhũ tổ ong kỳ lạ. Trekking leo dốc Ba Giàn thử thách thể lực. Xe đón đoàn về khách sạn Phong Nha liên hoan tổng kết.\"}]','[\"Trọn gói trang thiết bị thám hiểm chuẩn quốc tế: mũ bảo hiểm, đèn Petzl, găng tay\", \"Đội ngũ porter gùi hành lý, đầu bếp nấu ăn nóng hổi trong hang\", \"Lều trại, túi ngủ dày ấm, đệm khí êm ái\", \"Bảo hiểm thám hiểm mạo hiểm mức 150.000.000 VNĐ\"]','[\"Vé máy bay / tàu hỏa đến Quảng Bình\", \"Quần áo giày trekking cá nhân\", \"Tiền tip cho đội ngũ porter và chuyên gia\"]','2026-10-21 07:52:31'),
(32,7,2,'Trekking Tà Xùa Săn Biển Mây Đại Ngàn - Sống Lưng Khủng Long 3N2Đ','Chinh phục thiên đường mây Tây Bắc đẹp nghẹt thở: đi bộ trên Sống Lưng Khủng Long Háng Đồng chênh vênh giữa biển mây cuồn cuộn, ngắm cây táo mèo cô đơn và mỏm cá heo kỳ thú.',3200000.00,3,'Hà Nội','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',300,'2026-10-21','2026-10-24','ACTIVE',4.9,3900000.00,'Xe du lịch đời mới vượt dốc cao',3,'SĂN MÂY ĐỈNH CAO','[\"Chinh phục Sống Lưng Khủng Long Háng Đồng hùng vĩ giữa 4 bề mây trắng\", \"Check-in Mỏm Cá Heo và Cây Táo Mèo cô đơn góc chụp ảnh huyền thoại\", \"Thưởng thức ly cà phê nóng hổi ngắm hoàng hôn buông xuống thung lũng mây Tà Xùa\", \"Thưởng thức lẩu gà đen H\'Mông và thịt gác bếp nướng than hồng\"]','[{\"day\": 1, \"title\": \"Hà Nội - Bắc Yên - Đỉnh Gió Tà Xùa Đón Hoàng Hôn\", \"content\": \"Khởi hành từ Hà Nội qua đèo Nhọt đến Bắc Yên. Lên xã vùng cao Tà Xùa. Nhận homestay view thung lũng mây. Chiều ngắm hoàng hôn rực rỡ tại Đỉnh Gió.\"}, {\"day\": 2, \"title\": \"Trekking Sống Lưng Khủng Long - Mỏm Cá Heo - Cây Cô Đơn\", \"content\": \"05h30 sáng trekking trên Sống Lưng Khủng Long Háng Đồng săn biển mây bồng bềnh. Chiều check-in Mỏm Cá Heo và cây táo mèo cô đơn. Tối đốt lửa nướng khoai bắp.\"}, {\"day\": 3, \"title\": \"Thung Lũng Mây Xím Vàng - Trở Về Hà Nội\", \"content\": \"Dạo bộ ngắm ruộng bậc thang Xím Vàng. Mua chè Shan Tuyết cổ thụ trăm tuổi. Khởi hành về đến Hà Nội lúc 19h30.\"}]','[\"Xe vận chuyển chuyên cung đường đèo dốc khứ hồi\", \"Homestay bungalow view săn mây tuyệt đẹp\", \"Các bữa ăn đặc sản Tây Bắc gà đồi lợn bản\", \"Hướng dẫn viên dẫn đường kiêm thợ chụp ảnh có tâm\"]','[\"Xe ôm di chuyển vào sống lưng khủng long\", \"Chi tiêu cá nhân\", \"Đồ uống riêng\"]','2026-10-21 07:52:31'),
(33,7,3,'Trekking Lảo Thẩn - Chinh Phục Nóc Nhà Y Tý Bát Xát Mây Trắng 2N1Đ','Hành trình săn mây kỳ vĩ trên đỉnh Lảo Thẩn 2.860m: ngắm bình minh trên đỉnh núi đá trọc, cắm trại ngắm dải ngân hà Milky Way lung linh giữa không gian đại ngàn hoang hoải.',2800000.00,2,'Hà Nội','https://images.unsplash.com/photo-1528127269322-539801943592?w=800',260,'2026-10-21','2026-10-23','ACTIVE',4.8,3500000.00,'Xe giường nằm Hà Nội - Sa Pa & Xe trung chuyển Y Tý',3,'DÀNH CHO TREKKER','[\"Chinh phục đỉnh Lảo Thẩn 2.860m - nóc nhà Y Tý được mệnh danh là \'cung trekking quốc dân\'\", \"Check-in mỏm đá câu cá nhô ra giữa khoảng không biển mây bạt ngàn\", \"Cắm trại ngủ lán ngắm trời sao lấp lánh và đón ánh bình minh đầu tiên\", \"Khám phá kiến trúc nhà trình tường bằng đất độc đáo của người Hà Nhì\"]','[{\"day\": 1, \"title\": \"Sa Pa - Y Tý - Chân Núi Lảo Thẩn - Lán Nghỉ 2.500m\", \"content\": \"Đón tại Sa Pa đi Y Tý. Gặp porter người Mông, bắt đầu trekking vượt đồi cỏ tranh và rừng đỗ quyên. Đến lán nghỉ 2.500m, ngắm hoàng hôn rực lửa. Ăn tối lợn cắp nách nướng than.\"}, {\"day\": 2, \"title\": \"Chạm Đỉnh Lảo Thẩn 2.860m - Xuống Núi - Về Sa Pa - Hà Nội\", \"content\": \"05h00 sáng chinh phục đỉnh chóp Lảo Thẩn đón bình minh trên biển mây. Chụp ảnh mỏm đá sống ảo. Xuống núi về Sa Pa tắm lá thuốc người Dao Đỏ. Lên xe về Hà Nội.\"}]','[\"Xe đưa đón Sa Pa - Y Tý và xe giường nằm khứ hồi Hà Nội\", \"Lán nghỉ trên núi có chăn ấm đệm êm\", \"Đội ngũ porter hỗ trợ gùi đồ ăn uống\", \"Tắm lá thuốc người Dao Đỏ hồi phục cơ bắp\"]','[\"Chi phí cá nhân\", \"Thuế VAT\", \"Tip cho porter\"]','2026-10-21 07:52:31'),
(34,7,4,'Thám Hiểm Thác K50 - Trái Tim Rừng Già Khu Bảo Tồn Kon Chư Răng 2N2Đ','Chiêm ngưỡng \'đệ nhất thác nước Tây Nguyên\': vượt rừng già nguyên sinh Kon Chư Răng, luồn sâu vào hang đá sau màn nước khổng lồ của Thác K50 để thấy cầu vồng ngũ sắc rực rỡ.',3950000.00,2,'Quy Nhơn','https://images.unsplash.com/photo-1551632811-561732d1e306?w=800',200,'2026-10-21','2026-10-23','ACTIVE',5.0,4800000.00,'Xe ô tô đưa đón Quy Nhơn & Xe bán tải chuyên dụng địa hình',3,'SIÊU PHẨM THIÊN NHIÊN','[\"Khám phá Thác K50 (Thác Hang Én) - tuyệt tác thác nước đẹp bậc nhất Đông Nam Á\", \"Bách bộ luồn vào hốc đá khổng lồ phía sau dòng nước đổ trắng xóa ngắm cầu vồng kép\", \"Cắm trại bên bờ suối hoang sơ thưởng thức tiệc BBQ giữa rừng già đại ngàn\", \"Đắm mình trong làn nước suối xanh trong vắt mát lạnh giải nhiệt mùa hè\"]','[{\"day\": 1, \"title\": \"Quy Nhơn - Kbang Gia Lai - Trạm Kiểm Lâm Kon Chư Răng\", \"content\": \"Xe đón tại Quy Nhơn lên huyện Kbang Gia Lai. Đến Trạm kiểm lâm Khu bảo tồn Kon Chư Răng. Bắt đầu trekking xuyên qua những tán cây cổ thụ nghìn năm tuổi. Chiều đến chân thác K50 cắm trại.\"}, {\"day\": 2, \"title\": \"Chiêm Ngưỡng Vòm Hang Thác K50 - Xuất Rừng - Về Quy Nhơn\", \"content\": \"Khám phá vòm hang đá kỳ bí sau thác K50, chụp ảnh cầu vồng ngũ sắc. Tắm suối trong vắt. Bắt đầu hành trình xuất rừng. Xe đón đoàn về Quy Nhơn thưởng thức hải sản mừng thành công.\"}]','[\"Xe đưa đón chất lượng cao khứ hồi Quy Nhơn\", \"Lều trại chống thấm, túi ngủ, đèn pin chiếu sáng\", \"Toàn bộ các bữa ăn dinh dưỡng trong rừng do porter chuẩn bị\", \"Phí bảo tồn thiên nhiên và kiểm lâm dẫn đường\"]','[\"Vé máy bay đến Quy Nhơn\", \"Giày leo núi và trang phục cá nhân\"]','2026-10-21 07:52:31'),
(35,7,2,'Trekking Tà Năng Phan Dũng - Cung Đường Biển Mây Đẹp Nhất Việt Nam 3N2Đ','Chinh phục cung đường trekking huyền thoại: đi qua 3 tỉnh Lâm Đồng - Ninh Thuận - Bình Thuận, băng qua những đồi cỏ xanh ngút ngàn như thảo nguyên Thụy Sĩ, hạ độ cao xuống rừng khộp Bình Thuận.',3600000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',250,'2026-10-21','2026-10-24','ACTIVE',4.9,4400000.00,'Xe Universe đưa đón TP.HCM và xe ôm công nghệ rừng chở đồ',3,'HUYỀN THOẠI TREKKING','[\"Chinh phục cung đường trekking 35km đẹp nhất Việt Nam nối liền cao nguyên và miền biển\", \"Check-in cột mốc giao thoa 3 tỉnh Lâm Đồng - Ninh Thuận - Bình Thuận\", \"Chiêm ngưỡng những đồi cỏ xanh mướt trải dài vô tận tựa thảo nguyên châu Âu\", \"Cắm trại trên đỉnh đồi lộng gió đón ánh bình minh và ngắm hoàng hôn rực rỡ\"]','[{\"day\": 1, \"title\": \"TP.HCM - Tà Hine - Bìa Rừng Tà Năng - Đỉnh Cỏ Đồi Lộng Gió\", \"content\": \"Xe đêm xuất phát từ TP.HCM đến Tà Hine ăn sáng. Bắt đầu trekking xuyên rừng thông Tà Năng. Leo các con dốc đồi cỏ tuyệt đẹp. Dựng lều cắm trại trên đỉnh đồi cao nhất đón hoàng hôn.\"}, {\"day\": 2, \"title\": \"Mốc 3 Tỉnh - Hạ Độ Cao Phan Dũng - Cắm Trại Bên Suối\", \"content\": \"Đón bình minh tuyệt đẹp. Tiếp tục băng qua các con dốc sống trâu. Chụp ảnh mốc 3 tỉnh. Bắt đầu hạ độ cao xuống rừng khộp Phan Dũng. Cắm trại bên suối mát tắm giặt.\"}, {\"day\": 3, \"title\": \"Rừng Khộp Phan Dũng - Xe Trung Chuyển Grab Rừng - Về TP.HCM\", \"content\": \"Đi bộ 7km đường bằng rừng khộp ra bìa rừng Phan Dũng. Trải nghiệm xe ôm Grab rừng vượt suối. Ăn trưa tại Liên Hương. Xe đưa đoàn về TP.HCM kết thúc trọn vẹn.\"}]','[\"Xe du lịch giường nằm máy lạnh khứ hồi\", \"Lều trại cắm trại cao cấp 2 người/lều\", \"Xe ôm rừng hỗ trợ đoạn ra khỏi rừng\", \"Hướng dẫn viên và người dẫn đường bản địa am hiểu địa hình\"]','[\"Chi phí cá nhân ngoài chương trình\", \"Đồ ăn vặt tự mang\"]','2026-10-21 07:52:31'),
(36,8,2,'Thái Lan: Bangkok - Pattaya - Đảo San Hô Coral Island - Chùa Vàng 5N4Đ','Kỳ nghỉ sôi động tại xứ sở Chùa Vàng: tắm biển Đảo San Hô Coral Island, chiêm bái Tượng Phật Lớn Wat Phra Yai, xem Alcazar Show hoành tráng và thỏa sức mua sắm tại IconSiam.',6990000.00,5,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=800',380,'2026-10-21','2026-10-26','ACTIVE',4.9,8500000.00,'Máy bay khứ hồi Vietnam Airlines / Vietjet Air bao gồm 20kg ký gửi',4,'BÁN CHẠY NHẤT','[\"Dạo cano cao tốc tắm biển lặn ngắm san hô tại Đảo Coral Pattaya\", \"Thưởng thức chương trình đại nhạc hội Alcazar Show / Colosseum Show lộng lẫy\", \"Viếng Chùa Thuyền Wat Yannawa và Chùa Phật Vàng Wat Traimit 5,5 tấn vàng ròng\", \"Thưởng thức đại tiệc buffet Baiyoke Sky 86 tầng cao nhất Bangkok\"]','[{\"day\": 1, \"title\": \"TP.HCM / Hà Nội - Bangkok - Thành Phố Biển Pattaya\", \"content\": \"Bay đến sân bay Suvarnabhumi Bangkok. Xe và HDV đón đoàn di chuyển về Pattaya. Ghé thăm Chợ nổi 4 miền Thái Lan. Tối tự do khám phá phố đi bộ Walking Street.\"}, {\"day\": 2, \"title\": \"Cano Đi Đảo San Hô Coral - Trân Bảo Phật Sơn - Alcazar Show\", \"content\": \"Cano đưa sang Đảo Coral tắm biển, chơi dù bay. Thăm Núi Phật Vàng Khau Chee Chan khắc bằng 999kg vàng 24K. Tối xem Alcazar Show của các nghệ sĩ chuyển giới.\"}, {\"day\": 3, \"title\": \"Pattaya - Vườn Bách Thảo Nong Nooch - Bangkok - IconSiam\", \"content\": \"Thăm Vườn nhiệt đới Nong Nooch xem xiếc voi biểu diễn. Về Bangkok check-in TTTM siêu xa xỉ IconSiam bên bờ sông Chao Phraya. Xem nhạc nước ánh sáng.\"}, {\"day\": 4, \"title\": \"Dạo Thuyền Sông Chao Phraya - Chùa Phật Vàng - Buffet Baiyoke Sky\", \"content\": \"Dạo thuyền trên dòng sông mẹ Chao Phraya ngắm cá nổi. Viếng Chùa Phật Vàng Wat Traimit. Thưởng thức buffet quốc tế trên đỉnh tòa nhà Baiyoke Sky 86 tầng.\"}, {\"day\": 5, \"title\": \"Viếng Phật Bốn Mặt Erawan - Mua Sắm BigC - Tiễn Sân Bay\", \"content\": \"Chiêm bái Đền Phật Bốn Mặt Erawan linh thiêng giữa trung tâm Bangkok. Tự do mua sắm tại Central World / Big C. Xe đưa ra sân bay đáp chuyến bay về Việt Nam.\"}]','[\"Vé máy bay khứ hồi bao gồm 20kg ký gửi + 7kg xách tay\", \"Khách sạn 4 sao tiêu chuẩn quốc tế tại Bangkok và Pattaya\", \"Vé xem Alcazar Show và buffet Baiyoke Sky 86 tầng\", \"Bảo hiểm du lịch quốc tế mức bồi thường 210.000.000 VNĐ\"]','[\"Hộ chiếu còn hạn trên 6 tháng\", \"Tiền tip quy định bắt buộc cho HDV và tài xế (5 USD/khách/ngày)\", \"Chi tiêu cá nhân ngoài chương trình\"]','2026-10-21 07:52:31'),
(37,8,3,'Singapore - Malaysia: Garden By The Bay - Tháp Đôi Petronas - Cao Nguyên Genting 5N4Đ','Một hành trình hai quốc gia hiện đại bậc nhất Đông Nam Á: ngắm siêu cây Garden By The Bay Singapore, check-in Tháp Đôi Petronas Kuala Lumpur và đi cáp treo lên Cao nguyên Genting mờ sương.',10990000.00,5,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800',320,'2026-10-21','2026-10-26','ACTIVE',5.0,13500000.00,'Máy bay khứ hồi Singapore Airlines / Malaysia Airlines',4,'TOUR QUỐC TẾ HOT','[\"Khám phá kỳ quan kiến trúc Gardens By The Bay và thác nước trong nhà Flower Dome\", \"Check-in Công viên Sư Tử Biển Merlion Park biểu tượng quốc đảo Singapore\", \"Chụp ảnh lưu niệm tại Tháp Đôi Petronas Twin Towers cao 452m lừng danh\", \"Đi cáp treo mây vượt núi lên Thành phố giải trí trên mây Cao Nguyên Genting\"]','[{\"day\": 1, \"title\": \"TP.HCM - Sân Bay Changi Đẹp Nhất Thế Giới - Singapore City Tour\", \"content\": \"Đáp xuống sân bay Changi, ngắm thác nước Jewel khổng lồ. Tham quan Công viên Sư Tử Biển Merlion Park, Nhà hát Trái Sầu Riêng Esplanade. Tối xem show ánh sáng Spectra Show bên vịnh Marina.\"}, {\"day\": 2, \"title\": \"Gardens By The Bay - Đảo Sentosa - Xuất Cảnh Sang Malacca Malaysia\", \"content\": \"Chiêm ngưỡng siêu cây khổng lồ Gardens By The Bay. Sang Đảo Sentosa chụp ảnh biểu tượng Universal Studios. Chiều làm thủ tục qua cửa khẩu sang thành phố cổ Malacca Malaysia.\"}, {\"day\": 3, \"title\": \"Phố Cổ Malacca - Quảng Trường Hà Lan - Thủ Đô Kuala Lumpur\", \"content\": \"Dạo Quảng trường Đỏ Hà Lan, Pháo đài Famosa, Nhà thờ Thánh Paul. Khởi hành về thủ đô Kuala Lumpur. Chụp ảnh dưới chân Tháp Đôi Petronas Twin Towers rực rỡ ánh đèn.\"}, {\"day\": 4, \"title\": \"Động Batu Huyền Bí - Cáp Treo Lên Cao Nguyên Genting\", \"content\": \"Chinh phục 272 bậc thang rực rỡ sắc màu tại Thánh địa Hindu Động Batu. Lên cáp treo Genting Skyway lên đỉnh cao nguyên mây Genting thử vận may tại sòng bạc Casino hợp pháp.\"}, {\"day\": 5, \"title\": \"Cung Điện Hoàng Gia - Thành Phố Mới Putrajaya - Bay Về TP.HCM\", \"content\": \"Thăm Cung điện Hoàng Gia Istana Negara, Thành phố thông minh Putrajaya và Thánh đường Hồi giáo màu hồng Putra Mosque. Xe tiễn sân bay KLIA về lại TP.HCM.\"}]','[\"Vé máy bay khứ hồi quốc tế\", \"Khách sạn 4 sao trọn gói suốt hành trình tại Singapore và Malaysia\", \"Vé cáp treo Genting và vé tham quan các điểm\", \"Bảo hiểm du lịch quốc tế\"]','[\"Tiền tip cho HDV và tài xế địa phương (5 USD/ngày)\", \"Chi tiêu mua sắm cá nhân\", \"Phụ thu phòng đơn\"]','2026-10-21 07:52:31'),
(38,8,4,'Nhật Bản Mùa Hoa: Tokyo - Núi Phú Sĩ - Kyoto - Lâu Đài Osaka 6N5Đ','Hành trình vàng khám phá xứ sở Mặt trời mọc: ngắm núi Phú Sĩ tuyết phủ soi bóng hồ Kawaguchi, mặc kimono dạo phố cổ Kyoto nghìn năm, chiêm ngưỡng Lâu đài Osaka uy nghiêm.',29900000.00,6,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=800',200,'2026-10-21','2026-10-27','ACTIVE',5.0,35000000.00,'Máy bay khứ hồi 5 sao All Nippon Airways (ANA) / Japan Airlines',4,'ĐẲNG CẤP XỨ PHÙ TANG','[\"Chinh phục Trạm số 5 Núi Phú Sĩ - biểu tượng thiêng liêng của xứ sở hoa anh đào\", \"Trải nghiệm đi tàu cao tốc Shinkansen vận tốc 320km/h biểu tượng công nghệ Nhật\", \"Dạo bước qua hàng ngàn cổng Torii màu đỏ cam tại Đền Fushimi Inari Kyoto\", \"Thưởng thức bò Kobe thượng hạng nướng teppanyaki tan chảy trong miệng\"]','[{\"day\": 1, \"title\": \"TP.HCM - Sân Bay Narita Tokyo - Nghỉ Đêm Tokyo\", \"content\": \"Bay thẳng từ TP.HCM đến Narita Tokyo trên chuyến bay 5 sao ANA. Xe đón về khách sạn trung tâm thủ đô Tokyo nghỉ ngơi.\"}, {\"day\": 2, \"title\": \"Chùa Asakusa Kannon - Tháp Tokyo Skytree - Núi Phú Sĩ\", \"content\": \"Viếng ngôi chùa cổ nhất Tokyo Asakusa Sensoji. Chụp ảnh Tháp Tokyo Skytree. Di chuyển về khu vực Núi Phú Sĩ. Trải nghiệm tắm suối khoáng nóng Onsen truyền thống.\"}, {\"day\": 3, \"title\": \"Núi Phú Sĩ Trạm 5 - Làng Cổ Oshino Hakkai - Trải Nghiệm Shinkansen\", \"content\": \"Lên trạm 5 Núi Phú Sĩ ngắm tuyết trắng. Dạo bước làng cổ Oshino Hakkai thanh bình với 8 hồ nước tan từ tuyết núi Phú Sĩ. Lên tàu siêu tốc Shinkansen về thành phố Nagoya.\"}, {\"day\": 4, \"title\": \"Nagoya - Cố Đô Kyoto - Đền Ngàn Cổng Fushimi Inari - Chùa Vàng Kinkakuji\", \"content\": \"Đến Cố đô Kyoto, viếng Chùa Vàng Kinkakuji dát vàng lộng lẫy soi bóng hồ nước. Dạo bước dưới hàng ngàn cánh cổng Torii đỏ thắm tại Đền Fushimi Inari Taisha.\"}, {\"day\": 5, \"title\": \"Kyoto - Thành Phố Osaka - Lâu Đài Osaka - Mua Sắm Shinsaibashi\", \"content\": \"Di chuyển về Osaka. Tham quan và chụp ảnh lưu niệm tại khuôn viên Lâu đài Osaka biểu tượng. Tự do mua sắm tại khu phố thương mại sầm uất Shinsaibashi và Dotonbori.\"}, {\"day\": 6, \"title\": \"Sân Bay Kansai Osaka - Bay Về TP.HCM\", \"content\": \"Dùng bữa sáng buffet tại khách sạn. Xe đưa đoàn ra sân bay quốc tế Kansai đáp chuyến bay về lại TP.HCM kết thúc hải trình hoàn mỹ.\"}]','[\"Vé máy bay khứ hồi hàng không 5 sao có 2 kiện hành lý ký gửi (mỗi kiện 23kg)\", \"Khách sạn tiêu chuẩn 4 sao Nhật Bản có trải nghiệm tắm Onsen\", \"Trọn gói visa nhập cảnh Nhật Bản diện du lịch đoàn\", \"Thực đơn bữa tối bò Kobe và lẩu Shabu Shabu hảo hạng\"]','[\"Tiền tip tài xế và HDV Nhật Bản (8 USD/khách/ngày)\", \"Chi tiêu cá nhân ngoài chương trình\", \"Phí nâng hạng vé máy bay thương gia\"]','2026-10-21 07:52:31'),
(39,8,2,'Hàn Quốc: Seoul - Đảo Nami Lãng Mạn - Công Viên Lotte World - Tháp Namsan 5N4Đ','Trải nghiệm văn hóa xứ sở Kim Chi: dạo bước dưới hàng cây ngân hạnh lãng mạn tại Đảo Nami (phim Bản Tình Ca Mùa Đông), thử mặc Hanbok tại Cung điện Gyeongbokgung, vui chơi thỏa thích tại Lotte World.',14500000.00,5,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800',280,'2026-10-21','2026-10-26','ACTIVE',4.9,17800000.00,'Máy bay khứ hồi Vietnam Airlines / Korean Air',4,'LÃNG MẠN XỨ HÀN','[\"Dạo bước trên Đảo Nami - phim trường của bộ phim huyền thoại \'Bản Tình Ca Mùa Đông\'\", \"Mặc trang phục truyền thống Hanbok chụp ảnh tại Cung điện hoàng gia Gyeongbokgung\", \"Vui chơi thả ga tại Lotte World - công viên giải trí trong nhà lớn nhất thế giới\", \"Check-in Tháp truyền hình Namsan Seoul gắn ổ khóa tình yêu vĩnh cửu\"]','[{\"day\": 1, \"title\": \"TP.HCM - Sân Bay Quốc Tế Incheon Seoul\", \"content\": \"Bay đêm từ sân bay Tân Sơn Nhất đi Seoul. Nghỉ đêm trên máy bay.\"}, {\"day\": 2, \"title\": \"Seoul - Khám Phá Đảo Nami Xinh Đẹp - Tháp Namsan\", \"content\": \"Sáng đến sân bay Incheon, thưởng thức bữa sáng canh sườn bò nóng hổi. Khởi hành đi Đảo Nami. Chiều về Seoul ngắm hoàng hôn và gắn ổ khóa tình yêu tại Tháp Namsan.\"}, {\"day\": 3, \"title\": \"Cung Điện Gyeongbokgung - Bảo Tàng Dân Gian - Nhà Xanh Cheongwadae\", \"content\": \"Mặc Hanbok check-in Cung điện Cảnh Phúc Gyeongbokgung, viếng Viện Bảo tàng Dân tộc Quốc gia, chụp ảnh ngoài Phủ Tổng Thống Nhà Xanh. Chiều mua sắm sâm chính phủ.\"}, {\"day\": 4, \"title\": \"Công Viên Giải Trí Lotte World - Mua Sắm Chợ Myeongdong\", \"content\": \"Khám phá công viên giải trí Lotte World với hàng chục trò chơi mạo hiểm. Tối dạo phố đi bộ Myeongdong thưởng thức ẩm thực đường phố tokbokki, chả cá oden.\"}, {\"day\": 5, \"title\": \"Lớp Học Làm Kim Chi Mặc Hanbok - Sân Bay Incheon Về TP.HCM\", \"content\": \"Tham gia lớp học tự tay làm món kim chi truyền thống. Ghé siêu thị Ponglim mua quà bánh kẹo. Xe đưa ra sân bay Incheon bay về TP.HCM.\"}]','[\"Vé máy bay khứ hồi quốc tế có 20kg ký gửi\", \"Khách sạn 4 sao trung tâm thủ đô Seoul\", \"Trọn gói visa du lịch Hàn Quốc\", \"Vé vào cổng Đảo Nami và Công viên Lotte World\"]','[\"Tiền tip quy định (6 USD/khách/ngày)\", \"Chi phí cá nhân\", \"Phụ thu phòng đơn\"]','2026-10-21 07:52:31'),
(40,8,3,'Châu Âu 4 Nước: Pháp - Thụy Sĩ - Ý - Vatican 10N9Đ: Tháp Eiffel - Đỉnh Núi Titlis - Đấu Trường Colosseum','Hành trình trong mơ khám phá trái tim Châu Âu cổ kính và hoa lệ: chiêm ngưỡng Tháp Eiffel biểu tượng và du thuyền sông Seine thơ mộng tại Paris, chinh phục đỉnh tuyết vĩnh cửu Titlis Thụy Sĩ bằng cáp treo xoay 360 độ, dạo thuyền Gondola tại Venice và ngắm Đấu trường Colosseum La Mã.',68900000.00,10,'TP. Hồ Chí Minh / Hà Nội','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=1200&q=80',240,'2026-10-21','2026-10-26','ACTIVE',5.0,76000000.00,'Máy bay khứ hồi hàng không 5 sao Qatar Airways / Turkish Airlines bao gồm 30kg ký gửi',4,'TOUR CAO CẤP','[\"Chụp ảnh lưu niệm tại Tháp Eiffel biểu tượng và du thuyền trên dòng sông Seine Paris\", \"Chinh phục đỉnh núi tuyết Titlis Thụy Sĩ cao 3.020m bằng cáp treo xoay Rotair 360 độ\", \"Du ngoạn thành phố nổi Venice lãng mạn trên những chiếc thuyền Gondola truyền thống\", \"Chiêm ngưỡng Đấu trường La Mã Colosseum và Quảng trường Thánh Peter tại Vatican\"]','[{\"day\": 1, \"title\": \"TP.HCM / Hà Nội - Paris (Pháp)\", \"content\": \"Đoàn tập trung tại sân bay quốc tế Tân Sơn Nhất / Nội Bài làm thủ tục đáp chuyến bay thẳng hoặc quá cảnh 5 sao đi Paris. Nghỉ đêm trên máy bay.\"}, {\"day\": 2, \"title\": \"Kinh Đô Ánh Sáng Paris - Khải Hoàn Môn - Tháp Eiffel - Du Thuyền Sông Seine\", \"content\": \"Đến Paris hoa lệ. Xe đón đoàn tham quan Khải Hoàn Môn (Arc de Triomphe), Đại lộ Champs-Élysées danh tiếng. Chụp ảnh tại Tháp Eiffel biểu tượng nước Pháp. Chiều trải nghiệm du thuyền Bateaux Mouches lướt êm trên dòng sông Seine ngắm toàn cảnh các cây cầu cổ kính.\"}, {\"day\": 3, \"title\": \"Bảo Tàng Louvre - Nhà Thờ Đức Bà Paris - Di Chuyển Đi Thụy Sĩ\", \"content\": \"Chiêm ngưỡng Kim Tự Tháp kính tại Bảo tàng Louvre, chụp ảnh bên ngoài Nhà Thờ Đức Bà Paris. Khởi hành bằng tàu cao tốc TGV xuyên biên giới sang thị trấn cổ tích Thụy Sĩ.\"}, {\"day\": 4, \"title\": \"Thụy Sĩ: Engelberg - Chinh Phục Đỉnh Núi Tuyết Titlis - Lucerne\", \"content\": \"Trải nghiệm cáp treo xoay 360 độ Titlis Rotair đầu tiên trên thế giới lên đỉnh Titlis tuyết trắng vĩnh cửu ở độ cao 3.020m. Về thành phố Lucerne thơ mộng: check-in Cầu Gỗ Chapel cổ kính và Tượng đài Sư tử đá Lion Monument.\"}, {\"day\": 5, \"title\": \"Lucerne - Milan Kinh Đô Thời Trang Ý - Nhà Thờ Duomo\", \"content\": \"Khởi hành sang nước Ý đến Milan. Chiêm ngưỡng vẻ đẹp kiến trúc Gothic kỳ vĩ của Nhà thờ chính tòa Duomo Milan và dạo bước trong trung tâm mua sắm Galleria Vittorio Emanuele II.\"}, {\"day\": 6, \"title\": \"Milan - Thành Phố Kênh Đào Venice Lãng Mạn\", \"content\": \"Đi tàu ra Đảo Venice - thành phố nổi kỳ diệu trên biển Adriatic. Tham quan Quảng trường Thánh Mark, Cầu Than Thở (Bridge of Sighs), xưởng chế tác thủy tinh Murano và trải nghiệm ngồi thuyền Gondola ngắm nhìn những dãy phố cổ kính.\"}, {\"day\": 7, \"title\": \"Venice - Tháp Nghiêng Pisa Kỳ Diệu\", \"content\": \"Khởi hành đến thành phố Pisa vùng Tuscany. Chiêm ngưỡng Quần thể Quảng trường Màu Nhiệm (Piazza dei Miracoli) và Tháp Nghiêng Pisa - một trong những kỳ quan kiến trúc thế giới độc đáo nhất.\"}, {\"day\": 8, \"title\": \"Pisa - Thủ Đô Rome Cổ Kính - Đấu Trường Colosseum\", \"content\": \"Đến thủ đô Rome lịch sử nghìn năm. Tham quan bên ngoài Đấu Trường La Mã Colosseum vĩ đại, Đài Phun Nước Trevi ném đồng xu ước nguyện quay lại thành Rome và Bậc Thang Tây Ban Nha.\"}, {\"day\": 9, \"title\": \"Vương Quốc Vatican - Quảng Trường Thánh Peter - Sân Bay Rome\", \"content\": \"Viếng thăm Quốc gia nhỏ nhất thế giới Vatican, chiêm ngưỡng Vương Cung Thánh Đường Thánh Peter tráng lệ tuyệt mỹ. Mua sắm đồ lưu niệm. Xe tiễn đoàn ra sân bay Rome Fiumicino đáp chuyến bay về Việt Nam.\"}, {\"day\": 10, \"title\": \"Về Đến TP.HCM / Hà Nội\", \"content\": \"Máy bay hạ cánh an toàn tại sân bay Tân Sơn Nhất / Nội Bài. Kết thúc hành trình 10 ngày 9 đêm khám phá Châu Âu tuyệt đẹp đầy kỷ niệm đáng nhớ.\"}]','[\"Vé máy bay quốc tế khứ hồi hàng không 5 sao Qatar Airways / Turkish Airlines (bao gồm 30kg ký gửi + 7kg xách tay)\", \"Khách sạn 4 sao tiêu chuẩn quốc tế Châu Âu suốt hành trình (2 khách/phòng)\", \"Lệ phí visa Schengen và dịch thuật hồ sơ công chứng trọn gói\", \"Vé cáp treo xoay 360 độ chinh phục Đỉnh Núi Tuyết Titlis Thụy Sĩ\", \"Vé du thuyền sông Seine Paris và thuyền Gondola Venice\", \"Bảo hiểm du lịch quốc tế hạn mức bồi thường lên tới 1.050.000.000 VNĐ\"]','[\"Hộ chiếu còn hạn trên 6 tháng tính từ ngày kết thúc tour\", \"Tiền tip quy định bắt buộc cho Hướng dẫn viên và Tài xế Châu Âu (8 EUR/khách/ngày)\", \"Chi phí cá nhân ngoài chương trình (giặt ủi, điện thoại, mua sắm)\"]','2026-10-21 07:52:31'),
(41,1,1,'Phan Thiết - Mũi Né - Đồi Cát Bay - Bàu Trắng - Lâu Đài Rượu Vang 3N2Đ','Thỏa sức vi vu tiểu sa mạc Bàu Trắng, ngắm hoàng hôn rực rỡ trên Đồi Cát Hồng, trải nghiệm xe jeep địa hình và thưởng thức rượu vang hảo hạng tại Lâu Đài Rượu Vang RD đẳng cấp châu Âu.',2650000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=80',320,'2026-11-14','2026-11-16','ACTIVE',4.8,3250000.00,'Xe du lịch Limousine cao cấp 29 chỗ đời mới',4,'HOT DEAL','[\"Trải nghiệm cảm giác mạnh lái xe mô tô và xe jeep vượt đồi cát Bàu Trắng\",\"Check-in Lâu Đài Rượu Vang RD phong cách châu Âu thời Trung Cổ\",\"Thưởng thức tiệc hải sản tươi sống tại bờ kè Mũi Né lộng gió\",\"Nghỉ dưỡng resort 4 sao mặt biển với hồ bơi vô cực ngắm bình minh\"]','[{\"day\":1,\"title\":\"TP.HCM - Cao Tốc Dầu Giây Phan Thiết - Lâu Đài Rượu Vang RD\",\"content\":\"Xe Limousine đón khách tại TP.HCM, di chuyển qua cao tốc êm ái đến Phan Thiết. Tham quan Lâu Đài Rượu Vang Sealinks, thử nếm các dòng vang Napa Valley hảo hạng. Nhận phòng resort 4 sao ven biển và tự do tắm biển.\"},{\"day\":2,\"title\":\"Tiểu Sa Mạc Bàu Trắng - Đồi Cát Bay Mũi Né - Làng Chài Xưa\",\"content\":\"Sáng sớm xe jeep đưa đoàn đón bình minh tại Bàu Trắng ngắm hồ sen thơ mộng giữa sa mạc cát trắng. Chiều ghé thăm bảo tàng Làng Chài Xưa tìm hiểu lịch sử nước mắm 300 năm. Tối thưởng thức bữa tối hải sản tôm mực nướng than hồng.\"},{\"day\":3,\"title\":\"Chợ Phan Thiết Mua Đặc Sản - Tiễn Về Lại TP.HCM\",\"content\":\"Dùng điểm tâm buffet tại resort, tự do dạo biển. Mua sắm nước mắm cá cơm, bánh rế, thanh long ruột đỏ. Đoàn khởi hành về lại TP.HCM, kết thúc chuyến đi tuyệt vời.\"}]','[\"Xe du lịch Limousine cao cấp suốt hành trình\",\"Khách sạn/Resort 4 sao sát biển Mũi Né (2 khách/phòng)\",\"Các bữa ăn tiêu chuẩn cao kèm tiệc hải sản tươi sống\",\"Vé tham quan Lâu Đài Rượu Vang (bao gồm thử rượu)\",\"Bảo hiểm du lịch 100.000.000 VNĐ/khách\"]','[\"Vé xe jeep và xe mô tô địa hình tại Bàu Trắng\",\"Chi phí cá nhân và đồ uống minibar\",\"Thuế VAT 8% nếu xuất hóa đơn tài chính\"]','2026-10-28 10:38:44'),
(42,1,2,'Đảo Điệp Sơn - Dốc Lết - Con Đường Đi Bộ Dưới Biển Độc Nhất Vô Nhị 3N2Đ','Chinh phục kỳ quan con đường cát uốn lượn giữa biển xanh Điệp Sơn, thỏa thích tắm biển Dốc Lết bãi cát trắng thoai thoải và thưởng thức chả cá, nem nướng Ninh Hòa trứ danh.',3390000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1544644181-1484b3fdfc62?w=1200&q=80',280,'2026-11-20','2026-11-22','ACTIVE',4.9,4190000.00,'Xe giường nằm VIP 34 phòng & Cano cao tốc vượt sóng',4,'MỚI RA MẮT','[\"Dạo bước trên con đường cát trắng tự nhiên giữa biển nối liền 3 hòn đảo\",\"Thưởng thức hải sản tươi ngon bắt ngay từ bè nuôi ngư dân Điệp Sơn\",\"Vui chơi tại bãi biển Dốc Lết sóng êm, nước trong như pha lê\",\"Thưởng thức nem nướng Đặng Văn Quyên đặc sản Ninh Hòa nức tiếng\"]','[{\"day\":1,\"title\":\"TP.HCM - Vịnh Vân Phong - Điệp Sơn Thủy Đạo\",\"content\":\"Đoàn khởi hành từ TP.HCM bằng xe giường nằm VIP. Sáng đến Vạn Giã, cano đưa quý khách ra đảo Điệp Sơn. Trải nghiệm cảm giác bước đi giữa biển cả mênh mông trên con đường cát độc nhất vô nhị.\"},{\"day\":2,\"title\":\"Bãi Biển Dốc Lết Thiên Đường Cát Trắng - Chợ Hải Sản\",\"content\":\"Khám phá bãi tắm Dốc Lết nước xanh biếc cát trắng mịn, tham gia moto nước và dù lượn. Chiều ghé thưởng thức nem nướng Ninh Hòa chuẩn vị gia truyền và tham quan làng nghề làm muối.\"},{\"day\":3,\"title\":\"Nha Trang Mua Sắm Yến Sào - Khởi Hành Về TP.HCM\",\"content\":\"Tham quan trung tâm Yến Sào Khánh Hòa, mua chả cá thu và đặc sản khô mực một nắng. Xe đưa đoàn về lại điểm đón ban đầu tại TP.HCM.\"}]','[\"Xe giường nằm VIP phòng đôi/đơn êm ái khứ hồi\",\"Cano cao tốc đưa đón khứ hồi ra đảo Điệp Sơn\",\"Khách sạn 4 sao tiêu chuẩn tại trung tâm vịnh Vân Phong/Dốc Lết\",\"Ăn uống theo chương trình gồm bữa hải sản Điệp Sơn\",\"Bảo hiểm du lịch trọn gói 100 triệu đồng\"]','[\"Các trò chơi thể thao biển có tính phí tại Dốc Lết\",\"Chi phí giặt ủi, chi tiêu cá nhân\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(43,1,3,'Quần Đảo Nam Du - Hòn Mấu - Hòn Dầu - Lặn San Hô & Tiệc BBQ Hải Sản 3N2Đ','Vi vu quần đảo hoang sơ tuyệt đẹp giữa vịnh Thái Lan: ngắm hàng dừa nghiêng bóng Hòn Mấu, check-in cây dừa huyền thoại Hòn Dầu và lặn ngắm rạn san hô lộng lẫy tại Hai Bờ Đập.',2950000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?w=1200&q=80',300,'2026-11-21','2026-11-23','ACTIVE',4.8,3650000.00,'Xe giường nằm Limousine & Tàu cao tốc Superdong',3,'BÁN CHẠY NHẤT','[\"Tàu du lịch đưa đoàn dạo quanh quần đảo 21 hòn đảo lớn nhỏ thơ mộng\",\"Tắm biển Bãi Chướng, Bãi Nam tại Hòn Mấu cát trắng mịn như nhung\",\"Thưởng thức tiệc BBQ hải sản: cá xanh xương nướng bẹ chuối, mực hấp gừng, sò tộ nướng mỡ hành\",\"Lặn ngắm rạn san hô tự nhiên rực rỡ và câu cá giữa biển khơi\"]','[{\"day\":1,\"title\":\"TP.HCM - Rạch Giá - Tàu Cao Tốc Superdong Ra Đảo Nam Du\",\"content\":\"Xe đưa đoàn đến Rạch Giá, lên tàu Superdong vượt sóng đến Nam Du. Nhận phòng resort bungalow view biển. Chiều tắm biển Bãi Cây Mến với hàng dừa trăm tuổi uốn lượn.\"},{\"day\":2,\"title\":\"Khám Phá Hòn Mấu - Lặn San Hô Hai Bờ Đập - Đại Tiệc BBQ\",\"content\":\"Lên tàu tham quan Hòn Mấu, tắm biển cát trắng Bãi Đá Đen. Tàu dừng tại Hai Bờ Đập để du khách lặn ngắm san hô và thử tài câu cá. Tối thưởng thức đại tiệc BBQ hải sản tươi sống và cháo nhum nóng hổi.\"},{\"day\":3,\"title\":\"Chinh Phục Hải Đăng Nam Du - Mua Đặc Sản Cá Khô - Về TP.HCM\",\"content\":\"Ngắm toàn cảnh quần đảo Nam Du từ ngọn hải đăng cao nhất đảo. Mua khô cá bớp, mực một nắng làm quà. Tàu đưa đoàn về lại Rạch Giá rồi xe tiễn về TP.HCM.\"}]','[\"Vé tàu cao tốc Superdong khứ hồi Rạch Giá - Nam Du\",\"Xe giường nằm VIP đón trả khách TP.HCM - Rạch Giá\",\"Bungalow/Nhà nghỉ cao cấp view biển tiện nghi\",\"Tàu du lịch tham quan các hòn đảo và dụng cụ lặn san hô\",\"Bảo hiểm du lịch nội địa 100.000.000 VNĐ\"]','[\"Thuê xe máy tham quan quanh đảo (150.000đ/ngày)\",\"Đồ uống ngoài thực đơn và chi phí cá nhân\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(44,2,2,'Cao Bằng - Thác Bản Giốc - Suối Lê-nin - Hang Pác Bó - Động Ngườm Ngao 3N2Đ','Chiêm ngưỡng thác Bản Giốc - một trong bốn thác nước xuyên biên giới đẹp nhất hành tinh, ngắm dòng suối Lê-nin trong xanh như ngọc bích và khám phá kiệt tác thạch nhũ Động Ngườm Ngao.',3190000.00,3,'Hà Nội','https://images.unsplash.com/photo-1528127269322-539801943592?w=1200&q=80',350,'2026-11-18','2026-11-20','ACTIVE',4.9,3890000.00,'Xe du lịch Universe 35 chỗ máy lạnh êm ái',4,'TOUR CAO CẤP','[\"Chiêm ngưỡng Thác Bản Giốc hùng vĩ tung bọt trắng xóa giữa non ngàn\",\"Du ngoạn Suối Lê-nin nước xanh màu ngọc bích và viếng Đền thờ Bác Hồ Pác Bó\",\"Thám hiểm Động Ngườm Ngao - kỳ quan thạch nhũ lung linh kỳ ảo\",\"Thưởng thức đặc sản vịt quay 7 vị, lạp xưởng hun khói, bánh cuốn Cao Bằng\"]','[{\"day\":1,\"title\":\"Hà Nội - Đèo Gió - Khu Di Tích Lịch Sử Pác Bó Suối Lê-nin\",\"content\":\"Đoàn khởi hành từ Hà Nội qua Thái Nguyên, Bắc Kạn đến Cao Bằng. Tham quan Hang Pác Bó nơi Bác Hồ từng sống và làm việc, ngắm suối Lê-nin và núi Các Mác linh thiêng. Nhận phòng khách sạn 4 sao tại trung tâm thành phố Cao Bằng.\"},{\"day\":2,\"title\":\"Thác Bản Giốc Hùng Vĩ - Chùa Phật Tích Trúc Lâm - Động Ngườm Ngao\",\"content\":\"Chiêm ngưỡng vẻ đẹp ngoạn mục của Thác Bản Giốc, trải nghiệm đi bè mảng sát chân thác đón làn nước mát lành. Chiều khám phá Động Ngườm Ngao dài hơn 2km thạch nhũ hình hoa sen, ruộng bậc thang. Tối thưởng thức vịt quay 7 vị Cao Bằng.\"},{\"day\":3,\"title\":\"Đèo Mã Phục 7 Tầng - Mua Đặc Sản Miến Dong Phia Đén - Về Hà Nội\",\"content\":\"Check-in Đèo Mã Phục uốn lượn quanh co giữa núi đá vôi. Mua sắm miến dong Phia Đén, hạt dẻ Trùng Khánh nức tiếng. Xe đưa đoàn về lại Hà Nội an toàn.\"}]','[\"Xe du lịch đời mới đưa đón suốt hành trình từ Hà Nội\",\"Khách sạn 4 sao trung tâm Cao Bằng đầy đủ tiện nghi\",\"Vé tham quan Thác Bản Giốc, Động Ngườm Ngao, Pác Bó\",\"Bè mảng ngắm thác Bản Giốc cự ly gần\",\"Bảo hiểm du lịch trọn gói 100.000.000 VNĐ\"]','[\"Đồ uống trong các bữa ăn, giặt ủi\",\"Tiền tip cho lái xe và hướng dẫn viên\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(45,2,1,'Mai Châu - Mộc Châu - Thung Khe - Thác Chiềng Khoa - Rừng Thông Bản Áng 2N1Đ','Hít hà bầu không khí trong lành của cao nguyên Mộc Châu, ngắm thung lũng mây trắng đèo Thung Khe, check-in thác Chiềng Khoa dải lụa xanh biếc và dạo bước đồi chè trái tim bát ngát.',1750000.00,2,'Hà Nội','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=1200&q=80',400,'2026-11-21','2026-11-22','ACTIVE',4.8,2250000.00,'Xe du lịch Hyundai Universe 29 chỗ đời mới',4,'HOT DEAL','[\"Dừng chân đèo Thung Khe (Đèo Đá Trắng) ngắm toàn cảnh thung lũng Mai Châu\",\"Thác Chiềng Khoa ngọc bích - tuyệt tác thiên nhiên hoang sơ giữa rừng già\",\"Dạo bước rừng thông Bản Áng và đồi chè trái tim Mộc Châu xanh ngát\",\"Thưởng thức bê chao Mộc Châu, cá suối nướng, cơm lam thịt lợn bản\"]','[{\"day\":1,\"title\":\"Hà Nội - Đèo Đá Trắng - Thung Lũng Mai Châu - Cao Nguyên Mộc Châu\",\"content\":\"Đón đoàn tại Nhà Hát Lớn Hà Nội. Dừng chân đèo Đá Trắng chụp ảnh mây ngàn. Trưa ăn đặc sản Mai Châu tại Bản Lác. Chiều lên Mộc Châu ngắm đồi chè trái tim xanh mướt và thưởng thức trà Ô Long thơm nồng. Nghỉ đêm tại resort Mộc Châu.\"},{\"day\":2,\"title\":\"Thác Chiềng Khoa 7 Tầng - Rừng Thông Bản Áng - Về Lại Hà Nội\",\"content\":\"Khám phá Thác Chiềng Khoa nước xanh ngọc bích kỳ ảo, tha hồ chụp ảnh check-in sống ảo. Ghé thăm vườn dâu tây và rừng thông Bản Áng. Đoàn mua sữa tươi Mộc Châu, chẩm chéo rồi lên xe về Hà Nội.\"}]','[\"Xe du lịch đời mới phục vụ suốt tuyến Hà Nội - Mộc Châu\",\"Phòng nghỉ khách sạn resort 4 sao tại Mộc Châu\",\"Các bữa ăn chính mang đậm phong vị Tây Bắc\",\"Vé tham quan đồi chè, thác Chiềng Khoa, rừng thông\",\"Bảo hiểm du lịch tối đa 100 triệu đồng/vụ\"]','[\"Vé tham quan Cầu Kính Bạch Long (nếu có nhu cầu)\",\"Chi phí cá nhân ngoài chương trình\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(46,2,3,'Hà Giang Mùa Tam Giác Mạch - Cột Cờ Lũng Cú - Hẻm Vực Tu Sản - Dinh Vua Mèo 4N3Đ','Cung đường huyền thoại chinh phục đệ nhất hùng quan Tây Bắc: ngắm bạt ngàn hoa tam giác mạch Đồng Văn, đi thuyền trên sông Nho Quế ngắm hẻm vực Tu Sản sâu nhất Đông Nam Á.',4650000.00,4,'Hà Nội','https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?w=1200&q=80',310,'2026-11-25','2026-11-28','ACTIVE',4.9,5450000.00,'Xe du lịch Limousine cao cấp chuyên tuyến đèo dốc',4,'BÁN CHẠY NHẤT','[\"Chạm tay vào lá cờ Tổ quốc linh thiêng tại Cột cờ Lũng Cú cực Bắc\",\"Đi thuyền trên dòng sông Nho Quế ngắm hẻm vực Tu Sản kỳ vĩ\",\"Chinh phục Đèo Mã Pí Lèng - một trong Tứ Đại Đỉnh Đèo hiểm trở nhất\",\"Thưởng thức thắng dền, phở tráng kìm, lẩu gà đen và rượu ngô men lá\"]','[{\"day\":1,\"title\":\"Hà Nội - Km0 Hà Giang - Cổng Trời Quản Bạ - Núi Đôi Cô Tiên\",\"content\":\"Khởi hành từ Hà Nội đến Hà Giang, check-in cột mốc Km0. Dừng chân tại Cổng Trời Quản Bạ ngắm Núi Đôi Cô Tiên tuyệt tác. Tối nghỉ tại thị trấn Yên Minh.\"},{\"day\":2,\"title\":\"Dốc Thẩm Mã - Nhà Của Pao - Dinh Vua Mèo - Phố Cổ Đồng Văn\",\"content\":\"Vượt dốc Thẩm Mã uốn lượn, tham quan Nhà Của Pao giữa thung lũng Sủng Là rực rỡ hoa tam giác mạch. Tham quan Dinh Thự Họ Vương (Vua Mèo). Tối dạo phố cổ Đồng Văn uống cà phê phố cổ.\"},{\"day\":3,\"title\":\"Cột Cờ Lũng Cú - Đèo Mã Pí Lèng - Du Thuyền Sông Nho Quế\",\"content\":\"Đoàn làm lễ chào cờ tại điểm cực Bắc Lũng Cú. Vượt đèo Mã Pí Lèng ngắm toàn cảnh thung lũng đá tai mèo. Đi thuyền máy lướt trên sông Nho Quế xanh biếc len lỏi giữa Hẻm Tu Sản.\"},{\"day\":4,\"title\":\"Chợ Phiên Mèo Vạc - Trở Về Thủ Đô Hà Nội\",\"content\":\"Tham quan chợ phiên vùng cao rực rỡ sắc màu thổ cẩm của đồng bào dân tộc H\'Mông, Dao. Khởi hành về Hà Nội, kết thúc chuyến phiêu lưu Đông Bắc.\"}]','[\"Xe Limousine chuyên tuyến đèo dốc đời mới\",\"Khách sạn 4 sao hoặc resort cao cấp tại Đồng Văn, Yên Minh\",\"Vé tham quan các điểm du lịch trong chương trình\",\"Vé thuyền du ngoạn Hẻm Tu Sản sông Nho Quế\",\"Bảo hiểm du lịch mức bồi thường 100.000.000 VNĐ\"]','[\"Tiền xe ôm/xe điện trung chuyển tại bến thuyền Nho Quế\",\"Chi phí cá nhân ngoài hành trình\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(47,3,1,'Hà Nội - Thủ Đô Ngàn Năm Văn Hiến - Lăng Bác - Văn Miếu - 36 Phố Phường 1 Ngày','Hành trình lắng đọng nét đẹp văn hóa ngàn năm Thăng Long: viếng Lăng Bác, chiêm bái Chùa Một Cột, tham quan Văn Miếu Quốc Tử Giám trường đại học đầu tiên và dạo xe điện phố cổ.',850000.00,1,'Hà Nội','https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=1200&q=80',500,'2026-11-15','2026-11-15','ACTIVE',4.8,1150000.00,'Xe du lịch đời mới & Xe điện dạo quanh phố cổ',4,'HOT DEAL','[\"Viếng Lăng Chủ tịch Hồ Chí Minh, Nhà Sàn và Ao Cá Bác Hồ\",\"Khám phá Văn Miếu - Quốc Tử Giám nơi lưu giữ 82 bia Tiến sĩ vinh danh hiền tài\",\"Dạo xe điện tham quan 36 phố phường cổ kính và Hồ Hoàn Kiếm\",\"Thưởng thức bún chả Hà Nội nướng than hoa và cà phê trứng nức tiếng\"]','[{\"day\":1,\"title\":\"Trọn Ngày Khám Phá Di Sản Ngàn Năm Thăng Long Hà Nội\",\"content\":\"Sáng đoàn viếng Lăng Bác, Quảng trường Ba Đình, Chùa Một Cột. Tiếp tục tham quan Văn Miếu Quốc Tử Giám. Dùng bữa trưa đặc sản bún chả Hà Nội. Chiều đi xe điện dạo phố cổ Hàng Bạc, Hàng Đào, viếng Đền Ngọc Sơn bên Hồ Gươm và thưởng thức cà phê trứng Giảng truyền thống.\"}]','[\"Xe du lịch máy lạnh đưa đón đón trả nội thành Hà Nội\",\"Vé tham quan tất cả các di tích có trong chương trình\",\"Vé xe điện dạo phố cổ Hà Nội 30 phút\",\"Bữa trưa đặc sản bún chả kèm nem rán truyền thống\",\"Bảo hiểm du lịch nội địa 100.000.000 VNĐ\"]','[\"Đồ uống gọi thêm trong bữa ăn\",\"Vé xem múa rối nước Thăng Long (nếu có nhu cầu)\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(48,3,2,'Quảng Ngãi - Đảo Lý Sơn Vương Quốc Tỏi - Cổng Tò Vò - Đỉnh Thới Lới 3N2Đ','Khám phá đảo ngọc tiền tiêu miền Trung với kiến tạo địa chất triệu năm từ núi lửa: chụp ảnh Cổng Tò Vò hoàng hôn, ngắm cánh đồng tỏi xanh bạt ngàn và lặn ngắm san hô Đảo Bé An Bình.',3550000.00,3,'Đà Nẵng','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=80',260,'2026-11-22','2026-11-24','ACTIVE',4.9,4250000.00,'Xe du lịch & Tàu siêu tốc An Vĩnh Express',4,'TOUR CAO CẤP','[\"Check-in Cổng Tò Vò trầm tích nham thạch núi lửa tuyệt đẹp lúc hoàng hôn\",\"Cano sang Đảo Bé tắm biển làn nước trong vắt như hồ bơi tự nhiên\",\"Ngắm toàn cảnh đảo Lý Sơn từ cột cờ Tổ quốc trên đỉnh miệng núi lửa Thới Lới\",\"Thưởng thức gỏi tỏi Lý Sơn, ốc cừ, chả cá đỏ củ và cua Huỳnh Đế\"]','[{\"day\":1,\"title\":\"Đà Nẵng - Cảng Sa Kỳ - Tàu Siêu Tốc Ra Đảo Lý Sơn - Cổng Tò Vò\",\"content\":\"Xe đón khách tại Đà Nẵng đưa đến cảng Sa Kỳ. Tàu siêu tốc đưa đoàn đến đảo Lý Sơn. Tham quan Chùa Hang, Cột Cờ Thới Lới. Chiều ngắm hoàng hôn rực rỡ tại Cổng Tò Vò vòm đá nham thạch.\"},{\"day\":2,\"title\":\"Cano Đi Đảo Bé An Bình - Lặn San Hô Bằng Thúng Chai\",\"content\":\"Cano đưa đoàn sang Đảo Bé (An Bình). Du khách trải nghiệm thuyền thúng lặn ngắm rạn san hô lộng lẫy và tắm biển bãi cát trắng mịn màng. Chiều thăm cánh đồng tỏi và tìm hiểu nghề trồng hành tỏi truyền thống.\"},{\"day\":3,\"title\":\"Chùa Đục - Thạch Cổng - Tàu Trở Lại Sa Kỳ - Về Đà Nẵng\",\"content\":\"Viếng Chùa Đục ngắm tượng Phật Quan Âm hướng biển. Mua tỏi cô đơn Lý Sơn chính hiệu làm quà. Tàu đưa đoàn về lại Sa Kỳ rồi xe đưa về Đà Nẵng.\"}]','[\"Vé tàu siêu tốc khứ hồi Sa Kỳ - Lý Sơn\",\"Xe du lịch đón tiễn khứ hồi từ Đà Nẵng\",\"Khách sạn 4 sao trung tâm đảo Lý Sơn\",\"Vé cano khứ hồi tham quan Đảo Bé\",\"Bảo hiểm du lịch 100.000.000 VNĐ\"]','[\"Chi phí thuê thuyền thúng lặn ngắm san hô Đảo Bé (120.000đ/người)\",\"Chi phí cá nhân ngoài thực đơn\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(49,3,3,'Quy Nhơn - Phú Yên: Kỳ Co - Eo Gió - Gành Đá Đĩa - Bãi Xép Hoa Vàng Trên Cỏ Xanh 4N3Đ','Liên tuyến di sản thiên nhiên duyên hải Nam Trung Bộ: lặn ngắm san hô Kỳ Co, dạo bước con đường ven biển Eo Gió, ngắm kiệt tác đá bazan Gành Đá Đĩa và bãi cỏ xanh ngát bên biển Bãi Xép.',4990000.00,4,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1544644181-1484b3fdfc62?w=1200&q=80',330,'2026-11-26','2026-11-29','ACTIVE',4.9,5990000.00,'Vé máy bay khứ hồi Vietnam Airlines & Xe 45 chỗ Universe',4,'BÁN CHẠY NHẤT','[\"Cano cao tốc đưa đoàn ra bãi tắm Kỳ Co làn nước trong hai màu ngoạn mục\",\"Check-in con đường đi bộ ven biển ngoạn mục tại Eo Gió\",\"Chiêm ngưỡng Gành Đá Đĩa - di tích danh thắng quốc gia độc nhất Đông Nam Á\",\"Thưởng thức mắt cá ngừ đại dương hầm thuốc bắc, bánh hỏi lòng heo Phú Yên\"]','[{\"day\":1,\"title\":\"TP.HCM - Sân Bay Phù Cát - Tháp Đôi Chăm Pa - Biển Quy Nhơn\",\"content\":\"Đáp chuyến bay Vietnam Airlines đến Quy Nhơn. Xe đưa đoàn tham quan Tháp Đôi Chăm Pa cổ kính thế kỷ 12, viếng tượng đài Nguyễn Tất Thành. Chiều tắm biển Hoàng Hậu (Bãi Trứng) và viếng mộ nhà thơ Hàn Mặc Tử tại Ghềnh Ráng.\"},{\"day\":2,\"title\":\"Cano Kỳ Co Thiên Đường Biển - Lặn San Hô Bãi Dứa - Con Đường Eo Gió\",\"content\":\"Cano vượt sóng ra vịnh Kỳ Co, tắm biển cát trắng nước trong vắt. Lặn ngắm san hô tại Bãi Dứa. Dùng bữa trưa đại tiệc hải sản 8 món. Chiều check-in Eo Gió đón gió biển lồng lộng.\"},{\"day\":3,\"title\":\"Quy Nhơn - Phú Yên - Gành Đá Đĩa - Nhà Thờ Mằng Lăng - Bãi Xép\",\"content\":\"Di chuyển đến Phú Yên. Tham quan Nhà thờ Mằng Lăng nơi lưu giữ cuốn sách in chữ quốc ngữ đầu tiên. Khám phá Gành Đá Đĩa với các cột đá lăng trụ xếp chồng tự nhiên. Chiều ghé Bãi Xép - bối cảnh phim \'Tôi thấy hoa vàng trên cỏ xanh\'.\"},{\"day\":4,\"title\":\"Mũi Điện Đón Ánh Bình Minh - Tháp Nghinh Phong - Tiễn Sân Bay\",\"content\":\"Đón bình minh tại Mũi Điện (Hải Đăng Đại Lãnh). Check-in Tháp Nghinh Phong biểu tượng kiến trúc mới của Tuy Hòa. Xe đưa đoàn ra sân bay Tuy Hòa bay về TP.HCM.\"}]','[\"Vé máy bay khứ hồi Vietnam Airlines gồm hành lý ký gửi 20kg\",\"Khách sạn 4 sao chuẩn quốc tế trung tâm bờ biển Quy Nhơn và Tuy Hòa\",\"Xe du lịch đời mới Universe máy lạnh suốt hành trình\",\"Cano cao tốc và tiệc hải sản 8 món tại Kỳ Co\",\"Bảo hiểm du lịch trọn gói 100.000.000 VNĐ\"]','[\"Chi phí phát sinh cá nhân, giặt ủi\",\"Trò chơi thể thao nước tại bãi biển Kỳ Co\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(50,4,1,'Đà Lạt - Tuyệt Tình Cốc - Làng Cù Lần - Đồi Cỏ Hồng & Thung Lũng Tình Yêu 3N2Đ','Thả hồn giữa không gian thơ mộng xứ sương mù: ngắm hồ nước xanh ngọc Tuyệt Tình Cốc, lạc bước Làng Cù Lần mộc mạc bên suối, ngắm đồi cỏ hồng rực rỡ và tận hưởng đại tiệc BBQ giữa rừng thông.',2950000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?w=1200&q=80',380,'2026-11-18','2026-11-20','ACTIVE',4.8,3650000.00,'Xe giường nằm Limousine 34 phòng cao cấp',4,'HOT DEAL','[\"Check-in Tuyệt Tình Cốc mỏ đá cổ với hồ nước trong xanh màu ngọc bích\",\"Trải nghiệm xe jeep vượt suối khám phá không gian thanh bình Làng Cù Lần\",\"Đón bình minh săn sương sớm trên đồi cỏ hồng mộng mơ bên bờ hồ Dankia\",\"Thưởng thức tiệc lẩu gà lá é, bánh ướt lòng gà và buffet rau đà lạt không giới hạn\"]','[{\"day\":1,\"title\":\"TP.HCM - Cao Tốc Dầu Giây Liên Khương - Đà Lạt Ngàn Hoa\",\"content\":\"Xe Limousine đón khách tại TP.HCM đi Đà Lạt. Dừng chân ngắm Thác Prenn hùng vĩ. Đến Đà Lạt nhận phòng khách sạn 4 sao. Chiều dạo quanh Hồ Xuân Hương thơ mộng, tối tự do thưởng thức sữa đậu nành nóng và bánh tráng nướng chợ đêm.\"},{\"day\":2,\"title\":\"Tuyệt Tình Cốc Huyền Ảo - Làng Cù Lần Vượt Suối - Thung Lũng Tình Yêu\",\"content\":\"Xe jeep đưa đoàn vào Tuyệt Tình Cốc chụp ảnh hồ ngọc bích. Ghé Làng Cù Lần xem biểu diễn cồng chiêng Tây Nguyên. Chiều dạo bước trong hoa viên Thung Lũng Tình Yêu. Tối thưởng thức tiệc lẩu gà lá é Tao Ngộ.\"},{\"day\":3,\"title\":\"Đồi Cỏ Hồng Săn Sương - Vườn Dâu Tây Công Nghệ Cao - Về Lại TP.HCM\",\"content\":\"Sáng sớm ngắm đồi cỏ hồng đọng sương mai lung linh. Tham quan vườn dâu tây thủy canh tự tay hái những trái dâu chín mọng. Mua đặc sản mứt dâu, atiso rồi khởi hành về TP.HCM.\"}]','[\"Xe giường nằm VIP Limousine khứ hồi TP.HCM - Đà Lạt\",\"Khách sạn 4 sao trung tâm gần chợ Đà Lạt\",\"Xe jeep chuyên dụng tham quan Làng Cù Lần & Tuyệt Tình Cốc\",\"Các bữa ăn chính tiêu chuẩn cao kèm tiệc lẩu rau Leguda\",\"Bảo hiểm du lịch 100.000.000 VNĐ\"]','[\"Vé hái dâu tây mang về tính theo kg\",\"Chi phí cá nhân ngoài hành trình\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(51,4,2,'Gia Lai - Đắk Lắk - Chư Đăng Ya - Biển Hồ Tơ Nưng - Cưỡi Voi Buôn Đôn 4N3Đ','Hành trình đại ngàn Tây Nguyên hùng vĩ: ngắm hoa dã quỳ vàng rực trên miệng núi lửa Chư Đăng Ya, chiêm ngưỡng Biển Hồ Tơ Nưng mắt ngọc Gia Lai và giao lưu văn hóa cồng chiêng tại Buôn Đôn.',3990000.00,4,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1528127269322-539801943592?w=1200&q=80',270,'2026-11-20','2026-11-23','ACTIVE',4.8,4790000.00,'Vé máy bay Vietnam Airlines & Xe Universe 35 chỗ đời mới',4,'TOUR CAO CẤP','[\"Check-in miệng núi lửa Chư Đăng Ya triệu năm phủ kín sắc vàng hoa dã quỳ\",\"Chiêm ngưỡng Biển Hồ Tơ Nưng - \'Đôi mắt Pleiku Biển Hồ đầy\' trong xanh phẳng lặng\",\"Tham quan Buôn Đôn, cầu treo bằng tre bắc qua dòng sông Sêrêpôk cuồn cuộn\",\"Thưởng thức gà sa lửa cơm lam, gỏi lá rừng Tây Nguyên 40 loại lá và cà phê nguyên chất\"]','[{\"day\":1,\"title\":\"TP.HCM - Pleiku - Núi Lửa Chư Đăng Ya - Hàng Thông Trăm Tuổi\",\"content\":\"Bay đến Pleiku. Tham quan miệng núi lửa Chư Đăng Ya đất đỏ bazan màu mỡ. Dạo bước dưới hàng thông trăm tuổi và cánh đồng chè Biển Hồ xanh ngút ngàn. Nhận phòng khách sạn 4 sao Pleiku.\"},{\"day\":2,\"title\":\"Biển Hồ Tơ Nưng - Thủy Điện Yaly - Di Chuyển Đến Buôn Ma Thuột\",\"content\":\"Ngắm bình minh Biển Hồ Tơ Nưng. Thăm công trình Thủy điện Yaly hùng vĩ trên sông Sesan. Khởi hành về Buôn Ma Thuột thủ phủ cà phê. Tối dạo phố đi bộ Buôn Ma Thuột.\"},{\"day\":3,\"title\":\"Buôn Đôn Cầu Treo Sêrêpôk - Thác Dray Nur Tuyệt Tác Đại Ngàn\",\"content\":\"Khám phá Buôn Đôn, tìm hiểu phong tục săn bắt và thuần dưỡng voi rừng của Vua voi Khun Yu Nốp. Đi trên cầu treo lắc lư bắc qua sông Sêrêpôk. Chiều chiêm ngưỡng Thác Dray Nur dòng nước trắng xóa cuộn trào.\"},{\"day\":4,\"title\":\"Bảo Tàng Thế Giới Cà Phê - Làng Cà Phê Trung Nguyên - Bay Về TP.HCM\",\"content\":\"Check-in Bảo tàng Thế giới Cà phê với kiến trúc nhà dài cách điệu ấn tượng. Thưởng thức ly cà phê chồn thơm nồng. Xe đưa đoàn ra sân bay Buôn Ma Thuột bay về TP.HCM.\"}]','[\"Vé máy bay khứ hồi Vietnam Airlines / Bamboo Airways\",\"Khách sạn 4 sao chuẩn quốc tế tại Pleiku và Buôn Ma Thuột\",\"Xe du lịch đời mới phục vụ suốt tuyến\",\"Vé tham quan tất cả các điểm theo chương trình\",\"Bảo hiểm du lịch tối đa 100.000.000 VNĐ\"]','[\"Phí cưỡi voi (ủng hộ mô hình du lịch thân thiện với voi)\",\"Đồ uống ngoài thực đơn và giặt ủi\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(52,4,3,'Kon Tum - Nàng Thơ Măng Đen - Thác Pa Sỹ - Hồ Đăk Ke - Cầu Treo Kon Klor 3N2Đ','Lạc bước vào thiên đường khí hậu ôn đới Măng Đen - nơi được ví như Đà Lạt thứ hai giữa ngút ngàn rừng thông nguyên sinh, viếng Tượng Đức Mẹ Măng Đen linh thiêng và ngắm Thác Pa Sỹ hoang sơ.',3450000.00,3,'Đà Nẵng','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=1200&q=80',250,'2026-11-21','2026-11-23','ACTIVE',4.9,4150000.00,'Xe du lịch Limousine 19 chỗ cao cấp',4,'BÁN CHẠY NHẤT','[\"Tận hưởng khí hậu se lạnh mát mẻ quanh năm 18-22 độ C của cao nguyên Măng Đen\",\"Chiêm bái Tượng Đức Mẹ Măng Đen linh thiêng giữa rừng thông cổ thụ\",\"Khám phá Thác Pa Sỹ bọt tung trắng xóa và dạo thuyền đạp vịt Hồ Đăk Ke\",\"Thưởng thức gà nướng cơm lam cô Sinh, lẩu xuyên tiêu cay nồng đặc sắc\"]','[{\"day\":1,\"title\":\"Đà Nẵng - Đèo Lò Xo - Kon Tum - Thị Trấn Sinh Thái Măng Đen\",\"content\":\"Xe Limousine đón khách tại Đà Nẵng, vượt đèo Lò Xo hùng vĩ đến Kon Tum. Viếng Nhà thờ Gỗ Kon Tum hơn 100 năm tuổi kết hợp kiến trúc Roman và nhà sàn Ba Na. Lên Măng Đen nhận phòng resort giữa rừng thông.\"},{\"day\":2,\"title\":\"Thác Pa Sỹ - Hồ Đăk Ke Thơ Mộng - Vườn Cam & Khu Nông Nghiệp Công Nghệ Cao\",\"content\":\"Tham quan Thác Pa Sỹ cao 45m tuyệt đẹp, dạo bước quanh Hồ Đăk Ke ngắm hoa anh đào nở sớm. Ghé thăm các nông trại hữu cơ Măng Đen tự tay hái dâu tây, cà chua bi. Tối quây quần thưởng thức lẩu cá tầm Măng Đen.\"},{\"day\":3,\"title\":\"Tượng Đức Mẹ Sầu Bi Măng Đen - Cầu Treo Kon Klor - Về Đà Nẵng\",\"content\":\"Viếng Trung tâm hành hương Đức Mẹ Măng Đen. Xuống núi dừng chân tại Cầu treo Kon Klor bằng sắt lớn nhất Tây Nguyên bắc qua sông Đăk Bla. Xe đưa đoàn về lại Đà Nẵng.\"}]','[\"Xe du lịch Limousine 19 chỗ đời mới êm ái\",\"Resort 4 sao sinh thái giữa rừng thông Măng Đen\",\"Các bữa ăn đặc sản đậm chất núi rừng Măng Đen\",\"Vé vào cổng tất cả danh lam thắng cảnh\",\"Bảo hiểm du lịch 100.000.000 VNĐ\"]','[\"Chi phí hái hoa quả mang về tại các nông trại\",\"Chi phí cá nhân và đồ uống phát sinh\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(53,5,1,'Bạc Liêu - Sóc Trăng - Cà Mau: Nhà Công Tử Bạc Liêu - Chùa Dơi - Cột Mốc Mũi Cà Mau 3N2Đ','Hành trình phương Nam về với Đất Mũi thiêng liêng: viếng Chùa Dơi kiến trúc Angkor Khmer độc đáo, nghe giai thoại Công Tử Bạc Liêu đốt tiền nấu trứng và chạm tay Cột Mốc Tọa Độ Quốc Gia GPS 0001.',3290000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1544644181-1484b3fdfc62?w=1200&q=80',360,'2026-11-20','2026-11-22','ACTIVE',4.9,3990000.00,'Xe du lịch Universe 45 chỗ đời mới máy lạnh êm',4,'TOUR CAO CẤP','[\"Chạm tay vào Cột Mốc Tọa Độ Quốc Gia GPS 0001 và biểu tượng Mũi Tàu Cà Mau\",\"Đi cano xuyên qua Rừng Đước nguyên sinh Vườn Quốc Gia Mũi Cà Mau\",\"Tham quan Dinh Thự Công Tử Bạc Liêu xa hoa bậc nhất Nam Kỳ Lục Tỉnh\",\"Thưởng thức cua biển Cà Mau nướng mọi, lẩu cá bớp bắp chuối, ba khía Rạch Gốc\"]','[{\"day\":1,\"title\":\"TP.HCM - Sóc Trăng Viếng Chùa Dơi Chùa Chén Kiểu - Bạc Liêu\",\"content\":\"Đoàn khởi hành từ TP.HCM đi Sóc Trăng. Tham quan Chùa Dơi Mahatup nơi hàng vạn con dơi ngựa sinh sống, Chùa Chén Kiểu trang trí bằng chén dĩa sành sứ tinh xảo. Chiều tham quan Dinh thự Công Tử Bạc Liêu và Cánh đồng Điện Gió Bạc Liêu.\"},{\"day\":2,\"title\":\"Bạc Liêu - Cà Mau - Cano Xuyên Rừng Đước - Chinh Phục Đất Mũi\",\"content\":\"Xe đưa đoàn về Năm Căn, lên cano lướt sóng xuyên qua rừng đước Vườn Quốc Gia Mũi Cà Mau. Check-in mốc tọa độ GPS 0001 và Cột cờ Hà Nội tại Mũi Cà Mau. Dùng bữa trưa cua biển Năm Căn tại nhà hàng nổi sinh thái.\"},{\"day\":3,\"title\":\"Thành Phố Cà Mau - Nhà Thờ Tắc Sậy Cha Diệp - Trở Về TP.HCM\",\"content\":\"Viếng Nhà thờ Tắc Sậy cầu bình an nơi an nghỉ của linh mục Trương Bửu Diệp. Ghé trạm dừng chân mua tôm khô Rạch Gốc, mắm ba khía, bánh phồng tôm Năm Căn. Khởi hành về lại TP.HCM.\"}]','[\"Xe du lịch máy lạnh đưa đón khứ hồi suốt tuyến\",\"Khách sạn 4 sao Mường Thanh Luxury Cà Mau\",\"Cano cao tốc đưa đón xuyên rừng đước Đất Mũi\",\"Các bữa ăn đậm đà đặc sản vùng cực Nam (bao gồm bữa tiệc cua Cà Mau)\",\"Bảo hiểm du lịch trọn gói 100.000.000 VNĐ\"]','[\"Chi phí cá nhân ngoài thực đơn\",\"Thuê xe điện tham quan tại công viên Đất Mũi (nếu có)\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(54,5,2,'Tiền Giang - Bến Tre - Trà Vinh: Du Khảo Miệt Vườn - Chùa Hang - Ao Bà Om 2N1Đ','Trải nghiệm văn hóa đa sắc sông nước Cửu Long: chèo xuồng ba lá len lỏi rạch dừa nước Bến Tre, thưởng thức kẹo dừa tại lò, chiêm ngưỡng Chùa Hang cổ kính và thắng cảnh linh thiêng Ao Bà Om xứ Trà Vinh.',1890000.00,2,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=1200&q=80',400,'2026-11-22','2026-11-23','ACTIVE',4.8,2390000.00,'Xe du lịch Universe 29 chỗ & Thuyền gỗ chèo tay',4,'HOT DEAL','[\"Chèo xuồng ba lá truyền thống dưới rợp bóng dừa nước xanh mát Bến Tre\",\"Ghé lò kẹo dừa truyền thống thưởng thức kẹo nóng mới ra lò ngọt thơm\",\"Chiêm ngưỡng Chùa Âng - ngôi chùa Khmer cổ nhất Trà Vinh hơn 1.000 năm tuổi\",\"Thưởng thức cá tai tượng chiên xù cuốn bánh tráng, bún nước lèo Trà Vinh\"]','[{\"day\":1,\"title\":\"TP.HCM - Mỹ Tho - Bến Tre Xứ Dừa - Thuyền Rồng Sông Tiền\",\"content\":\"Đoàn khởi hành đi Tiền Giang, lên thuyền du ngoạn 4 cồn Long - Lân - Quy - Phụng. Nghe đờn ca tài tử Nam Bộ, chèo xuồng ba lá trong rạch nhỏ rợp bóng dừa nước. Dùng bữa trưa cá tai tượng chiên xù. Chiều sang Trà Vinh nhận phòng khách sạn 4 sao.\"},{\"day\":2,\"title\":\"Khám Phá Di Sản Văn Hóa Khmer Trà Vinh: Ao Bà Om - Chùa Hang - Về TP.HCM\",\"content\":\"Dạo bước dưới hàng cây sao trăm tuổi quanh thắng cảnh Ao Bà Om, viếng Chùa Âng và Bảo tàng Văn hóa Khmer. Tham quan Chùa Hang với xưởng điêu khắc gỗ nghệ thuật tinh xảo. Đoàn dùng bún nước lèo Trà Vinh trứ danh rồi khởi hành về TP.HCM.\"}]','[\"Xe du lịch đời mới phục vụ suốt hành trình\",\"Khách sạn 4 sao tiêu chuẩn tại Trà Vinh\",\"Thuyền máy và xuồng chèo ba lá trên sông Tiền\",\"Ăn uống theo chương trình gồm các món đặc sản miền Tây\",\"Bảo hiểm du lịch tối đa 100 triệu đồng\"]','[\"Chi tiêu cá nhân, mua quà đặc sản\",\"Tiền tip tài xế và hướng dẫn viên\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(55,5,3,'An Giang - Châu Đốc: Miếu Bà Chúa Xứ Núi Sam - Rừng Tràm Trà Sư Mùa Nước Nổi 2N1Đ','Hành trình tâm linh và khám phá sinh thái độc đáo vùng Thất Sơn Bảy Núi: viếng Miếu Bà Chúa Xứ linh ứng, đi tắc ráng lướt trên thảm bèo cám xanh mướt Rừng Tràm Trà Sư ngắm đàn chim trời bay lượn.',1950000.00,2,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?w=1200&q=80',380,'2026-11-28','2026-11-29','ACTIVE',4.9,2450000.00,'Xe du lịch Limousine VIP & Tắc ráng len lỏi rừng tràm',4,'BÁN CHẠY NHẤT','[\"Chiêm bái Miếu Bà Chúa Xứ Núi Sam nổi tiếng linh thiêng thu hút hàng triệu tín đồ\",\"Đi tắc ráng và xuồng chèo len lỏi qua thảm bèo xanh mướt Rừng Tràm Trà Sư\",\"Check-in cầu tre vạn bước xuyên rừng tràm dài nhất Việt Nam\",\"Thưởng thức cá lóc nướng trui cuốn lá sen non, lẩu mắm bông điên điển\"]','[{\"day\":1,\"title\":\"TP.HCM - Đồng Bằng Sông Cửu Long - Châu Đốc - Viếng Miếu Bà Núi Sam\",\"content\":\"Xe đưa đoàn khởi hành đến Châu Đốc An Giang. Chiều viếng Miếu Bà Chúa Xứ Núi Sam cầu bình an và may mắn, viếng Lăng Thoại Ngọc Hầu và Chùa Tây An cổ kính. Tối thưởng thức đặc sản lẩu mắm Châu Đốc nức tiếng.\"},{\"day\":2,\"title\":\"KDL Sinh Thái Rừng Tràm Trà Sư - Cầu Tre Xuyên Rừng - Về Lại TP.HCM\",\"content\":\"Đoàn tham quan Rừng Tràm Trà Sư, ngồi thuyền tắc ráng lướt êm ái trên mặt thảm bèo xanh ngát ngắm các loài chim nước quý hiếm. Lên đài quan sát ngắm toàn cảnh rừng tràm. Mua đặc sản mắm cá linh, đường thốt nốt rồi khởi hành về TP.HCM.\"}]','[\"Xe Limousine máy lạnh đón tiễn khứ hồi từ TP.HCM\",\"Khách sạn 4 sao sang trọng view Núi Sam Châu Đốc\",\"Vé vào cổng và trọn gói vé thuyền tắc ráng + xuồng chèo Trà Sư\",\"Các bữa ăn chính đặc sản miền Tây sông nước\",\"Bảo hiểm du lịch 100.000.000 VNĐ\"]','[\"Chi phí dâng lễ và cúng viếng cá nhân\",\"Chi phí đồ uống cá nhân ngoài chương trình\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(56,6,1,'Du Thuyền 5 Sao Capella Cruises Vịnh Lan Hạ - Bể Bơi Vô Cực & Cầu Trượt Nước Độc Đáo 2N1Đ','Nghỉ dưỡng thượng lưu trên siêu du thuyền Capella kết hợp kiến trúc Đông Dương hoài cổ và du thuyền hiện đại: trải nghiệm cầu trượt nước rơi tự do giữa biển, bể bơi vô cực nước biển và chèo kayak qua Hang Sáng Tối.',4690000.00,2,'Hà Nội','https://images.unsplash.com/photo-1528127269322-539801943592?w=1200&q=80',260,'2026-11-20','2026-11-21','ACTIVE',4.9,5690000.00,'Xe Limousine Dcar cao cấp & Siêu du thuyền 5 sao Capella',5,'TOUR CAO CẤP','[\"Siêu du thuyền 5 sao 6 tầng thiết kế Indochine lộng lẫy và ban công riêng biệt\",\"Bể bơi ốc đảo vô cực hướng biển duy nhất tại Vịnh Lan Hạ và cầu trượt biển cực đã\",\"Chèo thuyền kayak hoặc ngồi thuyền nan khám phá kỳ quan Hang Sáng Tối\",\"Thưởng thức tiệc trà chiều hoàng hôn và tiệc tối hải sản tôm hùm thượng hạng\"]','[{\"day\":1,\"title\":\"Hà Nội - Cảng Tuần Châu - Lên Siêu Du Thuyền Capella - Hang Sáng Tối\",\"content\":\"Xe Limousine đón khách tại Hà Nội, đưa đến Cảng Tuần Châu. Đội ngũ thủy thủ chào đón bằng đồ uống Welcome Drink. Thưởng thức buffet trưa thượng hạng khi du thuyền lướt êm đềm qua Vịnh Lan Hạ. Chiều chèo thuyền Kayak Hang Sáng Tối, tắm biển và trượt cầu trượt nước biển. Tối tiệc tối Fine Dining tôm hùm rượu vang.\"},{\"day\":2,\"title\":\"Thái Cực Quyền Đón Bình Minh - Vịnh Ao Ếch - Cảng Tuần Châu - Hà Nội\",\"content\":\"Tập Tai-chi đón ánh bình minh kỳ ảo trên Sundeck tầng 6. Du thuyền đưa khách đến khu bảo tồn Ao Ếch chèo SUP tự do. Dùng bữa brunch buffet tự chọn phong phú. Tàu cập cảng Tuần Châu, xe Limousine đưa đoàn về Hà Nội.\"}]','[\"Xe Limousine đưa đón khứ hồi cao tốc Hà Nội - Hạ Long\",\"01 đêm phòng nghỉ Suite hạng sang ban công riêng bồn tắm ngâm view vịnh\",\"Trọn gói 04 bữa ăn thượng hạng theo chương trình (bao gồm tiệc tối tôm hùm)\",\"Sử dụng không giới hạn hồ bơi vô cực, bể sục Jacuzzi và cầu trượt nước\",\"Vé tham quan, bảo hiểm du lịch trọn gói trên du thuyền\"]','[\"Dịch vụ Spa & Massage trị liệu\",\"Đồ uống gọi thêm trong bữa ăn\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(57,6,2,'Du Thuyền Heritage Bình Chuẩn Vịnh Lan Hạ Cát Bà - Kiệt Tác Di Sản Đông Dương 2N1Đ','Hành trình ngược dòng thời gian về thời kỳ hoàng kim của vua tàu thủy Bạch Thái Bưởi: chiêm ngưỡng bộ sưu tập hội họa tranh Phạm Lực, phòng trưng bày cổ vật quý hiếm và ẩm thực Bắc Bộ hoàng gia.',4950000.00,2,'Hà Nội','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=80',240,'2026-11-23','2026-11-24','ACTIVE',4.9,5950000.00,'Xe Limousine sang trọng & Du thuyền nghệ thuật Heritage',5,'TOUR CAO CẤP','[\"Du thuyền văn hóa di sản đầu tiên tại Việt Nam lấy cảm hứng từ cụ Bạch Thái Bưởi\",\"Phòng nghỉ đẳng cấp với 100% ban công ngắm toàn cảnh Vịnh Lan Hạ\",\"Bể bơi 4 mùa nước nóng thông minh trên boong tàu ngắm cảnh núi non trùng điệp\",\"Thực đơn Le Tonkin phong vị hoàng gia Bắc Bộ kết hợp ẩm thực Pháp tinh tế\"]','[{\"day\":1,\"title\":\"Hà Nội - Cảng Phà Gót Cát Hải - Thưởng Lãm Di Sản Heritage Bình Chuẩn\",\"content\":\"Xe đưa khách đến Cát Hải, bước lên du thuyền Heritage trong tiếng chuông đồng chào mừng. Thưởng thức bữa trưa tại nhà hàng L\'Indochine. Chiều thăm Làng Chài Trà Báu, chèo kayak trên làn nước xanh ngọc. Tối thưởng lãm triển lãm tranh nghệ thuật và tiệc tối hoàng gia.\"},{\"day\":2,\"title\":\"Bình Minh Trên Vịnh - Hang Sáng Tối - Thưởng Thức Bữa Sáng Buffet - Hà Nội\",\"content\":\"Ngắm bình minh và thưởng thức trà thảo mộc. Đi thuyền nan do người dân địa phương chèo đưa qua cổng vòm Hang Tối Hang Sáng. Trở lại tàu làm thủ tục trả phòng, dùng bữa trưa sớm trước khi cập bến về Hà Nội.\"}]','[\"Xe đưa đón Limousine cao cấp hai chiều từ Hà Nội\",\"Phòng nghỉ Delta / Ocean Suite sang trọng đầy đủ tiện nghi tiêu chuẩn 5 sao\",\"Các bữa ăn thượng hạng theo phong cách ẩm thực cung đình\",\"Bể bơi bốn mùa, tiện ích phòng tập gym, thư viện sách di sản\",\"Vé tham quan, chèo kayak, bảo hiểm du lịch 100.000.000 VNĐ\"]','[\"Chi phí dịch vụ Spa Sông Hồng trên tàu\",\"Đồ uống có cồn ngoài chương trình tiệc trà chiều\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(58,6,3,'Du Thuyền Indochina Sails Hạ Long - Phong Cách Gỗ Quý Cổ Điển Hoàng Gia 3N2Đ','Trải nghiệm nghỉ đêm trên vịnh kỳ quan với du thuyền buồm gỗ cổ điển chạm khắc tinh xảo: len lỏi qua hàng nghìn đảo đá vôi, thám hiểm Hang Sửng Sốt, leo đỉnh đảo Ti Tốp ngắm toàn cảnh vịnh và câu mực đêm cùng thuyền viên.',6850000.00,3,'Hà Nội','https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=1200&q=80',250,'2026-11-25','2026-11-27','ACTIVE',4.8,8250000.00,'Xe Limousine 9 chỗ Dcar & Du thuyền gỗ buồm cao cấp',5,'BÁN CHẠY NHẤT','[\"Du thuyền bằng gỗ gụ cổ điển mang đậm nét kiến trúc Đông Dương thế kỷ 19\",\"Chinh phục đỉnh Ti Tốp ngắm toàn cảnh 360 độ vịnh Hạ Long tráng lệ\",\"Khám phá Hang Sửng Sốt - hang động karst rộng lớn và lộng lẫy nhất vịnh\",\"Trải nghiệm lớp học cuốn nem truyền thống và câu mực đêm dưới ánh trăng\"]','[{\"day\":1,\"title\":\"Hà Nội - Tuần Châu - Lên Tàu Indochina Sails - Hang Sửng Sốt\",\"content\":\"Xe đưa khách ra bến Tuần Châu, lên du thuyền gỗ Indochina Sails. Dùng bữa trưa buffet hải sản khi tàu lướt qua Hòn Trống Mái. Chiều leo bậc đá khám phá vẻ đẹp kỳ vĩ của Hang Sửng Sốt. Tối ngắm trăng trên boong gỗ và câu mực đêm.\"},{\"day\":2,\"title\":\"Hồ Động Tiên - Làng Chài Cửa Vạn - Đảo Ti Tốp Tắm Biển\",\"content\":\"Đoàn chuyển sang thuyền ngày tham quan Làng chài Cửa Vạn - một trong những ngôi làng nổi cổ kính nhất thế giới. Chèo kayak tại Hồ Động Tiên. Chiều tắm biển bãi cát Ti Tốp và leo 400 bậc đá ngắm hoàng hôn đỏ rực.\"},{\"day\":3,\"title\":\"Tập Dưỡng Sinh - Lớp Nấu Ăn Tỉa Hoa - Tuần Châu - Về Hà Nội\",\"content\":\"Đón bình minh trong không gian tĩnh mịch của vịnh. Tham gia lớp học nấu ăn nghệ thuật tỉa củ quả của bếp trưởng. Du thuyền trở về cảng Tuần Châu, xe đưa đoàn về Hà Nội an toàn.\"}]','[\"Xe đưa đón Limousine Dcar khứ hồi Hà Nội - Hạ Long\",\"02 đêm phòng cabin gỗ sang trọng view cửa sổ toàn cảnh vịnh\",\"Toàn bộ 06 bữa ăn chính thịnh soạn theo chương trình 3 ngày\",\"Vé tham quan, chèo kayak, lớp dạy nấu ăn, cần câu mực đêm\",\"Bảo hiểm du lịch trọn gói theo quy định hàng hải\"]','[\"Đồ uống trong thực đơn bar & minibar\",\"Chi phí cá nhân ngoài hành trình\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(59,7,2,'Trekking Chinh Phục Đỉnh Pu Si Lung 3083m - Nóc Nhà Biên Cương Lai Châu 4N3Đ','Thử thách giới hạn bản thân trên cung đường trekking hoang dã bậc nhất Việt Nam: xuyên qua những cánh rừng đỗ quyên cổ thụ bạt ngàn, chạm tay cột mốc biên giới 42 thiêng liêng và đứng trên đỉnh Pu Si Lung ngắm đại ngàn Tây Bắc.',5950000.00,4,'Hà Nội','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=1200&q=80',220,'2026-11-26','2026-11-29','ACTIVE',4.9,7200000.00,'Xe giường nằm VIP phòng đơn & Porter bản địa dẫn đường',3,'TOUR CAO CẤP','[\"Chinh phục đỉnh núi cao thứ 2 Việt Nam (3.083m) đầy kiêu hãnh và thách thức\",\"Chạm tay vào Cột Mốc Biên Giới 42 phân định ranh giới Việt - Trung trên đỉnh đèo\",\"Chiêm ngưỡng rừng hoa đỗ quyên nở rộ và thảm rêu cổ thụ ma mị như truyện cổ tích\",\"Đội ngũ Porter người La Hủ chu đáo gùi đồ ăn, dựng lán trại và đốt lửa sưởi ấm\"]','[{\"day\":1,\"title\":\"Hà Nội - Thành Phố Lai Châu - Đồn Biên Phòng Pa Vệ Sử\",\"content\":\"Đoàn đi xe giường nằm VIP từ Hà Nội lên Lai Châu. Xe trung chuyển đưa đến Đồn Biên phòng Pa Vệ Sử làm thủ tục xuất trình giấy phép vào khu vực biên giới. Nghỉ ngơi tại trạm biên phòng chuẩn bị thể lực.\"},{\"day\":2,\"title\":\"Bắt Đầu Trekking - Rừng Thảo Quả - Cột Mốc 42 Biên Giới - Lán Trại 2600m\",\"content\":\"Đoàn bắt đầu chặng trekking vượt suối, xuyên rừng trúc và rừng thảo quả xanh ngút ngàn. Chinh phục Cột mốc 42 thiêng liêng ở độ cao 2.800m. Di chuyển về hạ trại tại lán gỗ 2.600m quây quần bên bếp lửa ấm áp.\"},{\"day\":3,\"title\":\"Chạm Đỉnh Pu Si Lung 3083m Đón Biển Mây - Trở Xuống Lán Bản Địa\",\"content\":\"3h sáng thức giấc leo dốc xuyên qua rừng đỗ quyên cổ thụ. Đón ánh bình minh vàng óng chiếu rọi biển mây bồng bềnh trên đỉnh Pu Si Lung 3.083m. Chụp ảnh vinh danh rồi quay trở xuống bản Pa Vệ Sử.\"},{\"day\":4,\"title\":\"Pa Vệ Sử - Lai Châu Tắm Lá Thuốc Dao Đỏ - Xe Về Lại Hà Nội\",\"content\":\"Đoàn về trung tâm Lai Châu ngâm mình trong bồn tắm lá thuốc thảo mộc của người Dao Đỏ phục hồi cơ bắp. Thưởng thức bữa liên hoan lẩu cá tầm rồi lên xe về Hà Nội.\"}]','[\"Xe giường nằm VIP khứ hồi Hà Nội - Lai Châu\",\"Giấy phép biên phòng tham quan cột mốc biên giới\",\"Đội ngũ Hướng dẫn viên chứng chỉ cứu hộ quốc tế & Porter mang vác đồ\",\"Trọn gói lều trại, túi ngủ chuyên dụng, đồ ăn thức uống nóng sốt\",\"Gói tắm lá thuốc hồi phục cơ thể & Bảo hiểm mạo hiểm 100 triệu đồng\"]','[\"Trang bị đồ cá nhân (giày trekking, balo, gậy leo núi)\",\"Tiền tip bồi dưỡng đội ngũ porter và hoa tiêu\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(60,7,1,'Trekking Vườn Quốc Gia Bạch Mã - Khám Phá Ngũ Hồ - Thác Đỗ Quyên Hùng Vĩ 2N1Đ','Thám hiểm \'Đà Lạt của xứ Huế\': dạo bước ngắm mây từ Vọng Hải Đài, lội suối ngâm mình làn nước ngọc bích Ngũ Hồ và chiêm ngưỡng Thác Đỗ Quyên cao 300m hùng vĩ như suối tóc mây tuôn trào.',2350000.00,2,'Đà Nẵng','https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?w=1200&q=80',290,'2026-11-21','2026-11-22','ACTIVE',4.8,2850000.00,'Xe du lịch đời mới & Xe chuyên dụng vượt đèo Bạch Mã',3,'MỚI RA MẮT','[\"Đứng trên Vọng Hải Đài ngắm toàn cảnh đầm phá Tam Giang và vịnh Lăng Cô\",\"Tắm suối thiên nhiên trong vắt tại quần thể Ngũ Hồ Bạch Mã\",\"Chinh phục đỉnh Thác Đỗ Quyên - thác nước kỳ vĩ rơi từ độ cao 300m giữa rừng già\",\"Khám phá hệ sinh thái động thực vật rừng mưa nhiệt đới chuyển tiếp đa dạng\"]','[{\"day\":1,\"title\":\"Đà Nẵng - Vườn Quốc Gia Bạch Mã - Vọng Hải Đài - Ngũ Hồ\",\"content\":\"Xe đón khách tại Đà Nẵng đưa lên đỉnh núi Bạch Mã cao 1.450m. Thăm Vọng Hải Đài rung chuông hòa bình ngắm cảnh non nước. Trekking xuyên rừng đến Ngũ Hồ, thưởng thức bữa trưa picnic bên bờ hồ và thỏa thích bơi lội trong làn nước mát lành.\"},{\"day\":2,\"title\":\"Thác Đỗ Quyên Cao 300m - Biệt Thự Cổ Pháp - Trở Về Đà Nẵng\",\"content\":\"Trekking qua rừng đỗ quyên đến đỉnh thác Đỗ Quyên. Thử thách bước xuống 689 bậc đá ngắm nhìn toàn cảnh chân thác nước tung bọt trắng xóa tuyệt mỹ. Ghé thăm các biệt thự cổ phong cách Pháp thời thuộc địa rồi trở về Đà Nẵng.\"}]','[\"Xe đón tiễn máy lạnh từ Đà Nẵng hoặc Huế\",\"Xe bán tải/chuyên dụng chở khách lên đỉnh Bạch Mã\",\"Vé tham quan Vườn Quốc Gia Bạch Mã\",\"Lưu trú biệt thự cổ Bạch Mã hoặc khách sạn chân núi\",\"Hướng dẫn viên chuyên nghiệp & Bảo hiểm du lịch 100 triệu\"]','[\"Chi phí cá nhân, đồ uống ngoài chương trình\",\"Trang phục trekking cá nhân\",\"Thuế VAT 8%\"]','2026-10-28 10:38:44'),
(61,7,3,'Trekking Vườn Quốc Gia Cát Tiên - Thám Hiểm Rừng Mưa Nhiệt Đới & Bầu Sấu Hoang Dã 2N1Đ','Thâm nhập vào khu dự trữ sinh quyển thế giới Cát Tiên: đạp xe dưới tán rừng nguyên sinh rợp bóng cây Tung cổ thụ ngàn năm, đi xe mui trần ngắm thú hoang dã ban đêm và thám hiểm Bầu Sấu kỳ thú.',1950000.00,2,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=1200&q=80',340,'2026-11-28','2026-11-29','ACTIVE',4.8,2450000.00,'Xe du lịch đời mới & Xe chuyên dụng mui trần xem thú đêm',3,'HOT DEAL','[\"Khám phá khu Ramsar ngập nước Bầu Sấu - nơi sinh sống của cá sấu Xiêm nước ngọt quý hiếm\",\"Trải nghiệm độc nhất vô nhị: xe mui trần đi rừng ngắm thú ăn cỏ kiếm ăn ban đêm\",\"Check-in cây Tung ngàn năm tuổi rễ bạnh khổng lồ cao vút chạm mây\",\"Đạp xe băng rừng ngắm chim công, vượn đen má vàng và hươu nai hoang dã\"]','[{\"day\":1,\"title\":\"TP.HCM - Sông Đồng Nai - Vườn Quốc Gia Cát Tiên - Xem Thú Đêm\",\"content\":\"Xe đón đoàn tại TP.HCM đến bến phà Cát Tiên, vượt sông Đồng Nai vào rừng. Nhận phòng bungalow ven sông. Chiều đạp xe thăm cây Tung ngàn năm và ghé Trung tâm cứu hộ linh trưởng. 19h lên xe chuyên dụng mui trần rọi đèn ngắm đàn nai, hoẵng, chồn kiếm ăn trong đêm.\"},{\"day\":2,\"title\":\"Trekking Khám Phá Bầu Sấu - Trở Về Lại TP.HCM\",\"content\":\"Xe chở đoàn vào bìa rừng, trekking 5km dưới tán rừng nhiệt đới vào Bầu Sấu. Ngồi thuyền nan ngắm cá sấu bơi lội tự nhiên và đàn chim nước chao lượn. Trưa trở ra bến tàu, xe đón đoàn về TP.HCM.\"}]','[\"Xe du lịch máy lạnh đưa đón từ TP.HCM\",\"Vé qua phà và vé vào cổng Vườn Quốc Gia Cát Tiên\",\"Xe mui trần chuyên dụng xem thú ban đêm và đèn rọi\",\"Xe trung chuyển và vé tham quan Bầu Sấu\",\"Bảo hiểm du lịch trọn gói 100.000.000 VNĐ\"]','[\"Thuê xe đạp cá nhân (100.000đ/buổi)\",\"Chi phí cá nhân ngoài thực đơn\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(62,8,1,'Dubai - Abu Dhabi 5N4Đ: Đỉnh Tháp Burj Khalifa - Khách Sạn Cung Điện Emirates Palace - Safari Sa Mạc Đua Xe Địa Hình','Khám phá xứ sở tỷ phú sa mạc phồn hoa bậc nhất Trung Đông: chạm đỉnh tòa tháp Burj Khalifa cao nhất hành tinh, viếng Đại Thánh Đường Hồi Giáo Sheikh Zayed cẩm thạch trắng nguy nga và trải nghiệm tiệc nướng BBQ sa mạc Safari múa bụng Ả Rập.',28900000.00,5,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1512453979798-5ea266f8880c?w=1200&q=80',250,'2026-11-20','2026-11-24','ACTIVE',4.9,33900000.00,'Hàng không 5 sao Emirates Airbus A380 & Xe Land Cruiser 4x4',5,'TOUR CAO CẤP','[\"Bay cùng Hàng không 5 sao Emirates siêu sang với tiêu chuẩn dịch vụ hàng đầu\",\"Check-in tầng 124 tòa tháp cao nhất thế giới Burj Khalifa (828m)\",\"Trải nghiệm cảm giác mạnh ngồi xe Land Cruiser vượt cồn cát sa mạc Safari và cưỡi lạc đà\",\"Chiêm ngưỡng Đại Thánh Đường Hồi Giáo Sheikh Zayed dát vàng và phủ thảm dệt tay Ba Tư\"]','[{\"day\":1,\"title\":\"TP.HCM - Chuyến Bay Siêu Sang Emirates Đến Dubai\",\"content\":\"Đoàn tập trung tại sân bay Tân Sơn Nhất đáp chuyến bay thẳng hãng Emirates Airlines đi Dubai. Đến sân bay quốc tế Dubai, xe đón đoàn về khách sạn 5 sao nghỉ ngơi.\"},{\"day\":2,\"title\":\"Khu Phố Cổ Al Fahidi - Taxi Nước Abra - Chợ Vàng Gold Souk - Tháp Burj Khalifa\",\"content\":\"Khám phá phố cổ Al Fahidi bên dòng kênh Dubai Creek, đi taxi nước Abra truyền thống. Mua sắm tại Chợ Vàng Gold Souk với hàng trăm tấn vàng lộng lẫy và Chợ Gia Vị Spice Souk. Chiều lên đài quan sát tầng 124 Tháp Burj Khalifa ngắm toàn cảnh Dubai rực sáng.\"},{\"day\":3,\"title\":\"Đảo Cọ Palm Jumeirah - Tàu Điện Trên Không Monorail - Sa Mạc Safari Cưỡi Lạc Đà\",\"content\":\"Trải nghiệm tàu điện Monorail ngắm đảo nhân tạo Palm Jumeirah hình cây cọ và khách sạn Atlantis The Palm lừng danh. Buổi chiều xe Land Cruiser 4x4 đón đoàn phiêu lưu sa mạc Safari cát vàng: trượt cát, cưỡi lạc đà, vẽ henna và xem múa bụng Belly Dance bên tiệc BBQ Ả Rập.\"},{\"day\":4,\"title\":\"Abu Dhabi - Đại Thánh Đường Hồi Giáo Sheikh Zayed - Cung Điện Qasr Al Watan\",\"content\":\"Di chuyển đến thủ đô Abu Dhabi. Viếng Đại Thánh Đường Sheikh Zayed bằng đá cẩm thạch trắng lớn nhất UAE. Dạo bước trong Cung điện Tổng thống Qasr Al Watan uy nghi lộng lẫy. Ngắm Khách sạn 7 sao Emirates Palace tráng lệ.\"},{\"day\":5,\"title\":\"Dubai Mall Mua Sắm Hàng Hiệu - Sân Bay Dubai - Về Lại TP.HCM\",\"content\":\"Tự do mua sắm tại Dubai Mall trung tâm thương mại lớn nhất thế giới, xem màn trình diễn nhạc nước Water Fountain hoành tráng. Xe tiễn đoàn ra sân bay bay về TP.HCM.\"}]','[\"Vé máy bay khứ hồi hàng không 5 sao Emirates Airlines (gồm 30kg ký gửi + 7kg xách tay)\",\"Khách sạn 5 sao quốc tế suốt 4 đêm tại Dubai (2 khách/phòng)\",\"Visa nhập cảnh Dubai điện tử cho công dân Việt Nam\",\"Vé lên tầng 124 Tòa tháp Burj Khalifa & Trọn gói tour Sa mạc Safari xe Land Cruiser\",\"Bảo hiểm du lịch quốc tế mức bồi thường 1.000.000.000 VNĐ (1 Tỷ đồng)\"]','[\"Tiền tip bắt buộc hướng dẫn viên và tài xế (8 USD/khách/ngày)\",\"Phí cà phê dát vàng và bánh ngọt tại Khách sạn Emirates Palace\",\"Chi tiêu cá nhân ngoài chương trình\",\"Thuế VAT\"]','2026-10-28 10:38:44'),
(63,8,2,'Trung Quốc: Trương Gia Giới - Phượng Hoàng Cổ Trấn 6N5Đ: Cầu Kính Thiên Môn Sơn - Hồ Bảo Phong - Phố Cổ Nghìn Năm','Lạc vào chốn bồng lai tiên cảnh trần gian: check-in Cầu Kính Đại Hiệp Cốc vắt qua vực sâu, trải nghiệm cáp treo dài nhất thế giới lên đỉnh Thiên Môn Sơn ngắm Cổng Trời huyền bí, và thả hồn cùng dòng sông Đà Giang ngắm nghía những mái nhà sàn Điếu Cước Lâu nghìn năm cổ kính.',15990000.00,6,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=1200&q=80',260,'2026-11-22','2026-11-27','ACTIVE',4.9,18990000.00,'Chuyến bay thẳng Vietjet Air / Vietnam Airlines & Xe VIP 2+1',4,'BÁN CHẠY NHẤT','[\"Bay thẳng thuận tiện không quá cảnh tiết kiệm thời gian nghỉ ngơi tối đa\",\"Chinh phục Cầu Kính Thiên Môn Sơn lơ lửng giữa mây ngàn và vách đá dựng đứng\",\"Đi thuyền du ngoạn ngắm trọn vẻ đẹp lung linh huyền ảo của Phượng Hoàng Cổ Trấn về đêm\",\"Thưởng thức lẩu cá cay Miêu Gia, vịt hầm tiết và rượu nếp thơm lừng của người Thổ Gia\"]','[{\"day\":1,\"title\":\"TP.HCM - Chuyến Bay Thẳng Đến Trương Gia Giới\",\"content\":\"Tập trung tại sân bay Tân Sơn Nhất đáp chuyến bay thẳng đến sân bay Hà Hoa Trương Gia Giới. Xe đón đoàn về khách sạn 4 sao nhận phòng nghỉ ngơi dưỡng sức.\"},{\"day\":2,\"title\":\"Kỳ Quan Thiên Môn Sơn - Cáp Treo Kỷ Lục - Cổng Trời - Sàn Đạo Kính Vách Núi\",\"content\":\"Trải nghiệm tuyến cáp treo dài hơn 7.400m vượt qua biển mây lên Thiên Môn Sơn. Bước đi trên con đường kính bám vách đá dựng đứng đáy trong suốt. Chinh phục 999 bậc thang dẫn đến Cổng Trời kỳ bí. Chiều di chuyển về Phượng Hoàng Cổ Trấn.\"},{\"day\":3,\"title\":\"Phượng Hoàng Cổ Trấn Tuyệt Mỹ - Du Thuyền Sông Đà Giang - Điếu Cước Lâu\",\"content\":\"Dạo bước trên những cây cầu đá nhảy, cầu Hồng Kiều cổ kính. Ngắm nhìn những dãy nhà sàn gỗ Điếu Cước Lâu soi bóng xuống làn nước xanh ngắt của dòng sông Đà Giang. Buổi tối ngắm thị trấn cổ lên đèn lung linh như một bức tranh thủy mặc.\"},{\"day\":4,\"title\":\"Phượng Hoàng Cổ Trấn - Trương Gia Giới - Du Thuyền Hồ Bảo Phong\",\"content\":\"Khởi hành trở lại Trương Gia Giới. Ngồi thuyền êm trôi trên mặt nước phẳng lặng như gương của Hồ Bảo Phong nghe điệu hò sơn ca của chàng trai cô gái Thổ Gia. Chiều tham quan Viện Tranh Cát Quân Thanh độc đáo.\"},{\"day\":5,\"title\":\"Cầu Kính Đại Hiệp Cốc Grand Canyon - Phố Ảo 72 Kỳ Lầu\",\"content\":\"Khám phá Cầu Kính Đại Hiệp Cốc dài 430m bắc qua thung lũng sâu hun hút ngắm cảnh phim Avatar. Buổi tối ngắm tòa nhà kiến trúc 72 Kỳ Lầu tráng lệ rực rỡ ánh sáng đèn lồng.\"},{\"day\":6,\"title\":\"Trương Gia Giới Mua Sắm Trà Đen & Thảo Dược - Bay Về TP.HCM\",\"content\":\"Mua sắm trà đen, kẹo gừng cay nồng và cao dán thảo mộc. Xe tiễn đoàn ra sân bay đáp chuyến bay về lại TP.HCM, kết thúc chuyến đi đầy ắp kỷ niệm đẹp.\"}]','[\"Vé máy bay khứ hồi bay thẳng kèm hành lý ký gửi 20kg\",\"Khách sạn 4 sao tiện nghi phong cách cổ trang Trung Hoa\",\"Visa đoàn nhập cảnh Trung Quốc thuận tiện nhanh chóng\",\"Vé cáp treo Thiên Môn Sơn, vé Cầu Kính và thuyền sông Đà Giang\",\"Bảo hiểm du lịch quốc tế mức bồi thường 1.000.000.000 VNĐ\"]','[\"Tiền tip tài xế và HDV địa phương (5 USD/người/ngày)\",\"Vé xem show diễn nghệ thuật Rạng Rỡ Tương Tây (Charm Xiangxi)\",\"Chi phí cá nhân và thuế VAT\"]','2026-10-28 10:38:44'),
(64,8,3,'Bờ Tây Hoa Kỳ: Los Angeles - Las Vegas - San Francisco 8N7Đ: Hollywood Walk of Fame - Đại Vực Grand Canyon - Cầu Cổng Vàng Golden Gate','Giấc mơ Mỹ trọn vẹn tại các siêu đô thị bờ Tây: check-in Đại Lộ Danh Vọng Hollywood, chiêm ngưỡng kỳ quan thiên nhiên vĩ đại Grand Canyon hẻm vực triệu năm, khám phá Las Vegas kinh đô ánh sáng và dạo bước bên cây Cầu Cổng Vàng biểu tượng San Francisco.',89900000.00,8,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1501594907352-04cda38ebc29?w=1200&q=80',200,'2026-11-25','2026-12-02','ACTIVE',4.9,105000000.00,'Hàng không quốc tế Eva Air / All Nippon Airways & Xe VIP Coach',4,'TOUR CAO CẤP','[\"Chuyến bay đẳng cấp 5 sao quốc tế khứ hồi đến Los Angeles và San Francisco\",\"Check-in Đại lộ Danh Vọng Hollywood, Nhà hát Dolby nơi trao giải Oscar lừng danh\",\"Khám phá kỳ quan hẻm núi Grand Canyon ngoạn mục vĩ đại nhất hành tinh\",\"Dạo bước trên Cầu Cổng Vàng Golden Gate và đi xe cáp treo Cable Car lịch sử San Francisco\"]','[{\"day\":1,\"title\":\"TP.HCM - Quá Cảnh Đài Bắc / Tokyo - Hạ Cánh Los Angeles \'Kinh Đô Điện Ảnh\'\",\"content\":\"Đoàn tập trung tại sân bay Tân Sơn Nhất, đáp chuyến bay xuyên Thái Bình Dương đi Los Angeles. Do chênh lệch múi giờ, đoàn đến Los Angeles cùng ngày. Xe đón đoàn về khách sạn 4 sao nghỉ ngơi điều chỉnh nhịp sinh học.\"},{\"day\":2,\"title\":\"Hollywood Walk of Fame - Nhà Hát Dolby - Phim Trường Universal Studios\",\"content\":\"Dạo bước trên Đại lộ Danh Vọng tìm kiếm ngôi sao của các huyền thoại điện ảnh. Check-in Nhà hát TCL Chinese và Nhà hát Dolby. Trải nghiệm một ngày phiêu lưu bất tận tại phim trường Universal Studios Hollywood với các kỹ xảo điện ảnh đỉnh cao.\"},{\"day\":3,\"title\":\"Los Angeles - Xuyên Sa Mạc Mojave - Thành Phố Không Ngủ Las Vegas\",\"content\":\"Xe đưa đoàn xuyên qua sa mạc Mojave cát trắng đến Las Vegas kinh đô sòng bạc thế giới. Mua sắm tại Barstow Outlet với hàng trăm thương hiệu thời trang Mỹ giảm giá sâu. Tối ngắm màn nhạc nước Bellagio và dải khách sạn The Strip rực rỡ ánh đèn neon.\"},{\"day\":4,\"title\":\"Đại Vực Grand Canyon Hùng Vĩ - Đập Thủy Điện Hoover Dam\",\"content\":\"Khởi hành đi chiêm ngưỡng Đập nước Hoover Dam kỳ quan công trình thế kỷ 20 và Hồ Mead. Tiếp tục đến Đại Vực Grand Canyon West Rim, ngắm nhìn hẻm núi sâu thăm thẳm với những tầng đá trầm tích đỏ rực triệu năm.\"},{\"day\":5,\"title\":\"Las Vegas - Bay Đến San Francisco \'Thành Phố Sương Mù Bờ Tây\'\",\"content\":\"Đáp chuyến bay nội địa từ Las Vegas đến San Francisco. Dạo bước ngắm vịnh San Francisco từ Bến Ngư Phủ Fisherman\'s Wharf, xem hải cẩu tắm nắng tại Pier 39 và thưởng thức món súp nghêu Clam Chowder truyền thống trứ danh.\"},{\"day\":6,\"title\":\"Cầu Cổng Vàng Golden Gate - Đường Hoa Lombard Cổ Kính - Phố Người Hoa\",\"content\":\"Dạo bước và chụp ảnh lưu niệm cùng biểu tượng Cầu Cổng Vàng (Golden Gate Bridge) huyền thoại. Chiêm ngưỡng đường hoa Lombard uốn lượn dốc quanh co nhất thế giới. Đi xe cáp treo kéo bằng dây cáp Cable Car cổ điển.\"},{\"day\":7,\"title\":\"Thung Lũng Silicon - Trụ Sở Google / Apple - Sân Bay San Francisco\",\"content\":\"Thăm trung tâm công nghệ thế giới Silicon Valley, check-in trụ sở phi thuyền Apple Park và Googleplex. Mua sắm hàng điện tử Apple chính hãng. Xe đưa đoàn ra sân bay quốc tế San Francisco làm thủ tục bay về Việt Nam.\"},{\"day\":8,\"title\":\"Bay Xuyên Thái Bình Dương - Về Đến Sân Bay Tân Sơn Nhất TP.HCM\",\"content\":\"Vượt qua đường đổi ngày quốc tế. Đoàn về đến sân bay Tân Sơn Nhất TP.HCM, kết thúc hải trình 8 ngày giấc mơ Mỹ tuyệt vời và trọn vẹn.\"}]','[\"Vé máy bay quốc tế khứ hồi 5 sao Eva Air / ANA (2 kiện hành lý xách tay 23kg/kiện)\",\"Chuyến bay nội địa Las Vegas - San Francisco\",\"Khách sạn 4 sao chuẩn Mỹ suốt hành trình (2 người/phòng)\",\"Vé vào cổng Phim trường Universal Studios & Vé tham quan Grand Canyon\",\"Thư mời bảo lãnh visa và hướng dẫn phỏng vấn visa Mỹ chuyên nghiệp\",\"Bảo hiểm du lịch quốc tế mức trách nhiệm 1.500.000.000 VNĐ (1.5 Tỷ đồng)\"]','[\"Lệ phí phỏng vấn visa Hoa Kỳ nộp Lãnh sự quán (185 USD)\",\"Tiền tip lái xe và HDV (10 USD/khách/ngày)\",\"Vé đi cầu kính Skywalk tại Grand Canyon (nếu tham gia)\",\"Chi tiêu cá nhân ngoài chương trình\"]','2026-10-28 10:38:44'),
(65,1,231,'Hà Nội - Cao Bằng - Thác Bản Giốc - Hồ Ba Bể - Động Ngườm Ngao 3N2Đ','Hành trình khám phá non nước Cao Bằng hùng vĩ: chiêm ngưỡng thác nước tự nhiên lớn thứ 4 thế giới Bản Giốc, dạo thuyền thong dong ngắm hồ Ba Bể nguyên sơ và khám phá kỳ quan thạch nhũ động Ngườm Ngao.',3490000.00,3,'Hà Nội','https://images.unsplash.com/photo-1528127269322-539801943592?w=800',280,'2026-11-05','2026-11-07','ACTIVE',4.9,4290000.00,'Xe Universe 45 chỗ & Thuyền máy Ba Bể',3,'ĐIỂM ĐẾN HẤP DẪN','[\"Chiêm ngưỡng vẻ đẹp kỳ vĩ của Thác Bản Giốc - thác nước biên giới lớn nhất Đông Nam Á\",\"Khám phá Động Ngườm Ngao với hệ thống nhũ đá lung linh ngàn năm tuổi\",\"Du thuyền trên lòng Hồ Ba Bể phẳng lặng như gương soi bóng mây trời\",\"Thưởng thức đặc sản vịt quay 7 vị Cao Bằng, xôi trám đen và cá suối nướng\"]','[{\"day\":1,\"title\":\"Hà Nội - Thái Nguyên - Cao Bằng - Đèo Gió\",\"content\":\"Xe Universe đón đoàn tại điểm hẹn trung tâm Hà Nội, khởi hành đi Cao Bằng theo quốc lộ 3. Dừng chân ngắm cảnh đèo Gió, thưởng thức bánh dứa Đèo Khau Khang. Chiều đến Cao Bằng nhận phòng khách sạn, tự do khám phá phố đi bộ Kim Đồng.\"},{\"day\":2,\"title\":\"Thác Bản Giốc - Động Ngườm Ngao - Làng Rèn Phúc Sen\",\"content\":\"Khởi hành tham quan Thác Bản Giốc trên sông Quây Sơn. Đi bè mảng ngắm từng tầng thác đổ trắng xóa. Chiều khám phá Động Ngườm Ngao kỳ vĩ, ghé thăm làng rèn dao thủ công Phúc Sen nổi tiếng của người Nùng An.\"},{\"day\":3,\"title\":\"Vườn Quốc Gia Hồ Ba Bể - Đảo Bà Góa - Trở Về Hà Nội\",\"content\":\"Di chuyển sang Bắc Kạn, xuống thuyền khám phá hồ Ba Bể: Ao Tiên, Đền An Mạ, Đảo Bà Góa. Thưởng thức bữa trưa cá hồ và rau rừng tại bản Pác Ngòi. Chiều khởi hành về lại Hà Nội, kết thúc chuyến đi tuyệt vời.\"}]','[\"Xe du lịch Universe đời mới máy lạnh đưa đón suốt hành trình\",\"Khách sạn 3 sao tiện nghi trung tâm TP Cao Bằng và Ba Bể\",\"Vé tham quan Thác Bản Giốc, Động Ngườm Ngao, thuyền tham quan Hồ Ba Bể\",\"Bảo hiểm du lịch nội địa mức bồi thường 100.000.000 VNĐ/khách\",\"Hướng dẫn viên chuyên tuyến Đông Bắc thuyết minh nhiệt tình\"]','[\"Bè mảng ngắm thác Bản Giốc cự ly gần (50.000đ/người)\",\"Chi phí cá nhân ngoài chương trình (giặt là, đồ uống)\",\"Tiền bồi dưỡng (tip) cho lái xe và hướng dẫn viên\",\"Thuế VAT 8% (nếu yêu cầu xuất hóa đơn đỏ)\"]','2026-10-28 15:54:14'),
(66,1,232,'Hà Nội - Mù Cang Chải - Suối Khoáng Nóng Trạm Tấu - Đèo Khau Phạ 3N2Đ','Chinh phục vẻ đẹp kỳ ảo của kiệt tác ruộng bậc thang Mù Cang Chải: ngắm sóng lúa Mâm Xôi, Móng Ngựa, vượt đèo Khau Phạ hiểm trở và thư giãn ngâm mình trong suối khoáng nóng tự nhiên Trạm Tấu.',2990000.00,3,'Hà Nội','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',250,'2026-11-06','2026-11-08','ACTIVE',4.8,3690000.00,'Xe Universe 29 - 35 chỗ cao cấp',3,'SĂN MÂY TÂY BẮC','[\"Check-in danh thắng Ruộng bậc thang Đồi Mâm Xôi và Đồi Móng Ngựa trứ danh\",\"Chinh phục Đèo Khau Phạ - một trong \\\"Tứ đại đỉnh đèo\\\" Tây Bắc hùng vĩ\",\"Thư giãn tắm suối khoáng nóng tự nhiên Trạm Tấu ngắm view thung lũng mây\",\"Thưởng thức lẩu gà đen vùng cao, xôi ngũ sắc nếp nương Tú Lệ ngào ngạt hương thơm\"]','[{\"day\":1,\"title\":\"Hà Nội - Thị Xã Nghĩa Lộ - Suối Khoáng Nóng Trạm Tấu\",\"content\":\"Xe đón đoàn từ Nhà Hát Lớn Hà Nội xuất phát đi Yên Bái. Trưa đến Nghĩa Lộ thưởng thức ẩm thực Thái Mường Lò. Chiều đến Trạm Tấu nhận bungalow, tự do ngâm tắm khoáng nóng thư giãn giữa núi rừng xanh mát.\"},{\"day\":2,\"title\":\"Đèo Khau Phạ - Đồi Mâm Xôi - Mù Cang Chải\",\"content\":\"Vượt đỉnh đèo Khau Phạ bồng bềnh mây trắng, ngắm thung lũng Cao Phạ rực rỡ lúa vàng. Chiều di chuyển xe ôm bản địa lên đồi Mâm Xôi check-in kiệt tác ruộng bậc thang. Tối thưởng thức giao lưu văn nghệ bản Lìm Mông.\"},{\"day\":3,\"title\":\"Đồi Móng Ngựa - Thung Lũng Tú Lệ - Mua Cốm - Hà Nội\",\"content\":\"Sáng sớm săn bình minh tại Đồi Móng Ngựa. Sau đó về Tú Lệ ghé chợ quê mua cốm non và xôi nếp Tú Lệ nức tiếng. Xe đưa đoàn về lại Hà Nội vào chiều tối.\"}]','[\"Xe du lịch đời mới máy lạnh đưa đón Hà Nội - Mù Cang Chải - Hà Nội\",\"1 đêm nghỉ dưỡng bungalow khoáng nóng Trạm Tấu + 1 đêm khách sạn Mù Cang Chải\",\"Vé vào cổng các điểm tham quan theo chương trình\",\"Vé tắm khoáng nóng không giới hạn tại Trạm Tấu\",\"Bảo hiểm du lịch nội địa 100.000.000 VNĐ/vụ\"]','[\"Xe ôm địa phương lên đồi Mâm Xôi và đồi Móng Ngựa\",\"Chi phí dù lượn lướt sóng Mù Cang Chải trên đèo Khau Phạ\",\"Đồ uống trong các bữa ăn và chi phí cá nhân ngoài hành trình\"]','2026-10-28 15:54:14'),
(67,2,2,'Đà Nẵng - Cù Lao Chàm - Phố Cổ Hội An - Cầu Vàng Bà Nà 3N2Đ','Chuyến du ngoạn biển xanh và di sản văn hóa: lặn ngắm san hô tại khu dự trữ sinh quyển thế giới Cù Lao Chàm, thả đèn hoa đăng sông Hoài thơ mộng và sải bước trên Cầu Vàng Bà Nà Hills tráng lệ.',3990000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?w=800',300,'2026-11-10','2026-11-12','ACTIVE',4.9,4990000.00,'Máy bay khứ hồi & Cano cao tốc',4,'TOUR NỔI BẬT','[\"Lướt sóng cano cao tốc ra Đảo Cù Lao Chàm, lặn ngắm rạn san hô rực rỡ sắc màu\",\"Check-in Cầu Vàng bàn tay khổng lồ và ngắm toàn cảnh đỉnh núi Chúa Bà Nà\",\"Thả đèn hoa đăng cầu an và du thuyền trên sông Hoài phố cổ Hội An về đêm\",\"Khách sạn 4 sao sát biển Mỹ Khê với bể bơi vô cực ngắm bình minh đại dương\"]','[{\"day\":1,\"title\":\"TP.HCM / Hà Nội - Đà Nẵng - Cù Lao Chàm - Hội An\",\"content\":\"Đáp chuyến bay sáng đến Đà Nẵng. Xe đón đoàn ra cảng Cửa Đại lên cano cao tốc đi Cù Lao Chàm: thăm Chùa Hải Tạng, Giếng cổ Chăm, tắm biển Bãi Ông và lặn ngắm san hô. Chiều về nhận phòng, tối dạo phố cổ Hội An rực rỡ ánh đèn lồng.\"},{\"day\":2,\"title\":\"Sun World Ba Na Hills - Check-in Cầu Vàng Biểu Tượng\",\"content\":\"Đi cáp treo Bà Nà đạt kỷ lục thế giới. Dạo bước trên Cầu Vàng vươn giữa mây trời, khám phá Làng Pháp, Hầm rượu Debay và Vườn hoa Le Jardin D\'Amour. Tối tự do ngắm cầu Rồng phun lửa tại Đà Nẵng.\"},{\"day\":3,\"title\":\"Bán Đảo Sơn Trà - Chợ Hàn Mua Quà - Tiễn Sân Bay\",\"content\":\"Viếng Chùa Linh Ứng Bãi Bụt chiêm ngưỡng tượng Phật Bà 67m. Mua sắm đặc sản chả bò, mực rim me tại chợ Hàn. Xe tiễn đoàn ra sân bay Đà Nẵng về lại điểm đón.\"}]','[\"Vé máy bay khứ hồi các hãng hàng không hàng đầu (kèm 20kg ký gửi)\",\"Khách sạn 4 sao gần biển Mỹ Khê (2 người/phòng)\",\"Vé cano cao tốc + vé tham quan sinh thái Cù Lao Chàm + lặn ngắm san hô\",\"Vé cáp treo Bà Nà Hills và buffet trưa thượng hạng\",\"Xe du lịch máy lạnh đời mới Universe và bảo hiểm du lịch 100M\"]','[\"Vé Bảo tàng Tượng sáp và hầm rượu Debay cao cấp\",\"Chi phí cá nhân ngoài chương trình, đồ uống minibar\",\"Tiền tip hướng dẫn viên và lái xe\"]','2026-10-28 15:54:14'),
(68,2,230,'Quy Nhơn - Kỳ Co - Eo Gió - Ghềnh Ráng Tiên Sa - Đảo Hòn Khô 3N2Đ','Chiêm ngưỡng thiên đường Maldives của Việt Nam với bãi cát vàng mịn và làn nước trong vắt tại bãi tắm Kỳ Co, đón luồng gió lộng mát rượi tại Eo Gió và viếng mộ thi sĩ Hàn Mặc Tử bên bờ biển Quy Nhơn.',3290000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800',260,'2026-11-12','2026-11-14','ACTIVE',4.8,4190000.00,'Máy bay khứ hồi & Cano siêu tốc',4,'THIÊN ĐƯỜNG BIỂN XANH','[\"Tắm biển và lặn ngắm san hô Bãi Kỳ Co - thiên đường biển trong vắt nhìn tận đáy\",\"Dạo bước trên con đường ven vách đá hùng vĩ tại Eo Gió - nơi ngắm hoàng hôn đẹp nhất VN\",\"Viếng mộ thi sĩ Hàn Mặc Tử, Bãi Trứng Hoàng Hậu tại danh thắng Ghềnh Ráng\",\"Thưởng thức đại tiệc hải sản tươi sống Nhơn Lý: ốc vú nàng, cua huỳnh đế, mực một nắng\"]','[{\"day\":1,\"title\":\"TP.HCM - Quy Nhơn - Ghềnh Ráng Tiên Sa - Tháp Đôi\",\"content\":\"Bay đến sân bay Phù Cát Quy Nhơn. Xe đón đoàn viếng Ghềnh Ráng Tiên Sa, viếng mộ nhà thơ Hàn Mặc Tử, Bãi tắm Hoàng Hậu với hàng triệu viên đá cuội nhẵn bóng. Chiều thăm Tháp Đôi Chăm Pa cổ kính.\"},{\"day\":2,\"title\":\"Cầu Thị Nại - Cano Siêu Tốc Đi Kỳ Co - Eo Gió\",\"content\":\"Vượt cầu vượt biển Thị Nại dài gần 2,5km sang bán đảo Phương Mai. Cano cao tốc đưa đoàn ra Bãi Kỳ Co tắm biển, lặn ngắm san hô Hòn Sẹo. Chiều dạo bước trên cung đường đi bộ ven biển Eo Gió hùng vĩ.\"},{\"day\":3,\"title\":\"Làng Chài Nhơn Hải - Đảo Hòn Khô - Mua Sắm - Tiễn Bay\",\"content\":\"Khám phá con đường đi bộ xuyên biển tại Hòn Khô. Mua sắm đặc sản bánh ít lá gai, nem Chợ Huyện, mực rim tỏi ớt. Xe tiễn đoàn ra sân bay về lại TP.HCM.\"}]','[\"Vé máy bay khứ hồi kèm hành lý ký gửi\",\"Khách sạn 4 sao trung tâm view biển Quy Nhơn\",\"Cano cao tốc tham quan Kỳ Co và dụng cụ lặn ngắm san hô\",\"Các bữa ăn hải sản tiêu chuẩn cao theo thực đơn địa phương\",\"Bảo hiểm du lịch bồi thường 100.000.000 VNĐ\"]','[\"Dịch vụ lặn bình khí oxy chuyên nghiệp (Scuba diving)\",\"Xe điện tham quan đồi cát Phương Mai\",\"Chi phí chi tiêu cá nhân ngoài chương trình\"]','2026-10-28 15:54:14'),
(69,3,4,'TP.HCM - Tây Ninh - Đỉnh Núi Bà Đen - Chùa Gò Kén - Tòa Thánh 1 Ngày','Chuyến hành hương tâm linh và chinh phục nóc nhà Nam Bộ: trải nghiệm cáp treo Sun World núi Bà Đen chiêm bái Đại tượng Phật Bà Tây Bổ Đà Sơn cao nhất Châu Á, viếng Tòa Thánh Cao Đài và Chùa Gò Kén thanh tịnh.',890000.00,1,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800',350,'2026-11-08','2026-11-08','ACTIVE',4.9,1190000.00,'Xe Limousine VIP 18 chỗ',4,'HÀNH HƯƠNG TÂM LINH','[\"Chinh phục đỉnh Núi Bà Đen cao 986m bồng bềnh mây trắng\",\"Chiêm bái Đại tượng Phật Bà Tây Bổ Đà Sơn bằng đồng cao nhất Châu Á trên đỉnh núi\",\"Viếng Tòa Thánh Tây Ninh - công trình kiến trúc tôn giáo độc nhất vô nhị\",\"Thưởng thức đặc sản bò tơ Tây Ninh nướng tảng thơm lừng và bánh canh Trảng Bàng\"]','[{\"day\":1,\"title\":\"TP.HCM - Tòa Thánh Tây Ninh - Đỉnh Núi Bà Đen - Trở Về\",\"content\":\"06h00 đón khách tại trung tâm Quận 1 khởi hành đi Tây Ninh. Thưởng thức bữa sáng bánh canh Trảng Bàng. Đến núi Bà Đen đi cáp treo lên đỉnh chiêm ngưỡng tượng Phật Bà và ngắm biển mây ngút ngàn. Thưởng thức buffet trưa trên đỉnh núi. Chiều viếng Tòa Thánh Tây Ninh và Chùa Gò Kén cổ tự. 18h30 về lại TP.HCM.\"}]','[\"Xe du lịch Limousine cao cấp đưa đón trọn ngày từ TP.HCM\",\"Vé cáp treo tuyến đỉnh Vân Sơn khứ hồi Núi Bà Đen\",\"Bữa trưa buffet ẩm thực trên đỉnh núi Bà Đen\",\"Bữa sáng bánh canh Trảng Bàng đặc sản\",\"Bảo hiểm du lịch nội địa 100.000.000 VNĐ/khách\"]','[\"Vé cáp treo tuyến Chùa Hang (nếu khách đi thêm)\",\"Mua sắm muối tôm Tây Ninh, mãng cầu Bà Đen\",\"Chi phí cá nhân ngoài hành trình\"]','2026-10-28 15:54:14'),
(70,3,3,'TP.HCM - Hồ Tràm Resort 5 Sao - Suối Khoáng Nóng Minera Bình Châu 2N1Đ','Chuyến nghỉ dưỡng tái tạo năng lượng đẳng cấp 5 sao: ngâm khoáng nóng tự nhiên chuẩn Nhật Bản tại Minera Hot Springs Bình Châu, dạo bộ giữa rừng nguyên sinh và tận hưởng kỳ nghỉ bên bờ biển Hồ Tràm thanh bình.',2790000.00,2,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800',240,'2026-11-14','2026-11-15','ACTIVE',4.8,3590000.00,'Xe Limousine VIP 18 chỗ',5,'NGHỈ DƯỠNG ONSEN','[\"Thư giãn ngâm khoáng nóng tự nhiên tại Minera Hot Springs Bình Châu - nguồn khoáng quý giá Nam Bộ\",\"Trải nghiệm luộc trứng trường thọ 82 độ C ngắm bình minh hồ nước khoáng sôi\",\"Nghỉ dưỡng resort 5 sao mặt biển Hồ Tràm với bãi cát dài êm đềm không ồn ào\",\"Thưởng thức đại tiệc hải sản ghẹ rang me, tôm sú nướng bơ tỏi tại làng chài Phước Hải\"]','[{\"day\":1,\"title\":\"TP.HCM - Suối Khoáng Minera Bình Châu - Luộc Trứng Khoáng\",\"content\":\"Xe Limousine đón đoàn khởi hành theo cao tốc Long Thành - Dầu Giây. Đến Bình Châu, khám phá công viên rừng Minera Forest, ngâm mình trong hồ khoáng nóng Onsen lộ thiên, trải nghiệm luộc trứng lòng đào trong giếng khoáng sôi. Chiều về nhận phòng resort 5 sao Hồ Tràm tắm biển.\"},{\"day\":2,\"title\":\"Cầu Ngắm Biển Hamptons Pier - Hải Sản Phước Hải - TP.HCM\",\"content\":\"Thưởng thức buffet sáng chuẩn quốc tế. Tự do tắm hồ bơi vô cực hoặc check-in Cầu đi bộ ngắm biển Hamptons Pier dài nhất Châu Á. Trưa trả phòng ghé làng chài Phước Hải thưởng thức hải sản tươi rói. Chiều khởi hành về lại TP.HCM.\"}]','[\"Xe Limousine VIP cao cấp đưa đón khứ hồi TP.HCM - Hồ Tràm\",\"1 đêm nghỉ dưỡng tại Resort 5 sao mặt biển Hồ Tràm (Melia hoặc The Grand)\",\"Gói vé ngâm khoáng nóng Onsen và luộc trứng tại Minera Hot Springs\",\"Bữa sáng buffet cao cấp tại resort + 2 bữa chính ẩm thực hải sản\",\"Bảo hiểm du lịch cao cấp mức 100.000.000 VNĐ\"]','[\"Dịch vụ spa trị liệu chuyên sâu và tắm bùn khoáng nóng\",\"Chi phí mini bar, giặt là phòng khách sạn\",\"Thuế VAT 8% (nếu cần xuất hóa đơn tài chính)\"]','2026-10-28 15:54:14'),
(71,4,230,'Cần Thơ - Chợ Nổi Cái Răng - Rừng Tràm Trà Sư - Làng Cá Bè Châu Đốc 2N1Đ','Hành trình đậm chất phù sa sông nước miền Tây: lênh đênh chợ nổi Cái Răng tấp nập buổi sớm, chèo xuồng ba lá len lỏi thảm bèo xanh mướt rừng tràm Trà Sư và viếng Miếu Bà Chúa Xứ núi Sam linh thiêng.',1890000.00,2,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1528181304800-259b08848526?w=800',280,'2026-11-15','2026-11-16','ACTIVE',4.8,2490000.00,'Xe Universe 45 chỗ & Tàu du lịch Cần Thơ',3,'SÔNG NƯỚC MIỀN TÂY','[\"Trải nghiệm văn hóa chợ nổi Cái Răng - thưởng thức hủ tiếu thuyền và cà phê kho trên sông\",\"Chèo xuồng ba lá lướt trên thảm bèo hoa dâu xanh mướt của Rừng Tràm Trà Sư\",\"Viếng Miếu Bà Chúa Xứ Núi Sam linh ứng bậc nhất vùng Thất Sơn An Giang\",\"Thưởng thức lẩu mắm cá linh bông điên điển, cá lóc nướng trui cuốn lá sen non\"]','[{\"day\":1,\"title\":\"TP.HCM - Đồng Tháp Mười - Rừng Tràm Trà Sư - Châu Đốc\",\"content\":\"Xe đón đoàn qua cầu Mỹ Thuận sang An Giang. Trưa đến Rừng Tràm Trà Sư đi tắc ráng và xuồng ba lá ngắm các loài chim quý trú ngụ. Chiều về Châu Đốc viếng Miếu Bà Chúa Xứ núi Sam, Lăng Thoại Ngọc Hầu và Tây An Cổ Tự. Tối nghỉ ngơi tại TP. Châu Đốc.\"},{\"day\":2,\"title\":\"Cần Thơ - Chợ Nổi Cái Răng - Lò Hủ Tiếu - Về TP.HCM\",\"content\":\"Sáng sớm lên thuyền du ngoạn Chợ nổi Cái Răng, chiêm ngưỡng \\\"cây bẹo\\\" rao hàng độc đáo. Ghé lò hủ tiếu truyền thống thưởng thức pizza hủ tiếu giòn tan. Trưa ăn lẩu mắm Miền Tây tại Cần Thơ. Chiều khởi hành theo cao tốc Trung Lương về lại TP.HCM.\"}]','[\"Xe du lịch đời mới máy lạnh Universe đưa đón toàn tuyến\",\"Khách sạn 3 sao tiện nghi trung tâm Châu Đốc\",\"Tàu du lịch chợ nổi Cái Răng và vé xuồng ba lá Rừng Tràm Trà Sư\",\"Các bữa ăn đặc sản Nam Bộ theo chương trình\",\"Bảo hiểm du lịch bồi thường tối đa 100.000.000 VNĐ\"]','[\"Lễ vật dâng Miếu Bà Chúa Xứ và đồ cúng tâm linh\",\"Mua sắm mắm Châu Đốc, đường thốt nốt mang về\",\"Chi phí chi tiêu cá nhân và tiền tip\"]','2026-10-28 15:54:14'),
(72,4,2,'TP.HCM - Bạc Liêu - Nhà Công Tử Bạc Liêu - Mũi Cà Mau Cực Nam 3N2Đ','Chạm tay vào cột mốc tọa độ quốc gia cực Nam Tổ quốc: thăm dinh thự lộng lẫy của Công tử Bạc Liêu, ngắm cánh đồng điện gió Bạc Liêu trải dài trên biển và viếng Đền thờ Mẹ Nam Hải linh thiêng.',3190000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800',270,'2026-11-20','2026-11-22','ACTIVE',4.9,3990000.00,'Xe Universe 45 chỗ đời mới & Vỏ lãi Mũi Cà Mau',4,'CỰC NAM TỔ QUỐC','[\"Chạm tay vào Cột mốc tọa độ Quốc gia GPS 0001 tại Đất Mũi Cà Mau\",\"Tham quan Nhà Công tử Bạc Liêu với kiến trúc Pháp cổ tráng lệ và nghe giai thoại đốt tiền\",\"Check-in Cánh đồng Điện Gió Bạc Liêu với hàng chục trụ tuabin khổng lồ trên biển\",\"Thưởng thức cua Cà Mau chính gốc chắc thịt ngọt lịm, vọp nướng mỡ hành thơm phức\"]','[{\"day\":1,\"title\":\"TP.HCM - Sóc Trăng - Chùa Dơi - Bạc Liêu - Điện Gió\",\"content\":\"Xe đón đoàn từ TP.HCM đi Sóc Trăng viếng Chùa Dơi, Chùa Chén Kiểu kiến trúc Khmer độc đáo. Chiều đến Bạc Liêu check-in Cánh đồng Điện Gió trên biển tuyệt đẹp. Tối thăm Nhà Công tử Bạc Liêu.\"},{\"day\":2,\"title\":\"Bạc Liêu - Năm Căn - Đất Mũi Cà Mau - Rừng Ngập Mặn\",\"content\":\"Di chuyển xuống Năm Căn, lên cano lướt sóng xuyên rừng ngập mặn ra Mũi Cà Mau. Chụp hình tại Mốc tọa độ quốc gia GPS 0001, ngắm biểu tượng Con Tàu hướng ra biển Đông. Chiều về TP Cà Mau nhận phòng 4 sao nghỉ ngơi.\"},{\"day\":3,\"title\":\"Nhà Thờ Tắc Sậy (Cha Diệp) - Tiễn Về Lại TP.HCM\",\"content\":\"Sáng viếng Nhà thờ Tắc Sậy cầu bình an tại mộ phần Cha Trương Bửu Diệp. Ghé mua đặc sản tôm khô Cà Mau, bánh phồng tôm Năm Căn. Chiều khởi hành về lại TP.HCM.\"}]','[\"Xe Universe đời mới máy lạnh đón tiễn trọn vẹn lịch trình\",\"Khách sạn 4 sao tiêu chuẩn quốc tế tại TP. Cà Mau và Bạc Liêu\",\"Cano cao tốc tham quan Công viên Văn hóa Mũi Cà Mau\",\"Bữa tiệc hải sản cua gạch Cà Mau và tôm sú nướng than hoa\",\"Bảo hiểm du lịch nội địa 100.000.000 VNĐ\"]','[\"Đồ uống trong bữa ăn và minibar khách sạn\",\"Lễ vật dâng Cha Diệp và cúng dường Chùa\",\"Chi phí mua sắm hải sản khô đem về\"]','2026-10-28 15:54:14'),
(73,5,3,'Khám Phá Thiên Đường Đảo Ngọc Phú Quốc - Grand World - Cáp Treo Hòn Thơm 3N2Đ','Trải nghiệm thiên đường nghỉ dưỡng hàng đầu thế giới: lướt cáp treo vượt biển 3 dây dài nhất thế giới Hòn Thơm, hòa mình vào không khí sôi động của thành phố không ngủ Grand World và tắm biển Bãi Sao tuyệt mỹ.',5490000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800',320,'2026-11-18','2026-11-20','ACTIVE',4.9,6890000.00,'Máy bay khứ hồi Vietnam Airlines / Bamboo',4,'ĐẢO NGỌC QUYẾN RŨ','[\"Trải nghiệm Cáp treo vượt biển Hòn Thơm dài gần 7,9km ngắm toàn cảnh Nam đảo ngọc\",\"Khám phá Thành phố không ngủ Grand World và xem show diễn triệu đô Sắc Màu Venice\",\"Tắm biển tại Bãi Sao với dải cát trắng mịn màng uốn cong hình vầng trăng khuyết\",\"Thưởng thức buffet hải sản tươi sống và món gỏi cá trích Phú Quốc trứ danh\"]','[{\"day\":1,\"title\":\"TP.HCM - Phú Quốc - Grand World - Show Sắc Màu Venice\",\"content\":\"Bay đến Phú Quốc. Xe đưa đoàn về resort 4 sao bãi Dài nhận phòng. Chiều khám phá Grand World, dạo thuyền Gondola kênh Venice, thăm Bảo tàng Gấu Teddy. Tối thưởng thức show nhạc nước ánh sáng đỉnh cao.\"},{\"day\":2,\"title\":\"Cáp Treo Hòn Thơm - Sunset Town - Cầu Hôn Kiss Bridge\",\"content\":\"Sáng đi cáp treo vượt biển sang Sun World Hòn Thơm tắm công viên nước Aquatopia. Chiều về Thị trấn Hoàng Hôn Sunset Town check-in Cầu Hôn Kiss Bridge tráng lệ. Tối dạo chợ đêm Vui Phết.\"},{\"day\":3,\"title\":\"Nhà Thùng Nước Mắm - Cơ Sở Ngọc Trai - Tiễn Bay\",\"content\":\"Khám phá quy trình ủ chượp nước mắm cá cơm Khải Hoàn trăm năm tuổi và nuôi cấy ngọc trai Phú Quốc. Xe đưa đoàn ra sân bay Phú Quốc về lại đất liền.\"}]','[\"Vé máy bay khứ hồi các hãng hàng không 4 sao có 20kg ký gửi\",\"Resort 4-5 sao mặt biển sang trọng có hồ bơi lớn\",\"Vé cáp treo Hòn Thơm khứ hồi và công viên nước Aquatopia\",\"Các bữa ăn hải sản tiêu chuẩn cao suốt hành trình\",\"Bảo hiểm du lịch toàn diện 100.000.000 VNĐ\"]','[\"Show diễn Tinh Hoa Việt Nam (ban đêm)\",\"Thuyền Gondola sông Venice (200.000đ/người)\",\"Chi tiêu cá nhân ngoài chương trình\"]','2026-10-28 15:54:14'),
(74,5,4,'Hành Trình Linh Thiêng Côn Đảo - Viếng Mộ Cô Sáu - Nghĩa Trang Hàng Dương 3N2Đ','Hành trình hướng về cội nguồn linh thiêng kết hợp nghỉ dưỡng biển hoang sơ: dâng hương viếng mộ nữ anh hùng Võ Thị Sáu vào ban đêm tại Nghĩa trang Hàng Dương, tham quan di tích Chuồng Cọp và tắm biển bãi Đầm Trầu.',6890000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',250,'2026-11-22','2026-11-24','ACTIVE',5.0,8290000.00,'Máy bay khứ hồi VASCO / Bamboo Airways',4,'LINH THIÊNG CÔN ĐẢO','[\"Nghi lễ dâng hương trang nghiêm viếng mộ Cô Sáu tại Nghĩa Trang Hàng Dương lúc 23h00 đêm\",\"Khám phá hệ thống Nhà tù Côn Đảo - \\\"Địa ngục trần gian\\\" thời Pháp - Mỹ\",\"Tắm biển Bãi Đầm Trầu tuyệt đẹp và trải nghiệm ngắm máy bay hạ cánh ngay trên bãi cát\",\"Thưởng thức hạt bàng rang muối, ốc vú nàng và cá mú đỏ nướng mọi Côn Đảo\"]','[{\"day\":1,\"title\":\"TP.HCM - Sân Bay Cỏ Ống - Đỉnh Tình Yêu - Viếng Mộ Cô Sáu\",\"content\":\"Bay đến Côn Đảo. Xe đưa đoàn về khách sạn 4 sao trung tâm thị trấn Côn Đảo. Chiều viếng Miếu Bà Phi Yến (An Sơn Miếu), ngắm cảnh Đỉnh Tình Yêu bãi Nhát. 23h00 xe đưa đoàn tham gia lễ viếng mộ Cô Sáu tại Nghĩa trang Hàng Dương.\"},{\"day\":2,\"title\":\"Di Tích Trại Phú Hải - Chuồng Cọp Pháp - Bãi Đầm Trầu\",\"content\":\"Tham quan Trại tù Phú Hải, Chuồng cọp Pháp, Chuồng cọp Mỹ, Cầu tàu 914 lịch sử. Chiều đến Bãi Đầm Trầu tắm biển trong xanh ngắm phi cơ hạ cánh sát mặt nước. Tối tự do khám phá phố đêm đảo.\"},{\"day\":3,\"title\":\"Chợ Côn Đảo Mua Đặc Sản - Tiễn Sân Bay Về TP.HCM\",\"content\":\"Dạo chợ mua mứt hạt bàng đặc sản, mực một nắng, hải sản tươi. Xe đưa đoàn ra sân bay Cỏ Ống đáp chuyến bay về lại TP.HCM.\"}]','[\"Vé máy bay khứ hồi chặng TP.HCM - Côn Đảo - TP.HCM (kèm 15-20kg hành lý)\",\"Khách sạn 4 sao sang trọng The Secret Con Dao / Marina Hotel\",\"Xe du lịch máy lạnh đưa đón viếng nghĩa trang ban đêm\",\"Bộ lễ dâng hương chu đáo chuẩn bị theo nghi thức truyền thống\",\"Bảo hiểm du lịch tối đa 100.000.000 VNĐ/khách\"]','[\"Lễ vật dâng cúng cá nhân thêm ngoài gói\",\"Đồ uống trong bữa ăn và phí giặt là\",\"Tiền tip cho hướng dẫn viên địa phương\"]','2026-10-28 15:54:14'),
(75,6,2,'Bắc Kinh - Vạn Lý Trường Thành - Tử Cấm Thành - Di Hòa Viên 5N4Đ','Khám phá thủ đô ngàn năm văn hiến Trung Hoa: chinh phục kỳ quan thế giới Vạn Lý Trường Thành hùng vĩ uốn lượn lưng chừng núi, bước vào hoàng cung Tử Cấm Thành nguy nga tráng lệ và dạo thuyền Di Hòa Viên thơ mộng.',16990000.00,5,'Hà Nội','https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=800',290,'2026-11-25','2026-11-29','ACTIVE',4.9,19990000.00,'Máy bay khứ hồi Vietnam Airlines / Air China',4,'KỲ QUAN THẾ GIỚI','[\"Đặt chân lên Vạn Lý Trường Thành - kỳ quan kiến trúc vĩ đại trường tồn cùng thời gian\",\"Tham quan Cố Cung Tử Cấm Thành - quần thể cung điện hoàng gia gỗ lớn nhất thế giới\",\"Dạo bước Di Hòa Viên - cung điện mùa hè nguy nga của Từ Hi Thái Hậu bên hồ Côn Minh\",\"Thưởng thức Vịt quay Bắc Kinh trứ danh với lớp da giòn rụm và lẩu cừu truyền thống\"]','[{\"day\":1,\"title\":\"Hà Nội - Bắc Kinh - Quảng Trường Thiên An Môn\",\"content\":\"Bay đến Bắc Kinh. Xe đón đoàn tham quan Quảng trường Thiên An Môn rộng lớn nhất thế giới. Nhận phòng khách sạn 4 sao nghỉ ngơi, thưởng thức bữa tối lẩu cừu Mông Cổ.\"},{\"day\":2,\"title\":\"Cố Cung Tử Cấm Thành - Cảnh Sơn Park\",\"content\":\"Dành trọn buổi sáng khám phá Điện Thái Hòa, Trung Hòa, Bảo Hòa và Ngự Hoa Viên trong Tử Cấm Thành. Chiều lên công viên Cảnh Sơn ngắm toàn cảnh mái ngói vàng hoàng cung.\"},{\"day\":3,\"title\":\"Vạn Lý Trường Thành (Bát Đạt Lĩnh) - Sân Vận Động Tổ Chim\",\"content\":\"Chinh phục đoạn Bát Đạt Lĩnh của Vạn Lý Trường Thành. Chiều về tham quan bên ngoài SVĐ Tổ Chim Olympic 2008 và Thủy Lập Phương lung linh về đêm.\"},{\"day\":4,\"title\":\"Di Hòa Viên - Thiên Đàn (Đàn Tế Trời) - Phố Vương Phủ Tỉnh\",\"content\":\"Khám phá Cung điện Mùa hè Di Hòa Viên và Điện Kỳ Niên tại Thiên Đàn. Tối tự do mua sắm và thưởng thức ẩm thực đường phố Vương Phủ Tỉnh sầm uất.\"},{\"day\":5,\"title\":\"Mua Sắm Đặc Sản Bắc Kinh - Tiễn Sân Bay Về Hà Nội\",\"content\":\"Mua sắm trà Long Tỉnh, ngọc bích phong thủy Bắc Kinh. Xe đưa đoàn ra sân bay thủ đô đáp chuyến bay về lại Hà Nội.\"}]','[\"Vé máy bay quốc tế khứ hồi bao gồm 23kg hành lý ký gửi\",\"Visa đoàn nhập cảnh Trung Quốc nhanh chóng\",\"Khách sạn 4 sao tiêu chuẩn quốc tế tại Bắc Kinh (2 khách/phòng)\",\"Các bữa ăn cao cấp gồm Vịt quay Bắc Kinh và lẩu cừu chính gốc\",\"Bảo hiểm du lịch quốc tế hạn mức 50.000 USD/người\"]','[\"Tiền bồi dưỡng bắt buộc cho HDV và lái xe (5 USD/ngày/khách)\",\"Chi phí làm hộ chiếu và chi tiêu mua sắm cá nhân\"]','2026-10-28 15:54:14'),
(76,6,232,'Hàn Quốc - Seoul - Đảo Nami - Công Viên Lotte World - Tháp Namsan 5N4Đ','Hành trình lãng mạn xứ sở Kim Chi: dạo bước dưới hàng cây ngân hạnh rực rỡ tại đảo Nami thiên đường của \"Bản tình ca mùa đông\", vui chơi hết mình tại Lotte World và ngắm hoàng hôn khóa tình yêu tháp Namsan.',15490000.00,5,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1517154421773-0529f29ea451?w=800',310,'2026-11-26','2026-11-30','ACTIVE',4.8,18990000.00,'Máy bay khứ hồi Vietnam Airlines / Asiana',4,'MÙA THU XỨ HÀN','[\"Khám phá Đảo Nami xinh đẹp - phim trường huyền thoại của \\\"Bản Tình Ca Mùa Đông\\\"\",\"Chinh phục Tháp Namsan Seoul Tower và gắn ổ khóa tình yêu vĩnh cửu\",\"Trải nghiệm công viên giải trí trong nhà lớn nhất thế giới Lotte World\",\"Thưởng thức ẩm thực Hàn Quốc chuẩn vị: thịt nướng Samgyeopsal, gà hầm sâm, lẩu nấm\"]','[{\"day\":1,\"title\":\"TP.HCM - Sân Bay Incheon - Khám Phá Seoul\",\"content\":\"Dáp chuyến bay đêm đến Incheon. Xe đón đoàn dùng bữa sáng súp bò tuyết ấm áp. Thăm Cung điện Gyeongbokgung cổ kính, mặc Hanbok chụp ảnh lưu niệm, thăm Nhà Xanh Blue House.\"},{\"day\":2,\"title\":\"Đảo Nami Lãng Mạn - Làng Cổ Bukchon Hanok\",\"content\":\"Đi phà sang đảo Nami dạo bước dưới hàng cây ngân hạnh vàng rực và cây linh sam thẳng tắp. Chiều về Seoul dạo phố cổ Bukchon Hanok rêu phong.\"},{\"day\":3,\"title\":\"Công Viên Lotte World - Tháp Truyền Hình Namsan\",\"content\":\"Thỏa sức trải nghiệm các trò chơi cảm giác mạnh tại Lotte World và thủy cung Aquarium. Chiều lên đỉnh Tháp Namsan ngắm toàn cảnh Seoul lung linh ánh đèn.\"},{\"day\":4,\"title\":\"Trung Tâm Nhân Sâm Chính Phủ - Phố Myeongdong\",\"content\":\"Tìm hiểu tinh hoa nhân sâm hoàng gia và mỹ phẩm nội địa Hàn Quốc. Tối tự do săn hàng hiệu và thưởng thức street food tại thiên đường Myeongdong.\"},{\"day\":5,\"title\":\"Siêu Thị Miễn Thuế - Tiễn Sân Bay Incheon Về TP.HCM\",\"content\":\"Mua sắm dâu tây Hàn Quốc, rong biển, bánh gạo kẹo sâm. Xe đưa đoàn ra sân bay Incheon làm thủ tục hoàn thuế và bay về TP.HCM.\"}]','[\"Vé máy bay khứ hồi các hãng 4-5 sao (gồm hành lý ký gửi 23kg)\",\"Phí xin visa nhập cảnh Hàn Quốc\",\"Khách sạn 4 sao tiêu chuẩn quốc tế tại thủ đô Seoul\",\"Vé vào cổng đảo Nami, Lotte World và trang phục Hanbok chụp ảnh\",\"Bảo hiểm du lịch quốc tế mức 50.000 USD\"]','[\"Tiền tip HDV và lái xe Hàn Quốc (6 USD/người/ngày)\",\"Vé lên đài quan sát kính tháp Namsan\",\"Chi phí tiêu dùng cá nhân\"]','2026-10-28 15:54:14'),
(77,7,230,'Khám Phá Bờ Tây Nước Mỹ: Los Angeles - Las Vegas - Đại Vực Grand Canyon 7N6Đ','Hiện thực hóa giấc mơ Mỹ qua những biểu tượng lẫy lừng thế giới: check-in Đại lộ danh vọng Hollywood, phim trường Universal Studios, thiên đường giải trí xa hoa Las Vegas và đại vực Grand Canyon hùng vĩ bậc nhất hành tinh.',65900000.00,7,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',200,'2026-12-01','2026-12-07','ACTIVE',4.9,75900000.00,'Máy bay quốc tế 5 sao EVA Air / ANA',4,'GIẤC MƠ NƯỚC MỸ','[\"Sải bước trên Đại lộ Danh vọng Hollywood Walk of Fame và Nhà hát Dolby lộng lẫy\",\"Khám phá Đại kỳ quan thiên nhiên thế giới - Hẻm vực khổng lồ Grand Canyon\",\"Trải nghiệm đêm không ngủ tại thủ phủ giải trí Las Vegas bên Đại lộ The Strip\",\"Thưởng thức tôm hùm Maine nướng bơ tỏi, bò bít tết Angus Mỹ hảo hạng\"]','[{\"day\":1,\"title\":\"TP.HCM - Quá Cảnh Taipei - Los Angeles (Thành Phố Thiên Thần)\",\"content\":\"Bay đến Los Angeles. Nhận phòng khách sạn 4 sao nghỉ ngơi, dạo bến tàu Santa Monica Pier lịch sử ngắm biển Thái Bình Dương.\"},{\"day\":2,\"title\":\"Hollywood Walk Of Fame - Phim Trường Universal Studios\",\"content\":\"Tham quan Đại lộ Danh vọng, Nhà hát Trung Hoa Mann\'s, Đồi Beverly Hills nơi ở của các siêu sao thế giới. Chiều khám phá phim trường Universal Studios Hollywood với các kỹ xảo điện ảnh đỉnh cao.\"},{\"day\":3,\"title\":\"Los Angeles - Sa Mạc Mojave - Las Vegas Rực Rỡ\",\"content\":\"Xe đưa đoàn xuyên qua sa mạc Mojave đến Las Vegas. Check-in khách sạn Bellagio / Caesars Palace. Tối dạo bước ngắm đài phun nước Bellagio và quả cầu ánh sáng MSG Sphere.\"},{\"day\":4,\"title\":\"Đại Vực Grand Canyon - Đập Thủy Điện Hoover Dam\",\"content\":\"Khám phá kỳ quan hẻm vực Grand Canyon sừng sững qua hàng triệu năm kiến tạo địa chất. Chiêm ngưỡng đập thủy điện Hoover Dam đồ sộ và hồ Mead trong xanh.\"},{\"day\":5,\"title\":\"Las Vegas - Mua Sắm Hàng Hiệu Premium Outlets\",\"content\":\"Thỏa sức săn hàng hiệu giảm giá tại Las Vegas North Premium Outlets: Coach, Michael Kors, Nike, Tommy Hilfiger với mức sale khủng.\"},{\"day\":6,\"title\":\"Los Angeles - Little Saigon - Tiễn Sân Bay LAX\",\"content\":\"Ghé thăm khu Little Saigon Phước Lộc Thọ thưởng thức ẩm thực Việt kiều. Chiều ra sân bay quốc tế Los Angeles đáp chuyến bay về Việt Nam.\"},{\"day\":7,\"title\":\"Quá Cảnh - Về Đến Sân Bay Tân Sơn Nhất TP.HCM\",\"content\":\"Đến sân bay Tân Sơn Nhất, hoàn tất thủ tục nhập cảnh. Kết thúc tour khám phá nước Mỹ tráng lệ.\"}]','[\"Vé máy bay quốc tế khứ hồi các hãng 5 sao kèm 2 kiện hành lý 23kg\",\"Thư mời bảo lãnh visa Mỹ và hỗ trợ luyện phỏng vấn 1 kèm 1\",\"Khách sạn 4-5 sao chuẩn Mỹ tại trung tâm Los Angeles và Las Vegas\",\"Vé vào cổng Đại vực Grand Canyon và phim trường Universal Studios\",\"Bảo hiểm du lịch quốc tế hạn mức bồi thường 100.000 USD\"]','[\"Lệ phí phỏng vấn visa Mỹ (nộp Đại sứ quán: 185 USD)\",\"Tiền tip HDV và lái xe địa phương (10 USD/người/ngày)\",\"Trực thăng ngắm cảnh Grand Canyon hoặc Skywalk kính\"]','2026-10-28 15:54:14'),
(78,7,231,'Tour Châu Úc: Sydney - Melbourne - Nhà Hát Con Sò Opera House 6N5Đ','Chinh phục xứ sở chuột túi tươi đẹp: chiêm ngưỡng biểu tượng Nhà hát Con Sò Sydney Opera House, ngắm toàn cảnh vịnh cảng từ Cầu Cảng Sydney Harbour, khám phá thung lũng rượu vang Yarra Valley và cung đường Great Ocean Road.',48900000.00,6,'Hà Nội','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800',220,'2026-12-05','2026-12-10','ACTIVE',4.9,56900000.00,'Máy bay quốc tế Vietnam Airlines Boeing 787',4,'XỨ SỞ CHUỘT TÚI','[\"Check-in biểu tượng thế giới Nhà Hát Con Sò Sydney Opera House và Cầu Cảng Sydney\",\"Chinh phục cung đường ven biển đẹp nhất hành tinh Great Ocean Road và Mười Hai Vị Tông Đồ\",\"Tương tác gần gũi và chụp ảnh cùng những chú Kangaroo và Gấu Koala đáng yêu\",\"Thưởng thức rượu vang thượng hạng Yarra Valley và món bò Wagyu nướng sốt nấm\"]','[{\"day\":1,\"title\":\"Hà Nội - Bay Thẳng Đến Thành Phố Cảng Sydney\",\"content\":\"Đoàn tập trung tại sân bay Nội Bài đáp chuyến bay thẳng của Vietnam Airlines đi Sydney. Nghỉ đêm trên máy bay tiêu chuẩn 4 sao.\"},{\"day\":2,\"title\":\"Khám Phá Sydney - Nhà Hát Con Sò - Du Thuyền Vịnh Cảng\",\"content\":\"Hạ cánh Sydney. Tham quan Sydney Opera House, dạo bước khu phố cổ The Rocks, ghé Ghế đá Quý bà Macquarie ngắm vịnh. Ăn trưa buffet trên du thuyền ngắm Sydney Harbour.\"},{\"day\":3,\"title\":\"Công Viên Động Vật Hoang Dã Featherdale - Blue Mountains\",\"content\":\"Thăm công viên bảo tồn thú hoang dã Featherdale chụp hình cùng Koala và cho Kangaroo ăn. Chiều đi cáp treo ngắm dãy núi xanh Blue Mountains và mỏm đá Ba Chị Em huyền thoại.\"},{\"day\":4,\"title\":\"Sydney - Bay Nội Địa Đi Melbourne - Phố Nghệ Thuật Graffiti\",\"content\":\"Bay sang thành phố nghệ thuật Melbourne. Dạo bước ngõ hẻm tranh tường Hosier Lane, thăm Nhà thờ thánh Patrick và Vườn bách thảo hoàng gia Royal Botanic Gardens.\"},{\"day\":5,\"title\":\"Cung Đường Ven Biển Great Ocean Road - Mười Hai Tông Đồ\",\"content\":\"Khám phá cung đường Great Ocean Road uốn lượn ven biển Nam Đại Dương. Chiêm ngưỡng các cột đá vôi khổng lồ Twelve Apostles sừng sững giữa sóng bạc.\"},{\"day\":6,\"title\":\"Mua Sắm Queen Victoria Market - Bay Về Lại Hà Nội\",\"content\":\"Mua sắm kem dưỡng nhau thai cừu, mật ong Manuka tại chợ Nữ Hoàng Victoria. Xe tiễn đoàn ra sân bay Melbourne đáp chuyến bay về lại Hà Nội.\"}]','[\"Vé máy bay khứ hồi quốc tế & chặng nội địa Úc (Sydney - Melbourne)\",\"Thư mời và phí visa nhập cảnh Australia điện tử\",\"Khách sạn 4 sao trung tâm Sydney và Melbourne\",\"Du thuyền ngắm vịnh cảng Sydney có phục vụ buffet trưa\",\"Bảo hiểm du lịch quốc tế toàn cầu mức 100.000 USD\"]','[\"Tiền tip HDV và lái xe bản địa (8 USD/người/ngày)\",\"Phí dịch thuật và công chứng hồ sơ cá nhân\",\"Chi tiêu cá nhân ngoài thực đơn\"]','2026-10-28 15:54:14'),
(79,8,3,'Kỳ Nghỉ Thượng Lưu Amanoi Vĩnh Hy Ninh Thuận - Biệt Thự Hướng Vịnh 3N2Đ','Kỳ nghỉ tĩnh dưỡng xa xỉ tại khu nghỉ dưỡng 6 sao đắt giá nhất Việt Nam Amanoi: villa riêng biệt ôm trọn vịnh Vĩnh Hy thơ mộng, hồ bơi vô cực trên vách đá, quản gia riêng 24/7 và liệu trình Spa Hydrotherapy đỉnh cao.',42500000.00,3,'TP. Hồ Chí Minh','https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=800',210,'2026-12-08','2026-12-10','ACTIVE',5.0,48500000.00,'Xe Mercedes-Benz Maybach đón tiễn & Vé máy bay Hạng Thương Gia',5,'SIÊU SANG TRỌNG','[\"Nghỉ dưỡng tại Amanoi Resort 6 sao - Top 33 khu nghỉ dưỡng tốt nhất hành tinh\",\"Biệt thự Pavilion riêng biệt view toàn cảnh vịnh Vĩnh Hy và vườn quốc gia Núi Chúa\",\"Thưởng thức đại tiệc nướng BBQ hải sản cao cấp tư gia bên hồ bơi riêng biệt\",\"Liệu trình chăm sóc sức khỏe Spa Thủy Liệu Pháp Hydrotherapy độc quyền Aman\"]','[{\"day\":1,\"title\":\"TP.HCM - Bay Thương Gia Đến Cam Ranh - Maybach Về Amanoi\",\"content\":\"Bay hạng thương gia Vietnam Airlines đến Cam Ranh. Xe riêng Mercedes Maybach đón đoàn về Amanoi Resort Vĩnh Hy. Nhận biệt thự riêng tư, thưởng thức trà chiều thượng hạng ngắm hoàng hôn vịnh biển.\"},{\"day\":2,\"title\":\"Du Thuyền Riêng Ngắm Vịnh Vĩnh Hy - Spa Trị Liệu Aman\",\"content\":\"Sáng trải nghiệm du thuyền tư nhân lướt vịnh ngắm các rạn san hô nguyên sinh. Chiều tận hưởng liệu trình spa hồi phục năng lượng độc bản. Tối thưởng thức bữa tối lãng mạn dưới ánh nến tại nhà hàng vách đá The Restaurant.\"},{\"day\":3,\"title\":\"Yoga Đón Bình Minh Trên Vách Núi - Tiễn Sân Bay Về TP.HCM\",\"content\":\"Tham gia lớp Yoga thiền định buổi sáng tại hồ sen thanh tịnh. Thưởng thức bữa trưa tinh tế. Xe Maybach tiễn đoàn ra sân bay Cam Ranh về lại TP.HCM.\"}]','[\"Vé máy bay Hạng Thương Gia (Business Class) khứ hồi\",\"Xe riêng hạng sang Mercedes Maybach đón tiễn sân bay Cam Ranh - Amanoi\",\"2 đêm nghỉ tại Biệt thự Ocean Pavilion view vịnh Vĩnh Hy\",\"Quản gia riêng phục vụ 24/7 và bữa ăn thượng hạng theo menu bếp trưởng Michelin\",\"1 liệu trình Spa Thủy Liệu Pháp cao cấp 90 phút/khách\"]','[\"Rượu vang cao cấp danh mục Grand Cru vintage\",\"Dịch vụ trực thăng đón tiễn theo yêu cầu riêng\",\"Chi tiêu mua sắm ngoài danh mục phục vụ của resort\"]','2026-10-28 15:54:14'),
(80,8,4,'Du Thuyền 6 Sao Ambassador Cruise Vịnh Lan Hạ - Trực Thăng Ngắm Cảnh 3N2Đ','Hải trình quý tộc trên siêu du thuyền Ambassador lớn nhất Vịnh Hạ Long - Lan Hạ: trải nghiệm ngắm vịnh di sản từ trực thăng Bell 505 hiện đại, phòng Suite có ban công riêng view kỳ quan triệu năm và tiệc tôm hùm không giới hạn.',21900000.00,3,'Hà Nội','https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800',230,'2026-12-12','2026-12-14','ACTIVE',4.9,26900000.00,'Xe Limousine President & Du thuyền 6 sao & Trực thăng Bell 505',5,'DU THUYỀN 6 SAO','[\"Bay trực thăng ngắm toàn cảnh Vịnh Hạ Long - kỳ quan thiên nhiên thế giới từ trên cao\",\"Trải nghiệm 2 đêm trên Siêu Du Thuyền 6 Sao Ambassador với bể sục Jacuzzi ngoài trời cực đại\",\"Cabin hạng Tổng thống Presidential Suite với ban công kính 360 độ ngắm vịnh\",\"Đại tiệc Buffet Tôm Hùm không giới hạn và nhạc Jazz acoustic sống động hàng đêm\"]','[{\"day\":1,\"title\":\"Hà Nội - Trực Thăng Ngắm Vịnh - Lên Du Thuyền Ambassador\",\"content\":\"Xe Limousine President đón khách từ Hà Nội đến cảng quốc tế Tuần Châu. Trải nghiệm bay trực thăng Bell 505 ngắm trọn vẹn vịnh Hạ Long. Lên du thuyền Ambassador thưởng thức cocktail chào mừng và nhận phòng Suite cao cấp.\"},{\"day\":2,\"title\":\"Vịnh Lan Hạ - Hang Sáng Tối - Chèo Thuyền Kayak - Tiệc Sunset\",\"content\":\"Tập Thái Cực Quyền đón bình minh. Chèo thuyền kayak len lỏi qua Hang Sáng Tối khám phá đầm phá biệt lập giữa biển. Chiều tham gia lớp học nấu ăn và tiệc Sundowner Party tại quầy bar tầng thượng.\"},{\"day\":3,\"title\":\"Hang Sửng Sốt - Đảo Ti Tốp - Trở Về Thủ Đô Hà Nội\",\"content\":\"Thăm Hang Sửng Sốt kỳ vĩ hoặc chinh phục đỉnh đảo Ti Tốp ngắm bao quát vịnh. Dùng bữa trưa buffet sớm trên du thuyền trong khi tàu cập bến Tuần Châu. Xe Limousine đưa đoàn về lại Hà Nội.\"}]','[\"Xe Limousine President cao cấp đón tiễn khứ hồi Hà Nội - Hạ Long\",\"Vé bay trực thăng ngắm cảnh 12 phút cùng phi công chuyên nghiệp\",\"2 đêm nghỉ phòng Ambassador Suite có ban công riêng biệt view vịnh\",\"Trọn gói các bữa ăn Michelin và tiệc hải sản tôm hùm không giới hạn\",\"Bảo hiểm du thuyền cao cấp mức bồi thường 150.000.000 VNĐ\"]','[\"Đồ uống có cồn nhập khẩu tại Sunset Bar\",\"Dịch vụ massage spa trị liệu trên du thuyền\",\"Chi tiêu quà lưu niệm cá nhân\"]','2026-10-28 15:54:14');
